-- 0067_sync_card_content_to_db.sql
-- Sync full 镜鉴 card content (lesson/witness/summary/prayer + follow/caution/
-- applications/scriptures/tags) from the frontend mirrorData.js into the DB for
-- every migration-added person, replacing the placeholder text from 0064-0066.
-- Embedded JSON + set-based UPDATE/INSERT. Idempotent (NOT EXISTS / ON CONFLICT).

CREATE TEMP TABLE _card_sync ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($json$[{"name": "罗得的妻子", "lesson": "回头看是对神命令最致命的不顺服", "witness": "命令只有一个：不要回头看。她回头了。圣经没有解释为什么——是留恋？是好奇？是不舍？无论是什么，那一回头终结了一切。神的命令不需要理由，只需要顺服。耶稣说：你们要回想罗得的妻子——这句话跨越了几千年，仍然在问我们：你的心在哪里？", "summary": "在逃离所多玛时被天使明确命令不许回头，却在逃跑途中回头看，立刻变成盐柱。耶稣自己引用她作为警戒：你们要回想罗得的妻子。", "prayer": "主，罗得的妻子一回头就失去了一切。帮助我在你说不要回头的地方，有彻底告别旧生活的勇气，不只是身体离开，更是心完全转向前方。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["在明确命令面前仍然回头看", "心中仍然留恋即将被审判的生活", "表面逃离，内心未曾离开"], "applications": ["你是否在离开某些旧生活、旧罪时，心里仍然回头看？", "「不要回头」不只是身体的方向，更是心的方向", "耶稣说记念罗得的妻子——今天你的心在哪里？"], "scriptures": ["创19:17", "创19:26", "路17:31-33"]}, {"name": "以挪士", "lesson": "那时候人开始求告耶和华的名", "witness": "以挪士是塞特的儿子、亚当敬虔后裔的一环。圣经在记下他出生时特别说：那时候人才求告耶和华的名。在该隐线日趋败坏之际，这一支却兴起了公开敬拜、呼求神的传统。", "summary": "以挪士是塞特之子、亚当之孙。圣经记载「那时，人才求告耶和华的名」，标志着公开敬拜与呼求神的开始，是敬虔后裔的延续。", "prayer": "主啊，以挪士的世代开始公开求告祢的名。求祢使我在冷淡的时代里带头敬拜祢，把呼求祢的传统传给后代。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在普遍的属灵冷淡中，带头求告神的名", "承接并延续家族敬虔的传统"], "caution": ["不让世代的流逝冲淡对神的呼求"], "applications": ["在信仰冷淡的环境中，带头敬拜、祷告", "看重并传承家中呼求神的传统", "让'求告耶和华的名'成为你日常的习惯"], "scriptures": ["创4:26", "创5:6-11"]}, {"name": "以诺", "lesson": "与神同行，蒙神喜悦", "witness": "以诺在那充满'就死了'的家谱中是个例外：他与神同行三百年，神将他取去，他就不在世了。希伯来书说，他得了'神喜悦他'的明证。与神亲密同行的人，连死亡的定律都被改写。", "summary": "以诺与神同行三百年，神将他取去，他就不在世了，未尝死味。希伯来书称他「得了神喜悦他的明证」，是与神亲密相交、胜过死亡的见证人。", "prayer": "主啊，以诺与祢同行，祢就把他取去。求祢吸引我与祢亲密同行，一生讨祢喜悦，在这世代中作与祢同行的见证。阿们。", "tags": ["其他", "正面榜样"], "follow": ["与神保持亲密、持续的同行", "一生讨神的喜悦，作时代的见证"], "caution": ["不让世务与年日冲淡与神同行的亲密"], "applications": ["把'与神同行'当作每日的实际，而非口号", "在败坏的世代中持守讨神喜悦的生活", "相信与神亲密的人，神必亲自看顾到底"], "scriptures": ["创5:21-24", "来11:5", "犹14-15"]}, {"name": "闪", "lesson": "承接祝福的一支", "witness": "闪是挪亚的长子。挪亚醉酒事件后，他与雅弗倒退着进去遮盖父亲的赤身，不看父亲的羞辱；挪亚便祝福闪，称'耶和华闪的神是应当称颂的'。这一支后来连于亚伯拉罕、连于救恩的谱系。", "summary": "挪亚的儿子，与雅弗一同尊重父亲而蒙福。挪亚祝福说「耶和华闪的神是应当称颂的」，敬虔后裔的线由闪承接，亚伯拉罕从闪而出。", "prayer": "主啊，闪以敬重遮盖父亲的羞辱，承接了祝福。求祢使我以敬重和爱遮盖他人的软弱，珍惜并传承祢所赐的福。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以敬重遮盖长辈的羞辱，不张扬", "承接并珍惜神所赐的祝福"], "caution": ["不效法含的轻看，要存敬重的心"], "applications": ["不传扬、不嘲笑他人（尤其长辈）的失态", "以遮盖和敬重待人", "珍惜并守护神所赐家族的属灵祝福"], "scriptures": ["创9:26-27", "创11:10-26", "路3:36"]}, {"name": "基善", "lesson": "联手散谣，拦不住神的工", "witness": "基善（又名迦施慕）是阿拉伯人首领，与参巴拉、多比雅联手，先嗤笑、后恐吓，又散布'你想造反'的谣言，百般阻挠尼希米修墙。然而墙仍在五十二天内修成——人的联手与谣言，拦不住神所定的工。", "summary": "基善是阿拉伯人首领，与参巴拉、多比雅同谋讥诮尼希米，造谣说犹大人修墙是要背叛王，并参与诱骗尼希米到平原会面的暗害计划，终未得逞。", "prayer": "主啊，基善联手造谣阻挠修墙，城墙却照样建成。求祢使我不参与嗤笑造谣，遇拦阻时专心做工，深信祢的工无人能拦。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["联手嗤笑、恐吓、造谣，阻挠神的工作", "以舆论与谣言打击行善的人"], "applications": ["不参与嗤笑、造谣、打击行善者的事", "遇阻挠时专心做工，不被谣言牵动", "相信神的工不被人的联手拦阻"], "scriptures": ["尼2-6"]}, {"name": "押尼珥", "lesson": "才干若无对神的忠诚，终必落空", "witness": "押尼珥是个有能力、有影响力的人——他几乎以一己之力维系了扫罗王朝，又有能力把整个以色列带到大卫面前。但他的忠诚始终是对人、对权力，而非对神的旨意；他早知神已拣选大卫，却为利益拥立伊施波设多年。当他终于归向大卫，却死于宿怨。他的一生提醒：恩赐与政治手腕若不臣服于神的旨意，再大的才干也只换来一声叹息——「押尼珥死，岂如愚顽人死吗？」", "summary": "扫罗的元帅，扫罗死后立伊施波设为王，后转投大卫，却在希伯仑被约押报私仇杀害。", "prayer": "主啊，押尼珥有才干却迟迟不顺服祢的旨意。求祢使我不效忠于权力或人，乃单单忠于祢的呼召；让我的恩赐都臣服在祢的旨意之下。阿们。", "tags": ["其他", "混合型"], "follow": ["有担当、有领导力，能凝聚人心", "最终愿意承认并顺服神所膏立的王"], "caution": ["明知神的旨意，却为私利拖延顺服", "效忠于权力与人，而非神的呼召"], "applications": ["把你的才干与影响力交给神，问祂要你如何使用", "不要明知神的心意却为利益拖延", "及早归向正确的一方，不要等到代价更大", "在纷争中寻求和好，也要防备旧怨的反扑"], "scriptures": ["撒下2:8-9", "撒下3:9-10", "撒下3:27", "撒下3:33-34"]}, {"name": "米甲", "lesson": "爱若失去对神的敬畏，会变成轻看", "witness": "米甲起初真心爱大卫，甚至违抗父王、用计救他逃生。但岁月、被夺来送去的婚姻创伤、以及对王室体面的看重，使她的心渐渐冷却。当大卫在约柜前忘形敬拜，她从窗户里望见，「就心里藐视他」。她代表了一种危险：曾经的爱可以退化成对属灵热情的冷眼与讥讽。她最终无子，在敬拜的事上与丈夫两隔。", "summary": "扫罗的女儿，大卫的妻子，曾冒险救大卫逃命，后来却因大卫在约柜前踊跃跳舞而心里藐视他。", "prayer": "主啊，求祢保守我起初爱祢的心，不因伤害与世故而变冷；当别人为祢火热敬拜时，让我一同欢喜，而不是站在窗后藐视。阿们。", "tags": ["女性", "混合型"], "follow": ["曾以勇气和机智保护神所膏立的人"], "caution": ["让创伤与体面取代了起初的爱", "轻看别人单纯火热的敬拜", "以世俗的尊严衡量属灵的事"], "applications": ["守护起初的爱，别让岁月与伤害使心变冷", "不要讥讽别人对神单纯的热情", "在神面前敬拜时不顾及人的眼光", "处理内心的苦毒，免得它毒害最亲的关系"], "scriptures": ["撒上19:11-17", "撒下6:16", "撒下6:20-23"]}, {"name": "暗嫩", "lesson": "放纵的私欲终必反噬自己", "witness": "暗嫩的故事是情欲完整轨迹的标本：起初是「忧急成病」的迷恋，接着用诡计与强暴满足私欲，而欲望一旦得逞，「极其恨她，这恨比先前的爱更甚」。他把人当作满足自己的对象，事后弃如敝屣。罪没有被处理，埋下两年的仇恨，最终在筵席上要了他的命。纵欲不会带来满足，只会带来更深的空虚与毁灭。", "summary": "大卫的长子，因情欲玷辱同父异母的妹妹他玛，两年后被押沙龙设计杀害。", "prayer": "主啊，暗嫩放纵私欲，毁了他玛也毁了自己。求祢洁净我的心思意念，叫我尊重人、约束己，在试探面前选择逃避而非筹算。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["把迷恋当作爱，实则是自我中心的占有", "用诡计与强迫满足私欲", "得逞后由「爱」转为憎恨，显明从无真爱", "犯罪后不悔改，任凭后果发酵"], "applications": ["识破「忧急成病」的迷恋，它往往是私欲而非爱", "在试探临到时立刻远离，不给它布局的机会", "尊重他人为有神形像的人，而非满足自己的工具", "犯错后立即认罪处理，不让罪埋下更大的祸根"], "scriptures": ["撒下13:1-2", "撒下13:14-15", "撒下13:28-29"]}, {"name": "耶西", "lesson": "神看的与人看的不一样", "witness": "撒母耳来膏王时，耶西让七个高大健壮的儿子一一经过，唯独把最小的、在野地放羊的大卫忘在外头。神却说：「不要看他的外貌……因为耶和华不像人看人；人是看外貌，耶和华是看内心。」耶西是「被忽略之处」的象征——神的拣选常常落在人所轻看、所遗漏的那一个身上。这个不起眼的伯利恒之家，后来成了大卫之家、弥赛亚之家。", "summary": "伯利恒人，波阿斯与路得的后代，大卫的父亲，弥赛亚谱系的关键一环。", "prayer": "主啊，祢从耶西被忽略的小儿子中兴起了大卫，又从这一家带来了救主。求祢赐我祢看人的眼光，不凭外貌，珍视祢所拣选的。阿们。", "tags": ["其他", "正面榜样"], "follow": ["养育了合神心意的大卫", "谦卑务实，持守在伯利恒的家业", "成为弥赛亚谱系蒙恩的一环"], "caution": ["险些以外貌与排行衡量神的拣选，忽略了最小的儿子"], "applications": ["不要以外貌、成绩或排行论断身边的人", "看重并栽培那些被别人忽略的人", "相信神能从最不起眼之处兴起祂的工作", "在平凡的本分中忠心，神的计划常藏在其中"], "scriptures": ["撒上16:1", "撒上16:7", "撒上16:11-13", "得4:17"]}, {"name": "大利拉", "lesson": "为利益出卖关系，终必两败", "witness": "大利拉把亲密关系变成了交易。非利士首领许她银子，她便日复一日地缠磨参孙：「你心里既不向我，怎么说你爱我呢？」她用爱的语言行出卖的事，直到参孙「心里烦闷要死」，说出实情。她代表了把信任当作筹码、为利益出卖至亲的人。讽刺的是，参孙的失败也有他自己的责任——他一再把心交给不该交的人。", "summary": "非利士人收买的女子，以柔情反复套问参孙力量的秘密，最终使他被擒。", "prayer": "主啊，大利拉为银钱出卖了信任她的人。求祢使我以诚实和忠贞待人，不因利益出卖关系；也求祢赐我警醒，不把心交给会害我的事物。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["以爱为名，行出卖之实", "为银钱牺牲他人的安危", "利用对方的信任与软弱下手"], "applications": ["察验那些不断打探你软弱与底线的关系", "不要因情感的缠磨而交出不该交的东西", "以诚实经营关系，不把信任当筹码", "在亲密关系中也要有属灵的警醒"], "scriptures": ["士16:5", "士16:15-17", "士16:18-21"]}, {"name": "亚希米勒", "lesson": "善待神的仆人，可能付上代价", "witness": "亚希米勒做的是一件良善的事——接待并供应一个落难的、神所膏立的人。他并不知道自己卷入了王室的猜忌。扫罗听信多益的告发，不容分说，把挪伯八十五位祭司连同全城尽行杀灭。亚希米勒的遭遇提醒我们：行善有时会招来无理的祸患；但他的儿子亚比亚他逃到大卫那里，神的祭司职分得以延续。义人的善行，神不会忘记。", "summary": "挪伯的祭司，在大卫逃难时供给他陈设饼与歌利亚的刀，后被扫罗迁怒、由多益下手杀害，全城祭司同遭屠戮。", "prayer": "主啊，亚希米勒因善待祢的仆人而付上性命的代价。求祢赐我怜悯接待人的心，即使行善有风险也不退缩，深信祢必记念并保守义人的后裔。阿们。", "tags": ["祭司", "正面榜样"], "follow": ["慷慨接待并供应落难中神的仆人", "坦荡无伪，问心无愧地申诉"], "caution": [], "applications": ["以怜悯接待落难、有需要的人", "行善时也要有智慧，知道可能的风险", "在被冤枉时坦然申辩，把结果交给神", "记得善行的影响会延续到下一代"], "scriptures": ["撒上21:6", "撒上22:14-15", "撒上22:18-20"]}, {"name": "多益", "lesson": "逢迎权势的舌头能杀人", "witness": "当扫罗的臣仆都不肯伸手杀耶和华的祭司，多益却毫不犹豫地动手，杀了八十五人和全城的人。他是逢迎权势、以他人鲜血换取自己地位的典型。诗篇52篇正是为他而写：「勇士啊，你为何以作恶自夸？……你的舌头邪恶诡诈，好像剃头刀。」他显出一个真理：愿意为讨好掌权者而作恶的人，何等可怕。", "summary": "以东人，扫罗的司牧长，告发挪伯祭司接待大卫，并亲手执行扫罗的屠杀令。", "prayer": "主啊，多益用舌头与刀为权势作恶。求祢洁净我的口，使我不告密构陷、不为讨好人而伤害人；赐我在众人作恶时不同流合污的勇气。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["为讨好权势而告密、构陷他人", "在众人都不肯作恶时，抢着动手", "以他人的苦难换取自己的晋升"], "applications": ["不做逢迎权势、出卖他人的告密者", "当众人作恶时，要有不参与的勇气", "看守自己的舌头，它能造就也能杀人", "记得神必追讨流无辜人血的罪"], "scriptures": ["撒上22:9-10", "撒上22:18", "诗52:1-4"]}, {"name": "瓦实提", "lesson": "在权势的羞辱前，尊严也有代价", "witness": "瓦实提被召，是要在七日酒宴的尾声、众人喝醉时出来「显她的美貌」。她拒绝了。圣经没有明说她的动机，但她守住了不被当作玩物展示的底线。她为此失去后位。她的退场为以斯帖的登场预备了道路——神的主权在人的决定与失败之上运行。瓦实提提醒：守住尊严有时要付代价，而神能使一个人的退场成为另一段救恩故事的开端。", "summary": "波斯王亚哈随鲁的王后，在王酒酣时拒绝出来给醉酒的群臣观看其美貌，因而被废。", "prayer": "主啊，瓦实提在羞辱面前守住了尊严，也为以斯帖的兴起预备了道路。求祢赐我在被轻看时仍有为人的体面，并深信祢的主权运行在一切变迁之上。阿们。", "tags": ["女性", "混合型"], "follow": ["在被当作玩物展示时，守住了为人的尊严"], "caution": ["在专横的权力前，个人的立场常被无情碾压"], "applications": ["在被物化、被羞辱时，持守为人的尊严", "明白守住底线有时要付上代价", "相信神的主权在人事变迁、甚至失势之上运行", "为身处权力压迫中的人祷告"], "scriptures": ["斯1:11-12", "斯1:19", "斯2:17"]}, {"name": "基大利", "lesson": "良善若无警醒，也会招致祸患", "witness": "基大利是亡国废墟上一线温和的希望。他劝余民安居、服事巴比伦、必得平安。他心地良善，却也因此天真——约哈难警告他以实玛利受亚扪王指使要来行刺，他却不信，反而款待。结果在筵席上被杀，残存的犹大群体也随之溃散逃亡。他的悲剧提醒：良善需要配上警醒与分辨，否则善意也可能酿成更大的灾难。", "summary": "犹大亡国后巴比伦所立的省长，治理温和，却因不信以实玛利会行刺的警告而被杀。", "prayer": "主啊，基大利心地良善却疏于防备，以致良政夭折。求祢赐我既温柔又警醒的智慧，以善待人却不天真，认真对待该听的警告。阿们。", "tags": ["其他", "混合型"], "follow": ["在废墟中安抚余民，劝人安居乐业", "为政温和，愿意给人出路"], "caution": ["对明确的危险警告掉以轻心", "以善意取代了必要的分辨与防备"], "applications": ["以良善待人，但也要有分辨与警醒", "对可信的警告认真对待，不要一味乐观", "在动荡中给人盼望，却不天真", "求神赐你既善良又精明的智慧"], "scriptures": ["王下25:24", "耶40:14-16", "耶41:1-2"]}, {"name": "西拿基立", "lesson": "在永生神面前夸口，必自取羞辱", "witness": "西拿基立横扫列国，以为耶和华不过是各国神明中的一个：「列国的神有哪一个救了自己的国脱离我的手呢？」他把对人的得胜当作可以胜过神的资本。希西家把他羞辱神的信铺在耶和华面前祷告，神藉以赛亚回答：「你向谁辱骂亵渎？……乃是向以色列的圣者。」当夜耶和华的使者出去，亚述全营尸横遍野。骄傲在永生神面前，是最危险的愚妄。", "summary": "亚述王，围攻耶路撒冷，藉拉伯沙基狂言羞辱耶和华，一夜之间军中被天使击杀十八万五千人。", "prayer": "主啊，西拿基立向永生神夸口，一夜之间全军覆没。求祢使我远离成功带来的骄傲，在威吓面前单单仰望祢；因为得胜在乎祢，不在乎人的势力。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以连续的得胜滋生狂妄，自高过神", "公然亵渎、轻看永生的神", "倚靠武力与威吓，不知有在上掌权者"], "applications": ["不要因一连串成功而目中无神", "遇威吓恐吓时，学希西家把难处摊在神面前祷告", "记得人的权势在神面前不堪一击", "警惕成功带来的属灵骄傲"], "scriptures": ["王下18:33-35", "王下19:14-19", "王下19:35-37"]}, {"name": "哈薛", "lesson": "否认心中的恶，不等于不会去行", "witness": "以利沙定睛看着哈薛直到他惭愧，然后哭了。哈薛问：「你仆人算什么，不过是一条狗，怎能行这大事呢？」他无法想象自己会做出屠城、剖孕妇的暴行。然而第二天他就用湿被子闷死了主人，夺了王位。哈薛的可怕在于：他真心以为自己不会变成那样的人，却一步步成了那样的人。我们都需要警惕——今日所否认的恶，可能正是明日所行的事。", "summary": "亚兰的臣仆，以利沙含泪预言他将作王并残害以色列；他闷死便哈达篡位，果然成了以色列的大患。", "prayer": "主啊，哈薛否认心中的恶，却终究行了出来。求祢光照我里面隐藏的败坏，使我不自欺、不被权力与野心吞吃，靠祢的恩典守住己心。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以「我绝不会那样」自欺，低估自己心中的恶", "为权位不择手段，弑主篡位", "掌权后行出曾经无法想象的残暴"], "applications": ["不要轻易说「我绝不会」，要警惕自己心中的恶", "掌握权力时尤其要防备它放大人的败坏", "让神的话与信任的人持续光照你的内心", "在野心萌动时及早对付，不给它生长的空间"], "scriptures": ["王下8:12-13", "王下8:15", "王下10:32"]}, {"name": "加百列", "lesson": "忠心传递神的话，不增不减", "witness": "加百列是神的信使，「站在神面前」的那一位。他向撒迦利亚宣告施洗约翰的出生，向马利亚宣告基督的降生：「在神没有难成的事。」他忠实地传递神的话语，不增添、不删减，也带着安慰：「不要害怕，马利亚，你在神面前已经蒙恩了。」加百列代表一切忠心事奉、单纯顺服、把神的话准确传开的人——伟大不在于自己有多重要，而在于所传的是谁的信息。", "summary": "侍立在神面前的天使，向但以理、撒迦利亚和马利亚传递神的信息，宣告救恩计划的关键时刻。", "prayer": "主啊，加百列忠心传递祢的话，带下安慰与盼望。求祢使我也作祢忠实的信使，准确传讲祢的真理，以祢的话安慰惧怕的人，深信在祢没有难成的事。阿们。", "tags": ["其他", "正面榜样"], "follow": ["忠心准确地传递神的信息，不增不减", "以「不要害怕」安慰领受信息的人", "完全顺服神的差遣"], "caution": [], "applications": ["传讲神的话时忠于原意，不夹带私意", "在事奉中甘居幕后，让神的信息居首位", "以神的话安慰惧怕中的人", "相信「在神没有难成的事」"], "scriptures": ["路1:13-17", "路1:19", "路1:26-38"]}, {"name": "亚利马太的约瑟", "lesson": "在关键时刻公开站在主一边", "witness": "亚利马太的约瑟原本「因怕犹太人，就暗暗地作门徒」。但在主被钉、众门徒四散的至暗时刻，他反倒「放胆」去见彼拉多，求耶稣的身体，献上自己的新坟墓。当跟随的代价最高、最危险时，这个隐藏的门徒站了出来。他提醒我们：信仰终究要从隐秘走向公开，而神往往在最艰难的时刻呼召我们勇敢表明立场。", "summary": "犹太公会的议士，暗暗作耶稣门徒，在主受死后挺身求取遗体，将其安葬在自己的新坟墓里。", "prayer": "主耶稣，亚利马太的约瑟在祢受难时放胆站出，献上最好的安葬祢。求祢使我不再暗暗跟随，乃在关键时刻公开承认祢，把最好的献给祢。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在最危险的时刻放胆承认主", "慷慨献上自己最好的（新坟墓）安葬主", "从暗暗作门徒走向公开站立"], "caution": ["曾因惧怕而长期隐藏信仰，迟迟不敢公开承认"], "applications": ["让你的信仰从隐秘走向公开的承认", "在别人退缩时，正是你站出来的时候", "把自己最好的献给主", "数算跟随主的代价，并甘心付上"], "scriptures": ["太27:57-60", "可15:43", "约19:38-42"]}, {"name": "迦玛列", "lesson": "在未明之事上，给神留出空间", "witness": "当公会怒气填胸要杀使徒，迦玛列站起来，以历史为鉴劝众人冷静：「这事若是出于人，必要败坏；若是出于神，你们就不能败坏他们，恐怕你们倒是攻击神了。」这是难得的审慎与敬畏——在尚未看清的事上，不急于用强力压制，而给神的作为留出空间。他虽未必信主，却保护了初代教会，也教导出后来的保罗。智慧有时表现为克制。", "summary": "公会中德高望重的法利赛教法师，保罗的老师；在公会要杀使徒时，劝众人谨慎，任凭其发展看是否出于神。", "prayer": "主啊，迦玛列在风暴中以审慎敬畏的心给祢的作为留出空间。求祢赐我同样的智慧与谦卑，在未明之事上不妄下论断，免得无意中抵挡了祢。阿们。", "tags": ["其他", "混合型"], "follow": ["在群情激愤时保持冷静与审慎", "以敬畏神的态度，不轻易论断神的作为", "尊重事实，以历史与时间检验真伪"], "caution": ["审慎中仍止步于观望，未走到真正的相信"], "applications": ["在看不清的事上保持谦卑，不急于打压", "群情激愤时作那个让大家冷静的声音", "用时间与事实检验真伪，把审判交给神", "警惕「攻击神的作为」而不自知"], "scriptures": ["徒5:34-39", "徒22:3"]}, {"name": "亚居拉", "lesson": "以家庭与职业服事主的同工", "witness": "亚居拉和百基拉是一对以日常生活服事神的夫妻典范。他们与保罗同业（制帐棚）、同工、同住，把职业变成宣教的平台。他们冒生命危险救助保罗，在以弗所听见亚波罗讲道，便「把神的道给他讲解更加详细」。他们的家在不同城市都成了教会聚集之所。他们提醒：服事神不一定要全职、要讲台，平凡的家庭、职业与好客，同样能承载极大的国度影响。", "summary": "制造帐棚的犹太人，与妻子百基拉一同接待保罗、同工同业，并在家中设立教会，栽培亚波罗。", "prayer": "主啊，亚居拉夫妇以职业、家庭与好客服事祢、造就人。求祢使我的日常生活也成为祢的器皿，在平凡中承载祢国度的工作。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以职业与家庭作服事的平台", "好客接待，冒险帮助主的仆人", "谦和而精准地栽培、造就他人"], "caution": [], "applications": ["把你的职业与家庭献上，成为服事的器皿", "以好客接待有需要的肢体与仆人", "在合适的时机温柔地帮助人更明白真理", "夫妻同心，一起委身于神的工作"], "scriptures": ["徒18:2-3", "徒18:26", "罗16:3-5"]}, {"name": "百基拉", "lesson": "在真理上造就人的姊妹", "witness": "百基拉是新约中极受敬重的女性同工，经文六次提到这对夫妻，有四次把她列在丈夫之前——这在当时极不寻常，显出她在教导与服事上的分量。当满有口才、熟悉圣经的亚波罗只知道约翰的洗礼时，百基拉与亚居拉「接他来，将神的道给他讲解更加详细」——不是公开羞辱，而是私下、谦和、准确地造就。她提醒：在真理上造就人，靠的是恩慈与扎实，不是张扬。", "summary": "亚居拉的妻子，常与丈夫并称且多次列名在前；与丈夫一同教导口才出众的亚波罗，使他更明白神的道。", "prayer": "主啊，百基拉以扎实与谦和在真理上造就了亚波罗。求祢使我在祢的道上下功夫，又以恩慈私下地帮助人成长，不求人前的张扬。阿们。", "tags": ["女性", "正面榜样"], "follow": ["在真理上扎实，能造就属灵领袖", "以谦和私下的方式帮助人，不羞辱人", "与丈夫同心，在服事中并肩"], "caution": [], "applications": ["在真理上下功夫，好能帮助别人", "纠正或补足人时，选择谦和私下的方式", "看重在幕后造就人的服事", "以家庭为单位一同服事神"], "scriptures": ["徒18:26", "罗16:3", "林前16:19"]}, {"name": "非比", "lesson": "默默服事众人的女执事", "witness": "保罗在罗马书结尾郑重推荐非比：称她为「女执事」，嘱咐信徒「在主里照着圣徒的体统接待她」，并说她「素来帮助许多人，也帮助了我」。一个常被略过的名字，却承担着保罗最重要书信的传递，也以实际行动供应、扶助众多肢体。非比代表那些不站台前、却以服事和款待默默托住教会的人——她们的名字或许不显，神却一一记念。", "summary": "坚革哩教会的女执事，被保罗郑重推荐，「帮助许多人，也帮助了我」，传统认为她受托携带罗马书。", "prayer": "主啊，非比默默服事众人，也忠心传递了祢仆人的书信。求祢使我甘心在不显眼处服事，以实际的帮助托住肢体，深信祢必记念。阿们。", "tags": ["女性", "正面榜样"], "follow": ["以实际的服事与供应帮助许多人", "忠心受托，承担重要的使命", "以款待与扶助托住教会"], "caution": [], "applications": ["看重并感谢教会中默默服事的人", "以实际行动帮助有需要的肢体", "忠心完成受托的事，无论显眼与否", "以好客与供应参与神的工作"], "scriptures": ["罗16:1-2"]}, {"name": "巴底买", "lesson": "坚持呼求，信心使人得救", "witness": "巴底买坐在路旁讨饭，听见是拿撒勒的耶稣，就喊着说：「大卫的子孙耶稣啊，可怜我吧！」众人责备他，不许他作声，他却越发大声喊叫。耶稣站住，叫他来。他丢下外衣（乞丐谋生的家当），跳起来去见耶稣。「你要我为你做什么？」「拉波尼，我要能看见！」耶稣说：「你的信救了你。」他立刻看见，就在路上跟随耶稣。坚持的、孤注一掷的信心，蒙主垂听。", "summary": "耶利哥城外的瞎眼乞丐，众人责备他仍大声呼求耶稣怜悯，因信得了看见，就跟随主走路。", "prayer": "主耶稣，巴底买不顾拦阻坚持呼求，因信得看见。求祢赐我同样迫切坚持的信心，丢下旧的倚靠来到祢面前，蒙恩后一生跟随祢。阿们。", "tags": ["其他", "正面榜样"], "follow": ["认定耶稣是大卫的子孙（弥赛亚），坚持呼求", "不顾众人拦阻，越发迫切", "得医治后立刻跟随主"], "caution": [], "applications": ["在拦阻与冷遇中，仍坚持向主呼求", "向主明确说出你的需要", "为跟随主，愿意丢下旧的倚靠（外衣）", "蒙恩后以跟随主作回应"], "scriptures": ["可10:47-48", "可10:50-52", "路18:42-43"]}, {"name": "撒玛利亚妇人", "lesson": "遇见活水的人，成了见证的人", "witness": "正午独自打水的撒玛利亚妇人，有破碎的过去（五个丈夫）和被边缘化的身份。耶稣却越过种族、性别、道德的藩篱，主动向她要水喝，并把「活水」赐给她：「人若喝我所赐的水，就永远不渴。」她从回避、争辩，到被主洞悉一切而折服，认出祂是基督。然后她「留下水罐子」跑回城里：「你们来看！」许多撒玛利亚人因她的话信了耶稣。一个被人轻看的人，成了最早的城市布道者。", "summary": "井边打水时遇见耶稣的撒玛利亚妇人，从谈论活水到认出基督，随即丢下水罐进城作见证，带来全城归主。", "prayer": "主耶稣，祢在井边把活水赐给被人轻看的妇人，她就成了带城归主的见证人。求祢以祢的活水充满我，使我也坦然作见证，带人来看祢。阿们。", "tags": ["女性", "正面榜样"], "follow": ["从遇见主到认出主，坦诚面对自己", "立刻向众人作见证，带人来见耶稣", "不因过去与身份而退缩"], "caution": [], "applications": ["在主面前坦诚面对自己的过去与渴望", "领受了主就立刻去与人分享", "跨越成见去关心、邀请人认识主", "让别人「来看」，把人带到耶稣面前"], "scriptures": ["约4:13-14", "约4:28-29", "约4:39-42"]}, {"name": "睚鲁", "lesson": "在绝望尽头，只管信", "witness": "睚鲁是有身份的会堂主管，却为了十二岁垂死的独生女，俯伏在耶稣脚前恳求。半路上，血漏妇人耽延了耶稣的脚步，家里传来噩耗：「你的女儿死了，何必还劳动夫子呢？」就在希望破灭的那一刻，耶稣对他说：「不要怕，只要信！」他选择继续相信。耶稣进去拉着女孩的手说：「闺女，我吩咐你起来！」她立刻起来行走。当人说「太迟了」，主说「只要信」。", "summary": "迦百农的会堂主管，为垂死的独生女俯伏求耶稣；女儿断气后，主对他说「不要怕，只要信」，使女孩复活。", "prayer": "主耶稣，睚鲁在女儿断气的噩耗中听见祢说「不要怕，只要信」。求祢在我绝望的尽头坚固我的信心，深信在祢没有太迟的事。阿们。", "tags": ["其他", "正面榜样"], "follow": ["放下身份，谦卑俯伏求主", "在女儿垂危时寻求唯一的指望", "在噩耗中仍选择继续相信主"], "caution": [], "applications": ["在绝望尽头，仍选择相信主", "不让身份与体面拦阻你来到主前", "当人说「太迟了」，记得主说「只要信」", "为你所爱的人，迫切地把他们带到主前"], "scriptures": ["可5:22-23", "可5:35-36", "可5:41-42"]}, {"name": "浪子的父亲", "lesson": "天父的慈爱，总在远处守望", "witness": "这位父亲是耶稣笔下天父的写照。他容许小儿子带着家产离开——爱里有自由；当儿子败光一切、落魄归来，「相离还远，他父亲看见，就动了慈心，跑去抱着他的颈项，连连与他亲嘴」。他不等儿子说完悔过的话，就吩咐拿上好的袍子、戒指、鞋，宰肥牛犊庆祝：「我这个儿子是死而复活、失而又得的。」他也出去恳求心里不平的大儿子。父亲的爱，既奔向回头的浪子，也寻找自义的长子。", "summary": "比喻中那位分家产、日日盼望、远远看见就跑去拥抱悔改幼子的父亲，预表天父接纳罪人的大爱。", "prayer": "天父，祢就像那位奔跑相迎的父亲，在我还远的时候就动了慈心。求祢使我也以这样的爱接纳回转的人，主动和好，为失而复得的生命欢喜。阿们。", "tags": ["其他", "正面榜样"], "follow": ["给人选择的自由，也始终守望盼望", "在儿子还远时就动慈心、奔跑相迎", "以恩典完全的接纳取代责备", "也主动出去寻找自义、苦毒的大儿子"], "caution": [], "applications": ["像天父一样，向回转的人敞开怀抱，不翻旧账", "主动迈出和好的一步，不端着架子", "为浪子的归回欢喜，而非计较", "也去寻找那些心里不平、自义的人"], "scriptures": ["路15:20", "路15:22-24", "路15:28-32"]}, {"name": "亚多尼雅", "lesson": "自我高举，终被高举所害", "witness": "亚多尼雅「自尊，说我必作王」——他没有等候神，也没有寻问父亲，就为自己张罗车马、宴请党羽。当所罗门被立，他的图谋落空。本可平安度日，他却又求娶大卫的妃子亚比煞，这在当时等同觊觎王位，终被处死。亚多尼雅的一生是「自我高举」的范本：抓取没有交托给自己的东西，一次得免后仍不死心，最终被自己的野心吞没。", "summary": "大卫之子，趁父年迈自立为王，失败后又求娶亚比煞，招致杀身之祸。", "prayer": "主啊，亚多尼雅自我高举，终被野心所害。求祢使我安于祢所量给我的，不抓取祢未交托的，甘心等候祢的高举与时候。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["不等候神，自行抓取王位与名分", "一次蒙宽容后仍不悔改、再次伸手", "以宴乐结党自抬声势"], "applications": ["渴望提升时，先问这是否出于神、是否到了时候", "得了宽容就当珍惜，不要再回到老路", "不抓取没有交托给你的位分与权利", "让神来高举你，而非自我高举"], "scriptures": ["王上1:5", "王上2:13-25"]}, {"name": "伊施波设", "lesson": "靠人扶持的权位，终不长久", "witness": "伊施波设的王位从头到尾都是别人给的——押尼珥立他、又因一句责备就要弃他；他「不敢回答押尼珥一句」，显出他的软弱。他没有神的膏立，只有人的扶持；一旦扶持他的人转向，他的国就瓦解，自己也死于非命。他提醒：靠人脉与势力撑起来的地位，根基浮浅；唯有神所立的，才能长久。", "summary": "扫罗之子，被元帅押尼珥扶立为以色列王，软弱无能，最终在床上被两名军长所杀。", "prayer": "主啊，伊施波设的王位靠人扶持，终归倾覆。求祢叫我不贪恋祢未赐的位分，把根基立在祢的呼召上，在所托之事上忠心尽责。阿们。", "tags": ["君王", "混合型"], "follow": [], "caution": ["据守不属于自己的王位，与神所立的为敌", "完全倚赖人的扶持，自己却无担当", "在该刚强时软弱，在该退让时贪恋"], "applications": ["不要据守神没有赐给你的位分", "真正的根基在于神的呼召，不在人的扶持", "在其位就当尽其责，不做傀儡", "顺服神所膏立的，不与神的旨意为敌"], "scriptures": ["撒下2:8-10", "撒下3:11", "撒下4:5-8"]}, {"name": "亚玛撒", "lesson": "夹在纷争中的人，需要分外警醒", "witness": "亚玛撒是个被夹在权力夹缝中的人：他先随押沙龙叛父，失败后蒙大卫宽宏，被立为元帅取代约押。但他召聚犹大人时迟延误期，给了局势失控的空间；更致命的是，他对暗藏杀机的约押毫无防备——约押用右手「抓住亚玛撒的胡子要与他亲嘴」，左手的刀已刺入他的肚腹。亚玛撒提醒：身处纷争与权力更替之间，既要果断尽责，也要警醒提防笑里藏刀。", "summary": "押沙龙叛乱时的元帅，后被大卫赦免并任命接替约押，却在迟疑误事后被约押假意问安刺杀。", "prayer": "主啊，亚玛撒在纷争中迟疑又疏于防备，以致丧命。求祢赐我果断尽责的心，又赐我分辨与警醒，在复杂的处境中靠祢站立得稳。阿们。", "tags": ["其他", "混合型"], "follow": ["失败后接受赦免，愿意重新被使用"], "caution": ["在关键任务上迟延误事", "对心怀宿怨者毫无防备"], "applications": ["蒙赦免后，以忠心和果断回应所托", "在权力交替的敏感处境中分外警醒", "对笑脸相迎却心怀敌意的人有所提防", "按时完成所托，不给混乱留空间"], "scriptures": ["撒下19:13", "撒下20:4-5", "撒下20:9-10"]}, {"name": "革罗罢", "lesson": "主常在失望的路上与我们同行", "witness": "受难后的第三天，革罗罢和同伴垂头丧气地走在回以马忤斯的路上：「我们素来所盼望要救赎以色列民的就是他。」希望破灭了。复活的耶稣却走近，与他们同行，从摩西和众先知给他们讲解圣经，他们的「心里火热」却仍不认得，直到坐席擘饼的那一刻——眼睛开了，认出了主，主却不见了。他们立刻起身赶回耶路撒冷报信。主常在我们最失望的路上，悄悄同行，藉祂的话与擘饼向我们显现。", "summary": "以马忤斯路上两个门徒之一，在失望返乡途中与复活的主同行而不认得，直到擘饼时眼睛明亮。", "prayer": "复活的主，祢在以马忤斯路上与失望的门徒同行，藉圣经与擘饼开他们的眼。求祢在我灰心的路上也与我同行，点燃我的心，使我认出祢、传扬祢。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在失望中仍彼此谈论主的事", "主一开他们的眼，就立刻起身去传扬"], "caution": ["曾因眼前的失望，看不见就在身边的主"], "applications": ["在失望沮丧时，记得主可能正与你同行", "让神的话「讲解圣经」点燃你冷却的心", "在擘饼/团契中经历主的同在", "一旦认出主，就立刻起身去与人分享"], "scriptures": ["路24:17-21", "路24:30-32", "路24:33-35"]}, {"name": "哈拿尼雅（假先知）", "lesson": "动听的假预言，拦不住真实的审判", "witness": "当耶利米以木轭警告百姓必须服事巴比伦，假先知哈拿尼雅当众折断木轭，宣告神「两年之内」就要打破巴比伦的轭。这是人人爱听的话——快速、廉价、皆大欢喜。但它是谎言。耶利米回应：你折断了木轭，却换来铁轭。神藉耶利米宣判：「你使这百姓倚靠谎言……今年你必死。」那年七月，哈拿尼雅就死了。讨人喜欢的假预言不能改变神的话，只能害死说的人和信的人。", "summary": "与耶利米对抗的假先知，折断耶利米颈上的木轭，宣告两年内被掳之物必归回，当年即死。", "prayer": "主啊，哈拿尼雅用动听的假预言抵挡祢的话，自取灭亡。求祢赐我分辨的心，宁愿领受逆耳的真理，也不被讨好的谎言迷惑。阿们。", "tags": ["先知", "警戒为主"], "follow": [], "caution": ["传讲人爱听、却非出于神的「平安」信息", "以戏剧化的举动包装谎言", "用速成的应许抵挡神真实的警告"], "applications": ["分辨信息是否出于神，而非是否动听", "警惕那些只说「平安平安」的声音", "宁可听逆耳的真话，不信顺耳的谎言", "不要用属灵的语言包装自己的意愿"], "scriptures": ["耶28"]}, {"name": "巴施户珥", "lesson": "逼迫传话的人，改变不了所传的话", "witness": "巴施户珥是殿里有权柄的祭司。他听见耶利米的预言，不是省察，而是动手——打先知、上枷锁，要羞辱、压制这逆耳的声音。但天一亮，枷锁打开，神的话反而更重：耶利米给他改名「玛歌珥米撒毕」（四面惊吓），宣告他必亲眼看见亲友倒在刀下、自己被掳客死巴比伦。逼迫传话的人，丝毫拦不住神所定的话——只会把审判引到自己身上。", "summary": "圣殿的总管祭司，打耶利米并把他枷在枷锁里，耶利米宣告他和全家必被掳到巴比伦死在那里。", "prayer": "主啊，巴施户珥逼迫先知，却拦不住祢的话，反招审判。求祢使我面对责备时谦卑省察，不以权力压制真理，乃尊重祢所差的人。阿们。", "tags": ["祭司", "警戒为主"], "follow": [], "caution": ["用权力压制、逼迫说真话的人", "面对责备，选择动手而非省察", "以为除掉信使就能除掉信息"], "applications": ["听见逆耳之言时，先省察而非反击", "不要用职权打压指出问题的人", "记得压制真理只会加重自己的责任", "尊重并保护忠心传讲神话语的人"], "scriptures": ["耶20:1-2", "耶20:3-4", "耶20:6"]}, {"name": "押撒", "lesson": "承受产业的人，也求活水的泉源", "witness": "押撒是个有信心、敢求的女子。父亲迦勒把她许配给攻取基列西弗的俄陀聂，又把南地赐给她为业。但南地干旱，她没有止步于「有地」，而是下驴向父亲求：「求你把水泉也赐给我。」迦勒就把上泉下泉都给了她。押撒提醒我们：神赐的产业有时还缺「水泉」——我们可以坦然向天父求那使产业有生命的活水，祂乐意厚赐。", "summary": "迦勒的女儿，俄陀聂之妻；得了南地为业后，进一步向父亲求水泉，得了上泉与下泉。", "prayer": "天父，押撒得了产业仍求水泉，祢父亲的心乐意厚赐。求祢赐我活水，浇灌祢所赐的一切，使它们不致干旱，反结出生命的果子。阿们。", "tags": ["女性", "正面榜样"], "follow": ["珍惜所承受的产业，并求使之有生命的水泉", "坦然向父亲（预表向天父）开口祈求", "有信心、有眼光，不止步于现状"], "caution": [], "applications": ["既领受神的恩赐，也求那滋润恩赐的活水", "坦然无惧地向天父祈求美好的事物", "为你所承受的（家庭、事业、恩赐）求属天的滋润", "不满足于「有」，更追求「有生命」"], "scriptures": ["书15:18-19", "士1:14-15"]}, {"name": "约亚拿", "lesson": "用所有的供应主的工", "witness": "约亚拿身份不低——丈夫是希律王的家宰。她却甘心跟随这位拿撒勒的夫子，「用自己的财物供给」耶稣和门徒的需要。在男性门徒之外，是这群妇女默默承担了主团队的供应。到了最后，当门徒四散，她又是清晨到坟墓、最早听见复活信息、回去报给使徒的人之一。约亚拿提醒：用你所拥有的资源供应神的工，是极其宝贵、被神记念的服事。", "summary": "希律家宰苦撒的妻子，与多位妇女用自己的财物供给耶稣和门徒，也是空坟墓的见证人之一。", "prayer": "主啊，约亚拿用自己所有的供给祢的工，又忠心作复活的见证。求祢使我也甘心献上资源服事祢，在幕后忠心，直到见证祢的荣耀。阿们。", "tags": ["女性", "正面榜样"], "follow": ["甘心用自己的财物供给主的工作", "跨越身份地位，谦卑跟随主", "忠心到底，成为复活的见证人"], "caution": [], "applications": ["用你的钱财与资源供应神的事工", "不因身份地位而羞于跟随主", "看重幕后供应型的服事", "忠心跟到底，你也能成为见证人"], "scriptures": ["路8:2-3", "路23:55-56", "路24:9-10"]}, {"name": "亚那", "lesson": "披着圣职的私心，最危险", "witness": "亚那是当时祭司集团的真正掌权者——五个儿子和女婿该亚法相继作大祭司，圣殿的买卖利益盘根错节。耶稣被捕，先被带到亚那面前私审，这本身就不合法。他披着最神圣的职分，内里却是维护家族权势与既得利益。亚那提醒：最危险的败坏，不是公开的恶，而是用圣职、用宗教外衣包裹的私心与权谋。", "summary": "曾任大祭司、该亚法的岳父，虽已卸任仍把持祭司家族大权，在夜间私审耶稣。", "prayer": "主啊，亚那披着圣职却怀私心，暗中不义审判祢的爱子。求祢洁净我事奉的动机，使我不以属灵身份谋私利，乃在隐密处持守公义。阿们。", "tags": ["祭司", "警戒为主"], "follow": [], "caution": ["用神圣的职分掩护家族私利", "在暗中操纵、行不公义的审判", "以宗教权威压制真理"], "applications": ["警惕用属灵身份包装的私心与权力", "不让既得利益扭曲你对真理的态度", "在暗处也持守公义，不搞暗箱", "常省察：我事奉的是神，还是自己的利益？"], "scriptures": ["路3:2", "约18:13", "约18:19-24"]}, {"name": "尼尼微王", "lesson": "真悔改，从宝座上俯伏开始", "witness": "一个外邦大城的王，听见一个外国先知一句「四十日尼尼微必倾覆」，竟「下了宝座，脱下朝服，披上麻布，坐在灰中」，并下令全城连牲畜都禁食、各人回头离开恶道：「或者神转意后悔……使我们不致灭亡。」这是圣经中最彻底的全民悔改之一。神就「察看他们的行为……不把所说的灾祸降与他们」。尼尼微王提醒：真正的悔改从最高位者的谦卑俯伏开始，而神的怜悯总向真心回转的人敞开。", "summary": "约拿向尼尼微宣告审判时在位的王，他下宝座、披麻蒙灰，带领全城禁食悔改，神就后悔不降所说的灾。", "prayer": "主啊，尼尼微王一听警告就下宝座、披麻悔改，祢就施怜悯。求祢赐我同样不迟延、不倚仗身份的悔改，带领我所影响的人一同归向祢。阿们。", "tags": ["君王", "正面榜样"], "follow": ["听见警告立刻谦卑回应，不倚仗王权", "以身作则，从自己开始悔改", "带领全城离开恶道，寻求神的怜悯"], "caution": [], "applications": ["听见神的警告，立刻回应而非拖延", "身居高位更要带头谦卑悔改", "真悔改是「回头离开恶道」，不只是仪式", "相信神的怜悯向真心回转的人敞开"], "scriptures": ["拿3:6", "拿3:7-8", "拿3:9-10"]}, {"name": "哈拿尼（先见）", "lesson": "忠言虽逆耳，也要说", "witness": "哈拿尼是先见，责备亚撒晚年倚靠亚兰王而非倚靠神，因此被下在监里。他宁可坐监，也要把神的话照实说出来。忠言常常逆耳，但忠心的仆人不因人的脸色改写神的信息。", "summary": "责备亚撒王晚年倚靠亚兰、不倚靠神的先见，因直言被亚撒下在监里。", "prayer": "主啊，哈拿尼冒着坐监说真话。求祢赐我忠心直言的勇气，不因人的脸色与权势而隐瞒祢的话。阿们。", "tags": ["先知", "正面榜样"], "follow": ["照实传讲神的话，不看人的脸色", "预备好为说真话付代价"], "caution": ["不要因对方有功、有权就不敢直言"], "applications": ["该说的真话不因情面而隐瞒", "提醒人（也提醒自己）根本问题是'倚靠谁'", "预备好承担说真话的代价"], "scriptures": ["代下16:7-10"]}, {"name": "耶弗他的女儿", "lesson": "在他人的轻率里，仍以顺服回应", "witness": "耶弗他出战前轻率许愿：得胜归来，头一个出门迎接他的，必献给耶和华。得胜了，出来的竟是他的独生女，击鼓跳舞迎接父亲。这是父亲的鲁莽酿成的悲剧。然而女儿的回应令人动容：「父啊，你既向耶和华开口，就当照你口中所说的向我行。」她只求两个月与同伴哀哭。她在父亲的轻率与那个时代的黑暗里，以惊人的顺服与尊严面对。她的故事既警戒轻率许愿，也彰显一个年轻生命的高贵。", "summary": "耶弗他得胜归来，女儿率先出来迎接，却因父亲轻率的许愿而献上自己，顺服地接受了这命运。", "prayer": "主啊，耶弗他的女儿在父亲的轻率里以顺服回应。求祢使我说话谨慎、许愿不轻率，也赐我在不公的处境中仍存尊严与信靠的心。阿们。", "tags": ["女性", "正面榜样"], "follow": ["在不公的命运前，仍以顺服与尊严回应", "尊重所许的愿，看重对神的承诺"], "caution": ["（警戒在其父）轻率许愿，累及无辜至亲"], "applications": ["不要轻率向神许愿，免得累及他人", "说话许诺前先三思，言出必行", "在他人造成的困境中，仍存尊严与信心", "记念那些在黑暗时代默默承受的人"], "scriptures": ["士11:35", "士11:36", "士11:39-40"]}, {"name": "浪子", "lesson": "醒悟回家的那一刻，父亲一直在等", "witness": "他要求提前分家产——等于说「我巴不得你死」；然后远走、放荡、耗尽一切，直到落在猪群中，连豆荚也没人给。就在最低谷，他「醒悟过来」：父亲家里雇工尚且有余，我却饿死在此！他起来，带着预备好的悔改的话往家走。还离得远，父亲就跑来抱住他。他悔改的话还没说完，袍子、戒指、鞋、肥牛犊就都来了。浪子提醒：无论走得多远、跌得多惨，只要醒悟回头，父亲一直在路口等候，要完全地接纳。", "summary": "比喻中那个要了家产、远走他乡挥霍净尽、落到喂猪地步，后醒悟回家、被父亲完全接纳的小儿子。", "prayer": "天父，浪子醒悟回家时，祢早已在路口奔跑相迎。求祢使凡走远的我们都肯起来回家，坦白认罪，并深知祢的接纳完全无条件。阿们。", "tags": ["其他", "混合型"], "follow": ["在最低谷「醒悟过来」，承认自己的罪", "起来、真实地回到父亲那里", "以「我得罪了天，又得罪了你」坦白认罪"], "caution": ["以自我为中心，挥霍神所赐的一切", "非要走到尽头才肯回头"], "applications": ["无论跌得多惨，记得起来回家永不太迟", "真实地向神认罪，不找借口", "相信天父在路口等候、要完全接纳你", "帮助那些在「远方」的人醒悟回家"], "scriptures": ["路15:13", "路15:17-19", "路15:20-24"]}, {"name": "浪子的哥哥", "lesson": "守在家里，心却可能离父亲很远", "witness": "大儿子从未离家，多年劳苦、未违背父命。可当弟弟回来、父亲设宴，他却「生气，不肯进去」。他对父亲说：我服事你这多年，你并没有给我一只山羊羔……「但你这个儿子」回来，你倒为他宰肥牛犊！他守着规矩，心里却满是比较、自义与苦毒——他在家，心却离父亲的心很远。父亲出来恳求他：「你常和我同在，我一切所有的都是你的。」大儿子警戒我们：循规蹈矩的人，也可能因自义而无法分享父亲的喜乐。", "summary": "比喻中那位循规蹈矩、却因父亲为归家的弟弟设宴而愤怒、不肯进去的大儿子。", "prayer": "天父，浪子的哥哥守在家里，心却因自义离祢很远。求祢医治我里面的比较与苦毒，使我为他人的蒙恩欢喜，真正享受与祢同在的福。阿们。", "tags": ["其他", "警戒为主"], "follow": ["多年顺服，持守本分"], "caution": ["以自义比较，看不起回头的人", "因恩典临到别人而愤恨不平", "身在父家，心却充满苦毒、不肯进去"], "applications": ["警惕「守规矩」背后的自义与比较", "为别人蒙恩、浪子回头而真心欢喜", "享受与父同在的福分，而非只盯着「报酬」", "让父亲的心成为你的心：失而复得就当欢喜"], "scriptures": ["路15:28-30", "路15:31-32"]}, {"name": "悔改的强盗", "lesson": "最后一刻的信心，也蒙主记念", "witness": "两个强盗都与耶稣同钉。一个讥诮，一个却在生命的最后几小时里看见了真相：他责备同伴「你既是一样受刑的，还不怕神吗？」承认自己「是应得的」，又认出无罪受死的耶稣是王：「耶稣啊，你得国降临的时候，求你记念我！」他没有受过洗、没有行过善、没有时间补救，只有一个转向基督的信心。主立刻应许：「今日你要同我在乐园里了。」他是恩典最纯粹的见证：得救本乎恩，因着信，与功德无关——哪怕在最后一刻。", "summary": "与耶稣同钉十字架的强盗之一，在临终之际悔改、求主记念，当天就蒙应许同进乐园。", "prayer": "主耶稣，十字架上的强盗最后一刻转向祢，就蒙应许同进乐园。谢谢祢的恩典如此浩大；求祢使我单单信靠祢的怜悯，也把这盼望带给绝境中的人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在临终之际仍肯悔改、敬畏神", "坦承自己的罪，认出基督是王", "把自己完全交托给主的怜悯"], "caution": [], "applications": ["无论何时回转都不太晚，但不要拖到最后", "得救在乎信靠基督，而非功德积累", "坦承己罪，单单求主的记念", "向临终、绝境中的人传讲这位接纳人的主"], "scriptures": ["路23:40-41", "路23:42", "路23:43"]}, {"name": "财主（与拉撒路）", "lesson": "今生的宴乐，挡不住永恒的鸿沟", "witness": "财主「穿着紫色袍和细麻布衣服，天天奢华宴乐」，而浑身生疮的拉撒路就躺在他门口，巴望得他桌上掉下的零碎。财主不是做了什么大恶，而是对近在门口的苦难「视而不见」。死后境遇翻转：拉撒路在亚伯拉罕怀里，财主在阴间的火焰里，中间有「深渊限定」，无法跨越。他求打发拉撒路去警告五个兄弟，得到的回答是：他们有摩西和先知，「若不听……就是有一个从死里复活的，他们也是不听劝」。财主警戒：漠视身边的穷人、把今生宴乐当一切，会换来无法挽回的永恒。", "summary": "比喻中那位天天奢华宴乐、却对门口的乞丐拉撒路视而不见的财主，死后在阴间受痛苦。", "prayer": "主啊，财主因漠视门口的拉撒路而在永恒中追悔莫及。求祢开我的眼看见身边的需要，不被财富迷惑，趁今生听从祢的话，认真预备永恒。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["天天宴乐，对门口的苦难视而不见", "以财富自满，不理会神的话", "到永恒里才发现一切已无法挽回"], "applications": ["睁眼看见你「门口」的需要，伸手帮助", "不要让财富使你对他人的痛苦麻木", "趁今生听从神的话，认真预备永恒", "用今生的财物结交永恒的朋友"], "scriptures": ["路16:19-21", "路16:25-26", "路16:29-31"]}, {"name": "不义的管家", "lesson": "属世人尚知未雨绸缪，属神人当为永恒筹谋", "witness": "这是一个容易被误读的比喻。管家因浪费主人财物将被辞退，他便趁还有职权，减免欠债人的债，为日后「有人接他到家里去」预备后路。主人「夸奖这不义的管家做事聪明」——夸的不是他的不义，而是他的远见与果断。主由此教导：「今世之子……比光明之子更加聪明。」连属世的人都知道为将来筹谋，属神的人岂不更当用今生的钱财（「不义的钱财」）去结交永恒的朋友？这是一堂关于精明、远见与善用资源的功课。", "summary": "比喻中那位将被辞退、便机智地为自己预备后路的管家；主称赞他的精明，以此教导门徒善用钱财。", "prayer": "主啊，连不义的管家都知道为将来筹谋。求祢赐我属天的精明与远见，善用今生的一切资源，去做有永恒价值的事，结交永恒的朋友。阿们。", "tags": ["其他", "混合型"], "follow": ["有远见，懂得为将来未雨绸缪", "在仅有的机会窗口里果断行动"], "caution": ["其手段本身是不义的，主夸的是精明而非诡诈", "若把精明用在自私上，就成了警戒"], "applications": ["像属世人筹划将来一样，为永恒筹谋", "善用今生的钱财去做有永恒价值的事", "趁还有机会与职权时，果断行善", "把资源用在结交永恒的朋友上"], "scriptures": ["路16:3-4", "路16:8", "路16:9"]}, {"name": "撒非喇", "lesson": "同心，要同心行善而非同谋欺骗", "witness": "初代教会满有慷慨分享的美好，亚拿尼亚和撒非喇却想要美名而不肯付真实的代价：卖了地，私自留下几分，却谎称全数献上。问题不在于他们留下钱（彼得说：卖了以后，价银不是你作主吗？），而在于「欺哄圣灵」、用谎言换取属灵的称许。三小时后，撒非喇进来，彼得给她机会说实话，她仍附和谎言，随即仆倒断气。这对夫妻警戒：夫妻当同心行善，而非同谋作假；在神面前的虚假，远比在人前的贫穷可怕。", "summary": "亚拿尼亚的妻子，与丈夫同谋，卖地后私留价银却谎称全数奉献，欺哄圣灵，当场仆倒而死。", "prayer": "主啊，撒非喇与丈夫同谋欺哄圣灵，自取灭亡。求祢使我在祢面前全然诚实，不慕虚名；也使我与至亲同心行善，而非同谋作假。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["夫妻同心，却同谋欺骗", "为博取美名而对神说谎", "有机会说实话时仍坚持谎言"], "applications": ["奉献与事奉要诚实，量力而为，不慕虚名", "夫妻要同心行善，彼此提醒走正路", "在神面前不可有半点虚假", "给人（也接受）说实话的机会，及时回转"], "scriptures": ["徒5:1-2", "徒5:8", "徒5:9-10"]}, {"name": "士求保罗", "lesson": "明达的人，渴慕真道", "witness": "士求保罗是罗马委派的方伯——有地位、有见识的「通达人」。他主动请巴拿巴和保罗来，「要听神的道」。身边的术士以吕马（巴耶稣）极力拦阻，要叫方伯不信。保罗被圣灵充满，定睛斥责这「魔鬼的儿子」，使他暂时瞎眼。方伯看见所发生的事，又「希奇主的道」，就信了。士求保罗提醒：有地位、有学识的人同样需要、也能够渴慕真理；而真心寻道的人，神必为他扫除拦阻。", "summary": "居比路的方伯，通达事理，渴慕听神的道；术士以吕马敌挡，被保罗斥责致瞎，方伯便信了主。", "prayer": "主啊，方伯士求保罗以通达的心渴慕祢的道，纵有拦阻仍信了主。求祢赐我谦卑寻道的心，不因学识地位自满，并为一切真心寻求祢的人除去拦阻。阿们。", "tags": ["其他", "正面榜样"], "follow": ["身居高位仍主动渴慕、寻求神的道", "不因身份学识而自满，愿意聆听", "看见神的作为就坦然相信"], "caution": [], "applications": ["无论地位学识高低，都当谦卑寻求真理", "主动为自己安排听道、寻道的机会", "不被身边敌挡真理的声音拦住", "看见神的作为，就以信心回应"], "scriptures": ["徒13:7", "徒13:8-11", "徒13:12"]}, {"name": "基土拉", "lesson": "在应许之外，神也眷顾", "witness": "基土拉是亚伯拉罕晚年的妻子，为他生了米甸等六个儿子。这些儿子虽不在应许的产业之列（亚伯拉罕把他们打发离开，产业归以撒），神却也使他们成为列族。神的眷顾，也临到应许主线之外的人。", "summary": "亚伯拉罕的后妻，为他生了米甸等六子。", "prayer": "主啊，基土拉的后裔虽不承受应许，祢仍眷顾他们。求祢使我安于祢所定的位分，不嫉妒、不强争，信靠祢全备的眷顾。阿们。", "tags": ["女性", "混合型"], "follow": ["在自己的位分上养育、栽培儿女"], "caution": ["接受神所定的次序（产业归以撒），不强争"], "applications": ["接受神在不同人身上不同的安排", "在自己的位分上尽责，不嫉妒别人的'应许'", "相信神的眷顾也临到'主线之外'的人"], "scriptures": ["创25:1-4"]}, {"name": "米甸", "lesson": "同源却走上不同的路", "witness": "米甸是亚伯拉罕与基土拉所生的儿子，米甸族的祖先。米甸人与以色列本是血亲（同出亚伯拉罕），后来却屡屡与以色列为敌。然而摩西的岳父叶忒罗也是米甸祭司——同一族中，有敌挡的，也有敬畏神的。", "summary": "亚伯拉罕与基土拉所生之子，米甸族的祖先。", "prayer": "主啊，米甸与以色列同源却分道。求祢使我无论出于哪一族，都作敬畏祢的人，也求祢怜悯一切远离祢的亲族。阿们。", "tags": ["其他", "混合型"], "follow": ["可效法米甸中如叶忒罗般敬畏神的人"], "caution": ["血亲也可能走上敌对神百姓的路"], "applications": ["不以血缘断定一个人或一族的属灵光景", "在自己的族群中作敬畏神的那一个", "为与神百姓疏远、敌对的亲族祷告"], "scriptures": ["创25:2"]}, {"name": "拉班", "lesson": "精于算计，却算不过神的看顾", "witness": "拉班是利百加之兄、利亚与拉结之父、雅各的岳父。他精明世故，十次更改雅各的工价，处处占便宜；神却一路看顾雅各，使他在被剥削中反倒昌大。算计人的，终究算不过那位看顾的神。", "summary": "利百加之兄，利亚与拉结之父，雅各的岳父。", "prayer": "主啊，拉班算计雅各，祢却看顾保守。求祢除去我心里算计占便宜的习性，使我待人公平；遭亏待时，叫我深信祢必看顾。阿们。", "tags": ["其他", "混合型"], "follow": ["对家人也有看顾与挂念之情"], "caution": ["待人精于算计、反复无常、占人便宜", "以利益衡量关系，不顾公平"], "applications": ["待人（尤其家人、雇员）公平，不算计占便宜", "遭遇被亏待时，信靠神的看顾与补偿", "不让利益腐蚀亲情与信任"], "scriptures": ["创24,29-31"]}, {"name": "辟拉", "lesson": "使女的身份，也被编入神的家", "witness": "辟拉是拉结的使女，后作雅各的妾，生了但和拿弗他利。她身为使女，地位卑微，却成了以色列两个支派的母亲。神的家谱里，容得下卑微的使女——出身不能拦阻神的使用。", "summary": "拉结的使女，生但与拿弗他利。", "prayer": "主啊，卑微的使女辟拉也成了支派的母亲。求祢使我不因身份卑微而自弃，在祢所安排的位分中忠心，深知祢看重的不是出身。阿们。", "tags": ["女性", "混合型"], "follow": ["在卑微的身份中尽本分", "接受神在自己生命中的安排"], "caution": ["（背景）人为求子而起的家庭纷争值得反思"], "applications": ["无论身份高低，都在神的安排中尽忠", "不以出身、地位论断自己或他人的价值", "相信神能使用最卑微的人成就大事"], "scriptures": ["创30:1-8"]}, {"name": "悉帕", "lesson": "被给来给去，神仍记念", "witness": "悉帕是利亚的使女，后作雅各的妾，生了迦得和亚设。她被主母当作生育的工具给来给去，自己无从作主，神却记念她，使她成为两个支派的母亲。在身不由己的处境里，神依然看顾、依然使用。", "summary": "利亚的使女，生迦得与亚设。", "prayer": "主啊，悉帕身不由己，祢却记念她、使用她。求祢使我在无从作主的处境中仍信靠祢的看顾，也提醒我不把人当作工具。阿们。", "tags": ["女性", "混合型"], "follow": ["在身不由己的处境中仍被神记念"], "caution": ["（背景）把人当生育工具的家庭争竞，值得警醒"], "applications": ["在身不由己的处境中，仍信靠神的看顾", "不把人当作达成目的的工具", "相信神记念每一个卑微、被忽略的人"], "scriptures": ["创30:9-13"]}, {"name": "底拿", "lesson": "一次随意的外出，卷入风暴", "witness": "底拿是雅各与利亚的女儿。她出去观看那地的女子，却被示剑玷辱，继而引发哥哥们血腥的报复，使全家陷入危机。一个少女的遭遇，成了那个充满暴力之世代里受害者的缩影。", "summary": "雅各与利亚的女儿，示剑事件的中心人物。", "prayer": "主啊，底拿在风暴中受了伤害。求祢保护软弱无助的人，安慰一切受侵害的心，也使我成为保护人、而非论断人的人。阿们。", "tags": ["女性", "混合型"], "follow": [], "caution": ["（受害提醒）在陌生环境中缺乏看顾与防备的危险"], "applications": ["在陌生或不安全的环境中保持警觉", "为遭受侵害的人代求，给予保护而非论断", "记得神看顾受伤、被欺的人"], "scriptures": ["创34"]}, {"name": "示剑", "lesson": "放纵情欲，害人也害己", "witness": "示剑是希未人哈抹的儿子，因情欲玷辱了底拿。即使事后他'心系底拿'、愿付任何聘礼，也无法弥补已造成的伤害，终在西缅利未的报复中与全城同亡。一时放纵的情欲，毁了对方，也毁了自己和全城。", "summary": "希未人哈抹之子，玷辱底拿。", "prayer": "主啊，示剑放纵情欲，害人害己。求祢洁净我的情欲，使我尊重人、敬畏祢，在试探前自守，不留下无法弥补的伤害。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["放纵情欲，以强暴满足私欲", "以为事后的弥补能抹去所造成的伤害"], "applications": ["约束情欲，尊重他人不可侵犯的尊严", "明白有些伤害造成后无法挽回，故当事前自守", "在欲望面前选择敬畏神而非放纵"], "scriptures": ["创34"]}, {"name": "哈抹", "lesson": "纵容之爱，酿成大祸", "witness": "哈抹是希未人，示剑的父亲。儿子玷辱了底拿，他却为儿子去向雅各家提亲、息事宁人，想以联姻化解。结果西缅、利未用诡计将他与全城男丁尽行杀灭。纵容儿子的过犯、想以妥协掩盖，反招来灭门之祸。", "summary": "希未人，示剑之父。", "prayer": "主啊，哈抹纵容掩盖，反招大祸。求祢使我不纵容、不掩盖罪，以爱与公义正面处理过犯，免得养成更大的祸患。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["纵容儿女的过犯，试图以妥协掩盖", "为息事而回避当面对的罪与责任"], "applications": ["不纵容、不掩盖儿女（或自己）的过犯", "正面处理罪，而非以妥协粉饰", "管教与爱并行，免得酿成大祸"], "scriptures": ["创34"]}, {"name": "谢拉（犹大之子）", "lesson": "同母所生，际遇却各不同", "witness": "谢拉是犹大与他玛所生的双胞胎之一，与法勒斯同时出生。接生时本是他的手先出来，系了朱红线，法勒斯却'抢先而出'，得了长子的名分与弥赛亚的谱系。神的拣选，常出人意料，不照人所定的先后。", "summary": "犹大与他玛所生的双胞胎之一。", "prayer": "主啊，谢拉本该先出，拣选却临到法勒斯。求祢使我顺服祢主权的安排，不嫉妒、不不平，安然在祢所定的位分中。阿们。", "tags": ["其他", "混合型"], "follow": ["接受神主权的拣选与次序"], "caution": ["不以'本该是我先'而心存不平"], "applications": ["接受神主权中出人意料的安排", "不因别人'抢先'而嫉妒不平", "在自己的位分中安然事神"], "scriptures": ["创38:30"]}, {"name": "波提乏", "lesson": "善用人才，却也轻信谗言", "witness": "波提乏是埃及法老的护卫长、约瑟的主人。他看出耶和华与约瑟同在，就把家中一切都交给约瑟管理，大得祝福；却在妻子的诬告下，不加查证就把约瑟下在监里。识人之明，败给了一时的偏听。", "summary": "埃及法老的护卫长，约瑟的主人。", "prayer": "主啊，波提乏识得约瑟的忠心，却偏听谗言冤枉了他。求祢使我重用忠诚，又在听讼时公正查证，不冤枉无辜。阿们。", "tags": ["其他", "混合型"], "follow": ["看重并重用有神同在、忠心可靠的人"], "caution": ["在偏听一面之词时不加查证", "因家庭关系而枉断忠仆"], "applications": ["重用忠心可靠的人，把责任交托", "遇到指控时先查证，不偏听一面之词", "不因亲疏关系而冤枉无辜"], "scriptures": ["创39:1"]}, {"name": "波提乏的妻子", "lesson": "情欲不得逞，便化为陷害", "witness": "波提乏的妻子天天勾引约瑟，约瑟以'我怎能作这大恶、得罪神呢'断然拒绝。她恼羞成怒，抓住约瑟的衣服反诬他，把他送进了监。被拒绝的情欲一旦转为报复，极其狠毒。", "summary": "诬陷约瑟、试探他的妇人。", "prayer": "主啊，波提乏的妻子以情欲与诬陷害约瑟，神却高举了约瑟。求祢洁净我的心，使我不放纵情欲、不挟怨报复，在引诱前像约瑟一样敬畏祢。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["放纵情欲，勾引、纠缠他人", "情欲被拒后，以诬告报复"], "applications": ["约束自己的情欲，不勾引、不纠缠", "被拒绝时不挟怨报复", "效法约瑟：面对引诱时果断逃避、敬畏神"], "scriptures": ["创39:7-20"]}, {"name": "酒政", "lesson": "得意便忘恩，需要警醒", "witness": "酒政是法老的臣仆，因得罪王下监，约瑟为他解梦说三日后必复职。约瑟求他出监后记念自己，他复职后却把约瑟忘了整整两年，直到法老作梦才想起。一朝得意，便忘了患难中帮助自己的人。", "summary": "埃及法老的酒政，约瑟为他解梦。", "prayer": "主啊，酒政得意便忘了约瑟。求祢使我不忘患难中帮助我的人，在顺境中常存感恩，及时回报、不拖延行善。阿们。", "tags": ["其他", "混合型"], "follow": ["蒙恩复职，本是神所赐的转机"], "caution": ["得意之后忘记患难中帮助过自己的人", "拖延当行的义，迟迟不感恩、不回报"], "applications": ["记念在你低谷中帮助过你的人，及时回报", "顺境时不忘患难之交", "不拖延当行的善与当表的恩"], "scriptures": ["创40"]}, {"name": "膳长", "lesson": "同样的处境，不同的结局", "witness": "膳长与酒政一同下监，约瑟也为他解梦，却是凶兆：三日后必被挂在木头上。三天后果然应验。同在监里、同得解梦，结局却天壤之别——神的话语真实，审判与拯救各按其实。", "summary": "埃及法老的膳长，约瑟为他解梦。", "prayer": "主啊，膳长的结局应验了祢藉约瑟所说的话。求祢使我敬畏祢话语的真实，认真面对人生的结局，不存侥幸。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["（背景）罪与审判的真实，不可轻忽"], "applications": ["敬畏神话语的真实，审判与拯救都必应验", "趁还有机会时认真面对自己与神的关系", "不抱侥幸，认真对待人生的结局"], "scriptures": ["创40"]}, {"name": "提幔人以利法", "lesson": "正统的道理，用错了对象", "witness": "提幔人以利法是约伯的三友之首，以'善有善报、恶有恶报'的传统智慧劝约伯认罪。他的话不无道理，却用错了地方——苦难中的约伯并非因罪受罚。神后来责备他们'议论我，不如我的仆人约伯说的是'。", "summary": "约伯的三友之一，以传统智慧论断约伯。", "prayer": "主啊，以利法用对的道理论断了约伯的苦难。求祢使我陪伴受苦的人时先存怜悯、慎于论断，免得以真理伤人。阿们。", "tags": ["其他", "混合型"], "follow": ["有寻求安慰受苦之人的初衷（起初七天默默陪伴）"], "caution": ["用刻板的因果论断别人的苦难", "以正确的道理说错误的应用"], "applications": ["陪伴受苦的人，先倾听而非急于论断", "不用'有罪才受苦'去定罪受难者", "谨慎：对的道理也可能用错对象"], "scriptures": ["伯4-5"]}, {"name": "书亚人比勒达", "lesson": "倚仗传统，却失之冷硬", "witness": "书亚人比勒达是约伯的三友之一，搬出'古人的遗传'劝约伯，甚至冷硬地暗示约伯的儿女是因罪而死。他坚持传统的框架，却在朋友最痛时缺了体恤。正确的传统若没有怜悯，反成扎心的话。", "summary": "约伯的三友之一。", "prayer": "主啊，比勒达以冷硬的传统刺伤了约伯。求祢使我对受苦的人多一分体恤，少一分教条，以怜悯传讲真理。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["以传统教条冷硬地论断受苦的人", "在人最痛时缺乏体恤"], "applications": ["向受苦的人说话时，先有体恤再有道理", "不搬教条去解释别人的痛", "让真理裹着怜悯说出来"], "scriptures": ["伯8"]}, {"name": "拿玛人琐法", "lesson": "言辞激烈，论断更甚", "witness": "拿玛人琐法是约伯三友中言辞最激烈的一位，断言约伯所受的'比你罪孽该得的还少'，催他赶快认罪。他自信满满地替神发言，却误解了神的心意，最后与两友一同需要约伯为他们献祭代求。", "summary": "约伯的三友之一。", "prayer": "主啊，琐法激烈地误替祢发言。求祢使我说话节制谦卑，不擅自替祢定人的罪，以怜悯和真理待受苦的人。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["自信地替神发言，实则误解神的心", "以激烈言辞催逼、定罪受苦的人"], "applications": ["不轻易'替神'下断语去定别人的罪", "对受苦者说话节制，不激烈催逼", "承认自己也会误解，存谦卑受教的心"], "scriptures": ["伯11"]}, {"name": "暗兰", "lesson": "平凡的父母，养育非凡的儿女", "witness": "暗兰是利未的后裔、摩西、亚伦、米利暗的父亲。圣经对他记载不多，但正是他和约基别这个利未人的家，在奴役与杀婴的恐怖中，养育出带领以色列出埃及的摩西与亚伦。神的拯救，从一个敬畏神的家开始。", "summary": "利未的孙子，摩西、亚伦、米利暗之父。", "prayer": "主啊，暗兰一家在奴役中养育了摩西、亚伦。求祢使我在艰难中仍敬畏祢、忠心养育，深知祢能从平凡的家兴起拯救。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在艰难恐怖的环境中，仍敬畏神养育儿女", "作下一代蒙召者的根基"], "caution": ["不被环境的恐怖夺去养育的信心"], "applications": ["在艰难处境中仍尽心养育下一代", "相信神能从平凡的家兴起非凡的器皿", "把儿女的前途交托给神"], "scriptures": ["出6:20"]}, {"name": "法老的女儿", "lesson": "一念怜悯，改写历史", "witness": "法老的女儿在河边洗澡，看见芦荻中的婴孩摩西，听见他哭就动了慈心：这是希伯来人的孩子。她明知父王下令杀男婴，却收养了他，还雇了他的生母作乳母。一个外邦公主的一念怜悯，保全了以色列未来的拯救者。", "summary": "从河中救起婴孩摩西并收养他。", "prayer": "主啊，祢藉法老女儿的一念怜悯保全了摩西。求祢使我对软弱无助者常存怜悯，不惧权势凭良知行善，作祢手中的器皿。阿们。", "tags": ["女性", "正面榜样"], "follow": ["对软弱无助者动慈心、施援手", "不惧权势，凭良知行当行的善"], "caution": ["不因'王命如此'而泯灭怜悯"], "applications": ["对身边软弱、被弃的生命施以怜悯", "在不义的命令面前，凭良知行善", "相信一个小小的怜悯之举，神能大大使用"], "scriptures": ["出2:5-10"]}, {"name": "叶忒罗", "lesson": "智慧的建议，值得谦卑接受", "witness": "叶忒罗是米甸的祭司、摩西的岳父。当他看见摩西从早到晚独自为百姓断案，就直言：这样不好，你必疲惫，百姓也疲惫；当拣选有才能、敬畏神的人分层治理。摩西听了岳父的话，照着行了。", "summary": "米甸的祭司，摩西的岳父，给摩西治理的智慧（又名流珥）。", "prayer": "主啊，摩西谦卑接受了岳父的建议。求祢使我不刚愎自用，乐意听取智慧的提醒，也懂得授权与分担，免得身心俱疲。阿们。", "tags": ["祭司", "正面榜样"], "follow": ["以局外人的清醒，给当局者中肯的提醒", "懂得分层授权，不把事工都揽在自己身上"], "caution": ["不要因自己是领袖就听不进忠告"], "applications": ["事工或工作过重时，学会拣选可信的人来分担", "遇到比你有经验的人的提醒，谦卑领受", "为你所带领的团队建立合理的分工"], "scriptures": ["出3:1,18:13-26"]}, {"name": "革舜", "lesson": "寄居者的身份，也是提醒", "witness": "革舜是摩西与西坡拉的长子，名字意为'在外邦作了寄居的'。摩西用儿子的名字纪念自己在米甸寄居的岁月。这名字也提醒神的子民：我们在世也是寄居的客旅，真正的家乡在神那里。", "summary": "摩西与西坡拉的长子。", "prayer": "主啊，革舜的名字提醒我在世是寄居的。求祢使我以客旅的心志生活，不贪恋今生，把盼望存在祢那永恒的家乡。阿们。", "tags": ["其他", "混合型"], "follow": ["记念自己在世为寄居者的身份"], "caution": ["不要把寄居之地当作永久的家"], "applications": ["以客旅、寄居的心志活在世上", "不被今生的事物缠累，心存天家", "在'寄居'的处境中仍忠心事神"], "scriptures": ["出2:22"]}, {"name": "以利以谢（摩西之子）", "lesson": "记念神是我的帮助", "witness": "以利以谢是摩西的次子，名字意为'我父亲的神帮助了我，救我脱离法老的刀'。摩西用儿子的名字，把神的拯救刻进家族的记忆。一个名字，就是一篇见证——提醒后代：神是我们的帮助。", "summary": "摩西的次子，名意为神是我的帮助。", "prayer": "主啊，以利以谢的名字宣告祢是帮助。求祢使我常记念祢的拯救，把祢的作为传给后代，在难处中深信祢是我的帮助。阿们。", "tags": ["其他", "混合型"], "follow": ["以具体的方式纪念神的拯救与帮助", "把神的作为传给下一代"], "caution": ["不忘记神曾如何搭救自己"], "applications": ["用某种方式（名字、记号、记录）纪念神的帮助", "常向儿女述说神在你身上的拯救", "在新的难处中记得'神是我的帮助'"], "scriptures": ["出18:4"]}, {"name": "亚比户", "lesson": "事奉神，必须照神所定的来", "witness": "亚比户是亚伦的次子，本有祭司的尊荣，却与哥哥拿答献上耶和华没有吩咐的凡火，当场被火烧灭。神说：我在亲近我的人中要显为圣。事奉越靠近神，越不可随己意妄为。", "summary": "亚伦次子，与拿答献凡火被神击杀。", "prayer": "主啊，拿答亚比户因献凡火被灭。求祢使我以敬畏的心事奉祢，凡事照祢所定的而行，不凭己意妄动圣洁的事。阿们。", "tags": ["祭司", "警戒为主"], "follow": [], "caution": ["不凭己意更改神所定的事奉方式", "不因身份尊贵就轻忽神的圣洁", "不把属灵的事奉当作可随意发挥的常规"], "applications": ["事奉前先问：这是神所吩咐的，还是我自己想出来的？", "存敬畏的心亲近神，不轻慢圣洁的事", "在教会服事中尊重神所立的次序"], "scriptures": ["利10:1-2"]}, {"name": "以利亚撒（亚伦之子）", "lesson": "忠心承接，稳稳接棒", "witness": "以利亚撒是亚伦的儿子，在两位兄长因凡火被灭后，忠心承接大祭司的职分，与约书亚一同为以色列分地。他不张扬，却在关键的过渡中稳住了祭司体系，把圣职一代代传了下去。", "summary": "亚伦之子，继任大祭司，与约书亚分地。", "prayer": "主啊，以利亚撒忠心承接了大祭司的职分。求祢使我在所托之处忠心稳妥，与同工同心，把祢的工作好好传承下去。阿们。", "tags": ["祭司", "正面榜样"], "follow": ["在前人离去后，忠心承接所托的职分", "与同工（约书亚）同心配搭，各尽其职", "在过渡与动荡中稳住事工"], "caution": ["不因别人的失败而退缩不前"], "applications": ["在交接、过渡的时刻，甘心承接当尽的责任", "学习与不同岗位的人同心配搭", "看重把信仰与事工传承下去"], "scriptures": ["民20:25-28"]}, {"name": "以他玛", "lesson": "在体系中默默尽责", "witness": "以他玛是亚伦最小的儿子，在会幕事奉中管理利未人的工作与器具，后裔也成为祭司家族的一支。他不是聚光灯下的人物，却在繁琐的事务中忠心，使圣所的事奉井然有序。", "summary": "亚伦之子，祭司家族的一支。", "prayer": "主啊，以他玛在会幕中默默管理、忠心尽责。求祢使我也在不起眼的岗位上忠心，把祢托付的事务做得井然有序。阿们。", "tags": ["祭司", "混合型"], "follow": ["在繁琐的事务中忠心尽责", "看重幕后管理与服事的价值"], "caution": ["不轻看不起眼却必要的本分"], "applications": ["在团队里甘心做幕后管理、统筹的工作", "把繁琐却必要的事做到位", "相信神记念默默尽责的人"], "scriptures": ["出38:21"]}, {"name": "昂", "lesson": "跟错了人，陷入叛乱", "witness": "昂是流便支派的人，名列可拉党起来反叛摩西、亚伦的名单中。他卷入了一场质疑神所立之领袖的叛乱，与可拉、大坍、亚比兰为伍。跟随错误的领袖、参与悖逆，是极危险的事。", "summary": "流便支派人，可拉党羽之一。", "prayer": "主啊，昂跟随可拉卷入了叛乱。求祢赐我分辨，不附和悖逆，不攻击祢所设立的权柄，在煽动中守住敬畏祢的心。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["跟随悖逆的领袖，卷入叛乱", "质疑、攻击神所设立的权柄"], "applications": ["谨慎你所跟随、所附和的人与立场", "不轻易卷入质疑、攻击神所立权柄的事", "在群体煽动中保持分辨，及早抽身"], "scriptures": ["民16:1"]}, {"name": "巴勒", "lesson": "想咒诅神所祝福的，终归徒然", "witness": "巴勒是摩押王，因惧怕以色列，重金雇术士巴兰来咒诅他们。然而神不许，巴兰开口反成祝福。巴勒一再换地方、加价钱，想买来一句咒诅，却拦不住神对祂子民的祝福。", "summary": "摩押王，雇巴兰咒诅以色列。", "prayer": "主啊，巴勒想咒诅祢所祝福的子民，终归徒然。求祢使我不因惧怕而暗算他人，深信祢的祝福无人能夺，安心交托于祢。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["想用手段对抗神的旨意，是徒劳的", "因惧怕而设法咒诅、暗算他人", "以为重金可以买动属灵的结果"], "applications": ["不要因惧怕别人而暗中谋害或咒诅他们", "记得神的祝福，人不能挪去", "遇威胁时仰望神，而非靠诡计反制"], "scriptures": ["民22-24"]}, {"name": "西罗非哈", "lesson": "无子的父亲，留下守业的女儿", "witness": "西罗非哈是玛拿西支派的人，死在旷野，没有儿子，只有五个女儿。他虽无子，女儿们却为他据理力争、求得了产业，神也藉此立下女儿可承受产业的律例。一个'绝后'的人，反成了公义律例的契机。", "summary": "玛拿西支派人，无子，五个女儿争得产业。", "prayer": "主啊，西罗非哈虽无子，祢却藉他的女儿立下公义的律例。求祢使我在缺憾中仍信靠祢，深知祢能从不足中带出祝福。阿们。", "tags": ["其他", "混合型"], "follow": ["在缺憾中仍留下信靠神的后人"], "caution": ["不因没有'儿子'（传统的指望）而绝望"], "applications": ["在人生的缺憾中仍信靠神的安排", "看重女儿（常被忽略者）的价值与权利", "相信神能从你的缺憾中带出公义与祝福"], "scriptures": ["民27:1-7"]}, {"name": "玛拉（西罗非哈之女）", "lesson": "为正当的权利，勇敢求问", "witness": "玛拉是西罗非哈的长女，与四个妹妹一同站在摩西、祭司和全会众面前，为父亲争取产业：我们的父亲死了，没有儿子，为什么因他没有儿子就把产业夺去呢？她们有理有据地求问，神就成全。", "summary": "西罗非哈的女儿之一。", "prayer": "主啊，玛拉姊妹勇敢求问，祢就成全她们。求祢赐我勇气，为正当的事合宜地表达、据理求问，并信靠祢的成全。阿们。", "tags": ["女性", "正面榜样"], "follow": ["为正当的权利有理有据地求问", "姊妹同心，勇敢站出来"], "caution": ["求问时存敬畏，不强争胡闹"], "applications": ["为正当合理的权益，勇敢而合宜地表达", "在合法的途径中据理力争", "相信神垂听有理有据、存敬畏的求问"], "scriptures": ["民27:1"]}, {"name": "挪阿", "lesson": "同心争取，一同蒙福", "witness": "挪阿是西罗非哈的女儿之一，与姊妹们同心为产业求问，一同蒙神成全。她们没有各自退缩，而是同心站出来，结果不只得了自家的产业，更为后世无子之家的女儿立下了承受产业的先例。", "summary": "西罗非哈的女儿之一。", "prayer": "主啊，挪阿与姊妹同心，一同蒙了祢的成全。求祢使我与人同心面对当争取的事，不退缩、不推诿，信靠祢的成全。阿们。", "tags": ["女性", "正面榜样"], "follow": ["姊妹同心，一同站立争取", "成为后人蒙福的先例"], "caution": ["不各自退缩、不彼此推诿"], "applications": ["与同伴同心面对该争取的事", "在合宜的事上彼此扶持、不退缩", "相信同心者的求问，神必垂听"], "scriptures": ["民27:1"]}, {"name": "曷拉", "lesson": "守住该得的产业", "witness": "曷拉是西罗非哈的女儿之一。她与姊妹们后来照神的吩咐，嫁给本支派的人，使所得的产业不至于从本支派转走。她们既勇于争取，也顺服神立下的界限，把产业稳稳地守在支派之中。", "summary": "西罗非哈的女儿之一。", "prayer": "主啊，曷拉既争取产业，也顺服祢的界限守住它。求祢使我既勇于承受祢的恩赐，也按祢的吩咐谨守，不致流失。阿们。", "tags": ["女性", "正面榜样"], "follow": ["既勇于争取，也顺服神所定的界限", "谨守所得的产业不致流失"], "caution": ["争取到的，也要按神的吩咐守住"], "applications": ["争取该得的，也顺服神所定的规矩", "谨守神所赐的产业（恩赐、责任）不流失", "在自由与顺服之间持守平衡"], "scriptures": ["民27:1"]}, {"name": "密迦（西罗非哈之女）", "lesson": "平凡女子，载入律例", "witness": "密迦是西罗非哈的女儿之一。她和姊妹的名字被一一记在圣经里，因为她们的求问促成了'女儿承受产业'的律例。几个平凡女子的勇敢与合理，竟成了影响后世的制度。", "summary": "西罗非哈的女儿之一。", "prayer": "主啊，密迦几姊妹的合理诉求成了影响后世的律例。求祢使我在合宜的事上勇敢，深信祢能藉小小的行动造福众人。阿们。", "tags": ["女性", "正面榜样"], "follow": ["以合理的诉求，带来长远的益处"], "caution": ["不轻看一次合宜行动的长远影响"], "applications": ["相信一次合理的争取能造福许多人", "在小事上的勇敢，神能用作大事", "看重公平与制度对后人的意义"], "scriptures": ["民27:1"]}, {"name": "得撒", "lesson": "名字被神记念", "witness": "得撒是西罗非哈最小的女儿。她和姊妹们的名字反复出现在民数记、约书亚记中。她们或许平凡，神却把她们的名字一再记下——在神眼中，没有一个忠心求问、合理而行的人会被遗忘。", "summary": "西罗非哈的女儿之一。", "prayer": "主啊，得撒几姊妹的名字祢一再记下。求祢使我忠心合理而行，不求人的称许，只愿被祢记念在永恒里。阿们。", "tags": ["女性", "正面榜样"], "follow": ["忠心合理而行，不求人的记念"], "caution": ["不因平凡就以为不被神看见"], "applications": ["相信神记念每一个忠心而行的人", "不为被人记得，只求被神记念", "在平凡中持守公义与勇敢"], "scriptures": ["民27:1"]}, {"name": "亚干", "lesson": "暗中的贪心，连累众人", "witness": "亚干在攻取耶利哥时，违背神的吩咐，私自取了当灭的财物藏在帐棚里。结果以色列在小小的艾城溃败，三十六人阵亡。一个人暗中的贪心，连累了整个群体——罪从来不只是'私事'。", "summary": "因私取当灭之物连累以色列在艾城失败。", "prayer": "主啊，亚干暗中的贪心连累了全营。求祢光照我隐藏的贪念，使我不取不义之财，知道我的选择也关乎群体，及时向祢认罪。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["暗中贪取神所禁止的，以为无人知道", "因一人的隐罪，连累整个群体"], "applications": ["不暗中贪取不当得的，神都看见", "明白个人的罪会影响整个群体", "及时认罪，不把罪藏在'帐棚'里"], "scriptures": ["书7"]}, {"name": "迦米", "lesson": "夹在世代之间的一环", "witness": "迦米是撒底的儿子、亚干的父亲，谢拉家族的一员。他是连接祖父撒底与儿子亚干的一环，名字随着亚干的事件被记下。家族的链条上，每一环都承上启下，也都担着影响。", "summary": "亚干之父。", "prayer": "主啊，迦米夹在世代之间。求祢使我在家族的链条中尽责，把敬畏祢的影响传下去，靠祢断开罪与咒诅的循环。阿们。", "tags": ["其他", "混合型"], "follow": ["在世代的链条中尽自己的责任"], "caution": ["上一代的影响会传到下一代，当谨慎"], "applications": ["意识到自己在家族链条中的承接责任", "努力把好的影响、而非罪传给下一代", "为家族断开罪的循环祷告"], "scriptures": ["书7:1"]}, {"name": "撒底", "lesson": "家族之首，影响深远", "witness": "撒底是亚干的祖父、谢拉家族的一员。亚干犯罪受罚时，圣经一直追溯到撒底这一家系。先祖的名字与后代的行为被一同记下——提醒我们，家族的根与代代的选择，彼此相连。", "summary": "亚干的祖父。", "prayer": "主啊，撒底的家系与亚干的罪被一同记下。求祢使我为家族立下敬畏祢的根基，深知今日的选择影响后代。阿们。", "tags": ["其他", "混合型"], "follow": ["看重为家族立下敬虔根基的责任"], "caution": ["家族的影响会延及后代，不可不慎"], "applications": ["看重自己作为家族一员对后代的影响", "为家族打下敬畏神的根基", "明白根与果在世代中彼此相连"], "scriptures": ["书7:1"]}, {"name": "亚多尼洗德", "lesson": "联合抵挡神，必然失败", "witness": "亚多尼洗德是耶路撒冷王，纠集南方五王联盟攻打与以色列立约的基遍。约书亚长驱奔袭，神又降大冰雹、使日头停留，五王败逃藏于洞中，终被擒杀。结盟再大，抵挡神的旨意终归崩溃。", "summary": "耶路撒冷王，南方五王联盟之首。", "prayer": "主啊，亚多尼洗德结盟抵挡祢，终被击溃。求祢使我不与人同谋抵挡祢的工作，乐见人归向祢，顺服祢的旨意。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["纠党结盟抵挡神的工作", "因他人归向神而心生敌意、群起攻之"], "applications": ["不要联合他人去抵挡神所做的事", "当别人转向神时，为他们高兴而非敌视", "记得人多势众也胜不过神的旨意"], "scriptures": ["书10:1-27"]}, {"name": "何咸", "lesson": "随众作恶，同负其责", "witness": "何咸是希伯仑王，南方五王联盟的一员，跟随耶路撒冷王一同攻打基遍、抵挡以色列，最终与众王一同败亡。他的结局提醒：随大流加入抵挡神的阵营，不会因'人多'而免责。", "summary": "希伯仑王，南方联盟成员。", "prayer": "主啊，何咸随众抵挡祢的子民而败亡。求祢赐我在群体压力中分辨的勇气，不随大流作恶，单单跟随祢。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["随众结盟，卷入抵挡神的行动", "以为法不责众，随大流作恶"], "applications": ["不因'大家都这样'就加入错误的阵营", "在群体压力下仍分辨是非", "为自己的选择负责，不躲在人群里"], "scriptures": ["书10:3"]}, {"name": "毗兰", "lesson": "同盟之恶，终被审判", "witness": "毗兰是耶末王，南方五王联盟成员之一，联合攻击基遍、与神为敌，最后与众王一同被约书亚擒杀于洞口。结盟再多，也不过是一同走向同一个审判。", "summary": "耶末王，南方联盟成员。", "prayer": "主啊，毗兰因结盟抵挡祢而受审判。求祢使我谨慎所结的同盟，不与抵挡祢的势力为伍，单单站在祢这一边。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["与人结盟去攻击神所要保守的", "倚仗联盟的声势抵挡神"], "applications": ["选择同盟前，先看它所对抗的是不是神的旨意", "不被'联盟声势'冲昏头脑", "及早退出抵挡神的阵营"], "scriptures": ["书10:3"]}, {"name": "雅非亚", "lesson": "权位再高，也立不住脚", "witness": "雅非亚是拉吉王，南方联盟成员，加入了攻打基遍、抵挡以色列的战争，与众王同藏同擒同亡。一城之王的权位，在与神为敌时也不堪一击。", "summary": "拉吉王，南方联盟成员。", "prayer": "主啊，雅非亚倚仗王权抵挡祢，终归覆亡。求祢使我不以地位自恃，谨慎自己所效忠的，单单敬畏祢。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以权位倚仗，卷入抵挡神的争战", "与众王同流，共赴败亡"], "applications": ["不让地位与权力使你站到神的对立面", "审视自己所效忠、所加入的是什么", "记得权位在神面前不能保命"], "scriptures": ["书10:3"]}, {"name": "底璧王", "lesson": "同心作恶，不如同心归正", "witness": "底璧王是伊矶伦王，南方五王联盟的最后一员，与众王联合攻基遍、抗以色列，一同藏身洞中又一同被处死。五王本可各自回头，却选择同心作恶，落得同一结局。", "summary": "伊矶伦王，南方联盟成员。", "prayer": "主啊，底璧王与众王同心作恶，同归败亡。求祢使我把同心用在敬畏祢、行善上，在群体走偏时勇敢回头。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["与人同心，却同心在错误的事上", "错失各自回头的机会"], "applications": ["把'同心'用在归正与行善上，而非作恶", "在群体走偏时，作那个回头的人", "不要等到与众人一同跌入结局才醒悟"], "scriptures": ["书10:3"]}, {"name": "耶宾（夏琐王）", "lesson": "北方霸主，也敌不过神", "witness": "耶宾是夏琐王，纠合北方诸王与众多车马，要扑灭以色列。约书亚靠神得胜，焚毁了当时的霸城夏琐。最强的军事联盟，在神面前也只是被扫除的尘土。", "summary": "夏琐王，北方联盟之首，被约书亚击败。", "prayer": "主啊，夏琐王耶宾纠集强军抵挡祢，终被扫除。求祢使我不惧强权，不靠势力，单单倚靠那使万军退去的祢。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["倚仗军力与联盟，自以为不可战胜", "集结势力抵挡神的子民"], "applications": ["不被强权的声势吓倒，神更大", "不把信心放在'车马'（实力）上", "记得最强的城在神面前也会倾倒"], "scriptures": ["书11:1-11"]}, {"name": "基遍人长老", "lesson": "用诡计求存，神仍以怜悯待之", "witness": "基遍人长老听闻以色列的得胜，惧怕之下，假扮远方来客，用发霉的饼、破旧的皮袋骗以色列与他们立约。诡计被识破后，他们沦为'劈柴挑水'的仆役，却因约得以存活，后来还在大卫时代蒙神看顾。求生的诡诈虽不光彩，神的怜悯却仍存留余地。", "summary": "基遍居民的首领，用诡计与以色列立约。", "prayer": "主啊，基遍人用诡计求存，祢仍以怜悯待他们。求祢使我以诚实而非诡诈寻求出路，也叫我看见祢怜悯的宽广。阿们。", "tags": ["其他", "混合型"], "follow": ["在强势临到时，寻求与神的子民和好（虽以诡计）", "立约之后，甘守卑微的本分"], "caution": ["以欺骗、诡计求取生路"], "applications": ["求生存与出路时，选诚实而非诡诈", "即使曾用错方法，也可在卑微中存活蒙恩", "看见神的怜悯连向'用诡计的外人'敞开"], "scriptures": ["书9"]}, {"name": "西西拉", "lesson": "铁车再强，也胜不过神的时候", "witness": "西西拉是夏琐王耶宾的元帅，有九百辆铁车，压迫以色列二十年。底波拉与巴拉照神的话出战，神使他全军溃败；逃命的西西拉最终死在一个妇人雅亿的帐棚橛子之下。强者的结局，常出人意料。", "summary": "迦南将军，被雅亿用帐棚橛子所杀。", "prayer": "主啊，西西拉的铁车胜不过祢所定的时候。求祢使我不倚仗强势欺人，也不惧怕欺压，深信祢必为受压的人伸冤。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["以武力压迫，欺凌弱小", "倚仗'铁车'的优势，目中无神"], "applications": ["不以自己的优势去压制别人", "记得再强的势力也有神所定的终点", "不轻看神藉看似软弱之人成就的事"], "scriptures": ["士4"]}, {"name": "伊矶伦", "lesson": "贪图辖制，终遭审判", "witness": "伊矶伦是摩押王，趁以色列犯罪辖制他们十八年，养尊处优、肥胖安逸。神兴起左手便利的以笏，以一把双刃剑了结了这个压迫者。安逸中的霸权，神并不长久容忍。", "summary": "摩押王，被以笏刺杀。", "prayer": "主啊，伊矶伦辖制祢的子民，终遭审判。求祢使我不欺压人，也不在安逸中麻木，记得祢必追讨压迫者的罪。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["趁人软弱时加以辖制、勒索", "在压迫与安逸中失去警觉"], "applications": ["不趁人之危去辖制、占便宜", "警惕安逸使人麻木、目中无神", "为被强权压制的人祷告并伸出援手"], "scriptures": ["士3:12-30"]}, {"name": "耶宾（士师时代）", "lesson": "长久的压迫，神必兴起拯救", "witness": "士师时代的夏琐王耶宾，用铁车强兵压迫以色列二十年，使百姓困苦呼求。神就兴起女先知底波拉与巴拉，彻底剪除了耶宾的势力。压迫再久，也有神所定的尽头。", "summary": "夏琐王，压迫以色列二十年，底波拉时代的敌人。", "prayer": "主啊，耶宾压迫祢的子民二十年，祢终究兴起拯救。求祢使受压的人得安慰，也使我不靠强权欺人，单单敬畏祢。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以强权长期欺压，自以为稳固", "不知压迫越久，审判越近"], "applications": ["不要以为靠强权可以长久压制别人", "在被压制的处境中向神呼求", "相信神听见困苦人的呼声，必兴起拯救"], "scriptures": ["士4"]}, {"name": "西巴（米甸王）", "lesson": "掳掠者，终被追讨", "witness": "西巴是米甸的王，与撒慕拿一同年年入侵、掳掠以色列的出产，使百姓躲进山洞。神藉基甸三百人将他追杀。靠掠夺别人维生的，神必亲自追讨。", "summary": "米甸二王之一，被基甸追杀。", "prayer": "主啊，米甸王西巴掳掠祢的子民，终被追讨。求祢使我不靠剥削得利，也求祢眷顾一切被压被掠的人。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["靠掠夺、剥削他人得利", "欺压使人陷入贫困与恐惧"], "applications": ["不靠占夺别人来成全自己", "为遭受剥削、压迫的人祷告", "相信神看顾被掠夺者，必追讨不义"], "scriptures": ["士8"]}, {"name": "撒慕拿", "lesson": "与恶同行，同归败亡", "witness": "撒慕拿与西巴同为米甸王，一同年年压境、掠夺以色列，也一同被基甸追上击杀。两王同恶相济，也同负刑罚。结伴作恶，不过是结伴受审。", "summary": "米甸二王之一，被基甸所杀。", "prayer": "主啊，撒慕拿与西巴同恶同亡。求祢使我远离结伴作恶的同伙，与敬畏祢的人同行，走蒙福的路。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["与人同恶相济，结伴压迫他人", "以为人多势众就可逃避追讨"], "applications": ["不与人结伴去欺压、掠夺", "选择同伴时，看他同行的方向", "记得同伙作恶，也要同担后果"], "scriptures": ["士8"]}, {"name": "俄立", "lesson": "掠夺者的结局，刻在地名上", "witness": "俄立是米甸的首领之一，在基甸的追击中被杀于一块磐石，那地后来就叫'俄立磐石'。他随米甸大军压境掠夺以色列，最终连名字都成了败亡的纪念。倚仗势力欺压的人，结局被神记下。", "summary": "米甸首领，被基甸的军队所杀。", "prayer": "主啊，俄立随米甸掠夺，终败亡留名。求祢使我不倚仗势力欺人，深知一切欺压者的结局都在祢手中。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["随强势的一方掠夺、欺压", "以为人多势众便可横行"], "applications": ["不加入欺压、掠夺他人的一方", "记得欺压者的结局都在神的记念中", "在势力面前仍存敬畏神的心"], "scriptures": ["士7:25"]}, {"name": "西伊伯", "lesson": "与恶为伍，同葬一处", "witness": "西伊伯是米甸的首领，与俄立一同被基甸的军队擒杀，死处后来叫'西伊伯酒醡'。他与俄立同行掠夺、同遭剿灭。结伴行恶的人，连结局都被记在同一处。", "summary": "米甸首领，与俄立一同被杀。", "prayer": "主啊，西伊伯与俄立同行掠夺，同遭剿灭。求祢使我远离结伴作恶的同伙，与敬畏祢的人同行，走蒙福的路。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["与人结伴行恶、掠夺", "以为同伙众多就可逃脱审判"], "applications": ["谨慎你所结伴同行的人与方向", "不与欺压者为伍", "记得结伴作恶，也要同担结局"], "scriptures": ["士7:25"]}, {"name": "玛挪亚的妻子", "lesson": "领受应许，信心比丈夫更稳", "witness": "她是参孙的母亲，原本不育，神的使者向她显现，预告她要生一个拿细耳人。当丈夫玛挪亚惊恐'我们必死，因为看见了神'，她却冷静地说：耶和华若要杀我们，必不悦纳我们的祭。她以信心稳住了惊慌的丈夫。", "summary": "参孙的母亲，蒙天使预告生子。", "prayer": "主啊，玛挪亚的妻子以信心稳住了惊慌的丈夫。求祢赐我这样沉稳的信心，在家人惊惧时带下安定，郑重领受祢的托付。阿们。", "tags": ["女性", "正面榜样"], "follow": ["以信心和理性稳住惊慌的家人", "郑重对待神所赐的呼召与托付"], "caution": ["不被一时的惊惧夺去信心"], "applications": ["在家人惊慌时，作那个有信心、稳得住的人", "郑重对待神在你儿女身上的呼召", "以理性的信心面对属灵的经历"], "scriptures": ["士13"]}, {"name": "参孙的非利士妻", "lesson": "被当作筹码的婚姻，埋下悲剧", "witness": "她是亭拿的非利士女子，参孙的第一任妻子。她在三十个同伴的威胁下，逼问出参孙谜语的答案，又被父亲改嫁他人，最终在冲突中被火烧死。她夹在两个民族的恩怨之间，成了那段悲剧的牺牲品。", "summary": "亭拿的女子，参孙的第一任妻子。", "prayer": "主啊，参孙的妻子被卷入恩怨，沦为牺牲品。求祢使我不在威逼下出卖信任，也求祢怜悯一切夹在仇恨冲突中受害的人。阿们。", "tags": ["女性", "混合型"], "follow": [], "caution": ["（受迫提醒）在威逼下出卖至亲的秘密", "卷入彼此报复的恩怨漩涡"], "applications": ["不在压力下出卖信任你的人", "警惕把婚姻、关系当作利益的筹码", "为夹在仇恨与冲突中的人代求"], "scriptures": ["士14"]}, {"name": "但支派探子", "lesson": "为自己，抢了别人的神像", "witness": "但支派打发五个探子寻找居住之地，途中夺了米迦家的神像和祭司，迁居到拉亿，设立了自己的偶像敬拜。他们为支派谋地、谋'神明'，却是靠抢夺与拜偶像。离了神的话，'为自己谋发展'就走上了歧路。", "summary": "但支派所差、夺取米迦神像的五人。", "prayer": "主啊，但支派靠抢夺与偶像谋发展，走了歧路。求祢使我谋求出路时不夺人之物、不拜偶像，凡事以祢的话为准。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["为自身利益抢夺他人之物", "自设偶像敬拜，离弃真神", "在'人人任意而行'的世代随流而下"], "applications": ["谋求发展时，不以抢夺、不义为手段", "不为自己设立任何取代真神的'偶像'", "在随流的风气中，仍以神的话为准"], "scriptures": ["士18"]}, {"name": "以利加拿", "lesson": "带着家人，持守敬拜的习惯", "witness": "以利加拿是撒母耳的父亲，每年按时上示罗敬拜献祭，疼爱苦于不育的哈拿。在一个混乱的士师时代，他默默维系着一个敬畏神的家——撒母耳就是在这样的家中被献给神、被神兴起。", "summary": "哈拿的丈夫，撒母耳的父亲。", "prayer": "主啊，以利加拿在乱世中维系敬畏祢的家，养育了撒母耳。求祢帮助我持守家庭的敬拜，体贴所爱的人，把家交在祢手中。阿们。", "tags": ["其他", "正面榜样"], "follow": ["按时敬拜神，维系家庭的属灵习惯", "体贴、安慰受苦的家人"], "caution": ["家有纷争时，要更主动地维系和睦"], "applications": ["建立全家固定敬拜、亲近神的节奏", "在配偶或家人受苦时给予体贴的爱", "相信敬畏神的家，神必使用"], "scriptures": ["撒上1"]}, {"name": "毗尼拿", "lesson": "以己之有，刺人之痛", "witness": "毗尼拿是以利加拿的另一个妻子，有儿有女。她因哈拿不育，就年年'作她的对头，大大激动她，要使她生气'。她拿自己所拥有的（儿女）去刺哈拿最深的痛。以自己的优势去伤害别人的缺乏，何等残忍。", "summary": "以利加拿的另一妻子，常激动哈拿。", "prayer": "主啊，毗尼拿拿儿女刺痛了哈拿。求祢除去我里面以优势伤人的心，使我体恤别人的缺乏，以恩慈而非挑衅待人。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["拿自己的优势去刺痛别人的缺乏", "以言语挑衅、激怒身边的人"], "applications": ["不拿自己所拥有的去刺痛别人的不足", "对身边有缺乏、有痛处的人多一分体恤", "管住挑衅、激怒人的舌头"], "scriptures": ["撒上1"]}, {"name": "何弗尼", "lesson": "圣职若无敬畏，必招审判", "witness": "何弗尼是祭司以利的儿子，身为祭司却藐视耶和华的祭物、强取供物、行为污秽，使百姓厌弃献祭。他不认识耶和华，终在约柜被掳之日与兄弟同死。披着圣职而无敬畏，是最危险的。", "summary": "以利的恶儿子之一，藐视耶和华的祭物。", "prayer": "主啊，何弗尼身为祭司却无敬畏，招致审判。求祢洁净我事奉的心，使我真认识祢、敬畏祢，不因我而使人远离祢。阿们。", "tags": ["祭司", "警戒为主"], "follow": [], "caution": ["身在圣职却心无敬畏", "利用职分中饱私囊、放纵情欲", "使别人因自己而厌弃神"], "applications": ["事奉时常省察自己是否真认识、敬畏神", "不利用属灵身份谋取私利", "警惕自己的行为会绊倒别人"], "scriptures": ["撒上2"]}, {"name": "非尼哈（以利之子）", "lesson": "把神圣的当儿戏，荣耀必离开", "witness": "非尼哈是以利的恶儿子，与何弗尼一同亵渎祭司之职。他们把约柜当作打仗的护身符抬上战场，结果约柜被掳、兄弟同亡。他的遗腹子被取名'以迦博'——荣耀离开以色列了。", "summary": "以利的恶儿子，与约柜一同战死。", "prayer": "主啊，非尼哈把约柜当护身符，招致荣耀离开。求祢使我以敬畏待祢神圣的事，不把信仰当工具，免得失去祢的同在。阿们。", "tags": ["祭司", "警戒为主"], "follow": [], "caution": ["把神圣的事物当作工具或护身符", "明知故犯，不听父亲与神的警告"], "applications": ["不把信仰当作达成目的的工具", "存敬畏的心对待神圣的事", "听得进劝诫，趁早回转"], "scriptures": ["撒上2,4"]}, {"name": "以迦博", "lesson": "荣耀离开的那一刻，被刻进名字", "witness": "以迦博是非尼哈的遗腹子。约柜被掳、祖父以利和父亲同日而死的噩耗传来时，他的母亲临产而死，给他起名'以迦博'，意为'荣耀离开以色列了'。他一出生就背负着一个时代属灵荒凉的印记。", "summary": "非尼哈之子，名意为荣耀离开以色列。", "prayer": "主啊，'以迦博'宣告了荣耀的离开。求祢使我以失去祢的同在为最痛，竭力挽回，不让荒凉的印记落在我和我家身上。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（时代警戒）神的荣耀因悖逆而离开，何等可悲", "把神圣当儿戏的世代，终失同在"], "applications": ["以失去神同在为最大的可悲，竭力挽回", "不让'以迦博'（荣耀离开）成为你家的写照", "常省察：神的同在还在我们中间吗？"], "scriptures": ["撒上4:21"]}, {"name": "基士", "lesson": "寻驴的差遣，通向王国的起点", "witness": "基士是便雅悯人，扫罗的父亲。他打发儿子去寻找走失的驴，这趟平凡的差事，却引着扫罗遇见撒母耳、被膏立为以色列第一位王。神常藉着最平凡的日常差事，展开祂宏大的计划。", "summary": "便雅悯人，扫罗的父亲。", "prayer": "主啊，基士打发扫罗寻驴，竟通向王国的起点。求祢使我忠心做手边平凡的事，深信祢能藉日常的小事展开祢宏大的计划。阿们。", "tags": ["其他", "混合型"], "follow": ["在平凡的家务差事中尽责"], "caution": [], "applications": ["忠心做手边平凡的差事，神的计划常藏其中", "不轻看日常小事的属灵潜能", "相信神能藉'寻驴'般的小事开展大计划"], "scriptures": ["撒上9:1-2"]}, {"name": "亚比拿达（扫罗之子）", "lesson": "与家族的命运一同落幕", "witness": "亚比拿达是扫罗的儿子，在基利波山的战役中与父亲、兄弟麦基舒亚、约拿单一同战死。他随着扫罗家的衰亡一同落幕。一个人的际遇，常与他所属之家的兴衰紧紧相连。", "summary": "扫罗之子，与父同死于基利波。", "prayer": "主啊，亚比拿达随扫罗家一同陨落。求祢怜悯我的家，使我家转向祢、走在蒙福的方向，不让悖逆殃及后代。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（背景）家族悖逆神的衰亡，殃及子孙"], "applications": ["意识到家族的属灵方向关乎全家", "为自己的家求神的怜悯与转向", "不让家族的悖逆延续到下一代"], "scriptures": ["撒上31:2"]}, {"name": "麦基舒亚", "lesson": "随父家一同走到尽头", "witness": "麦基舒亚是扫罗的儿子，在基利波山之战中与父亲扫罗、兄弟约拿单、亚比拿达一同阵亡。他随着扫罗家的败亡一同落幕。子女的命运常与父家的属灵方向紧紧相连——这正是为家祷告、为家求转向的理由。", "summary": "扫罗之子，战死于基利波山。", "prayer": "主啊，麦基舒亚随扫罗家一同陨落。求祢怜悯我的家，使我家转向祢，不让悖逆殃及子女，叫我作家中归向祢的那一个。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（背景）父家悖逆神的衰亡，殃及子女"], "applications": ["为自己家的属灵方向警醒、祷告", "不让父辈的悖逆延续成全家的衰败", "在家族中作转向神的那一个"], "scriptures": ["撒上31:2"]}, {"name": "以利押", "lesson": "外表堂堂，神却看内心", "witness": "以利押是耶西的长子、大卫的长兄，身材高大。撒母耳一见就以为'耶和华的受膏者必在他面前'，神却说：不要看他的外貌……人是看外貌，耶和华是看内心。他后来还轻视来送饼的大卫。外表的堂堂，不等于内心合神心意。", "summary": "大卫的长兄。", "prayer": "主啊，以利押外表堂堂，祢却看中了大卫的内心。求祢使我不以外貌自恃、不轻看人，惟求内心合祢的心意。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["以外貌、资历自恃", "轻看比自己小、却合神心意的人"], "applications": ["不以外表、身材、资历衡量人与己", "看重内心是否合神心意", "不轻看那些被神看中的'小人物'"], "scriptures": ["撒上16:6,17:28"]}, {"name": "亚比拿达（大卫之兄）", "lesson": "被略过的兄长，各有其位", "witness": "亚比拿达是耶西的次子、大卫的哥哥。撒母耳膏王时他也从撒母耳面前经过，神却没有拣选他。他后来也随军在扫罗的阵中。神的拣选不照排行与外貌，被略过的人也各有自己当守的本分。", "summary": "耶西的次子，大卫的哥哥。", "prayer": "主啊，亚比拿达被略过，大卫却蒙拣选。求祢使我在被略过时仍安于本分，不嫉妒不平，深信祢的拣选自有美意。阿们。", "tags": ["其他", "混合型"], "follow": ["接受神的拣选不照人意，安于本分"], "caution": ["不因被略过而心生嫉妒不平"], "applications": ["当别人被拣选而你被略过时，仍安然尽本分", "不以排行、资历论断神的拣选", "在自己的位置上忠心，不嫉妒"], "scriptures": ["撒上16:8"]}, {"name": "沙玛（大卫之兄）", "lesson": "排行靠前，却非神所拣选", "witness": "沙玛是耶西的三子、大卫的哥哥。撒母耳膏王时，他也从撒母耳面前经过，神却没有拣选他。他后来也在扫罗军中。三个哥哥都被略过，神偏偏选了放羊的小弟——神的拣选，从不照人所看重的次序。", "summary": "耶西的三子，大卫的哥哥。", "prayer": "主啊，沙玛被略过，大卫蒙拣选。求祢使我在被略过时安于本分，不嫉妒蒙拣选的人，深信祢的拣选自有美意。阿们。", "tags": ["其他", "混合型"], "follow": ["接受神不照人意的拣选，安于本分"], "caution": ["不因被略过而轻看那蒙拣选的"], "applications": ["当神拣选了别人，你仍安于自己的位置", "不以排行、资历自恃", "在被略过时不嫉妒，在本分上忠心"], "scriptures": ["撒上16:9"]}, {"name": "他玛（大卫之女）", "lesson": "受害的尊贵公主，神必看顾", "witness": "他玛是大卫的女儿、押沙龙的妹妹，美丽而尊贵，却被同父异母的哥哥暗嫩设计玷辱，从此凄凉度日。她无辜受害，成了大卫家悲剧的开端。她的遭遇提醒：即使在尊贵之家，罪也能造成深重的伤害；但受害的人，神都看顾。", "summary": "大卫的女儿，押沙龙的妹妹，被暗嫩玷辱。", "prayer": "主啊，他玛无辜受害，凄凉度日。求祢安慰一切受侵害的人，作他们的看顾者与伸冤者，也使我成为保护、而非伤害人的人。阿们。", "tags": ["女性", "混合型"], "follow": ["在受害中仍保有为人的尊严"], "caution": ["（受害提醒）防范熟人之间的侵害，看重保护"], "applications": ["为遭受侵害的人提供保护与扶持，而非责备", "重视家庭内部的界限与保护", "相信神看顾、必为受害的人伸冤"], "scriptures": ["撒下13"]}, {"name": "基利押", "lesson": "名字一现，便归于沉寂", "witness": "基利押是大卫与亚比该所生的儿子，排行第二。圣经只在大卫众子名单中提了他一次，之后再无记载，可能早逝。在显赫的王室中，他是几乎被遗忘的一位——然而被人遗忘的，神并不遗忘。", "summary": "大卫与亚比该所生之子。", "prayer": "主啊，基利押几乎被人遗忘，祢却记念他。求祢使我不为被人记得而活，只求被祢记念，也教我珍惜每个看似平凡的生命。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": [], "applications": ["即使被世人遗忘，也相信神记念你", "不以'被记得'为人生的目标，而以讨神喜悦为念", "珍惜每个生命，纵然其事迹无多"], "scriptures": ["撒下3:3"]}, {"name": "巴西莱", "lesson": "在患难中慷慨供应的长者", "witness": "巴西莱是基列的老人，极其富足。大卫逃避押沙龙、最狼狈的时候，他送来床、粮、食物供养王和随从。后来大卫请他进宫享福，他却谦辞，只求归回故乡安度晚年。一位在患难中慷慨、在荣华前淡泊的长者。", "summary": "基列人，在大卫逃难时供应他。", "prayer": "主啊，巴西莱在大卫患难中慷慨供应，荣华前却淡泊知足。求祢使我在人患难时慷慨，在名利前知足，作慷慨而不贪的人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在别人患难、狼狈时慷慨供应", "面对荣华赏赐，淡泊知足、不贪恋"], "caution": [], "applications": ["在别人最难的时候伸出供应的手", "面对名利赏赐，存淡泊知足的心", "作一个慷慨而不贪恋的长者榜样"], "scriptures": ["撒下17,19"]}, {"name": "洗巴", "lesson": "趁主人落难，谋取私利", "witness": "洗巴是扫罗家的仆人，被派服事米非波设。大卫逃避押沙龙时，他带粮来迎，却趁机进谗言说主人米非波设盼望复国，骗取了主人的产业。趁主人落难、以谗言谋取私利，是仆人的不忠。", "summary": "扫罗家的仆人，服事米非波设。", "prayer": "主啊，洗巴趁主人落难进谗言谋私。求祢除去我里面趁机谋利、以谗言害人的心，使我在所服事的人身上存真实的忠诚。阿们。", "tags": ["其他", "混合型"], "follow": ["在主人患难时及时送上供应（表面之善）"], "caution": ["趁主人落难进谗言、谋私利", "以不实之词陷害人、夺取产业"], "applications": ["不趁别人落难时谋取私利、说人坏话", "在所服事的人有难时存真实的忠心", "不以谗言为自己捞取好处"], "scriptures": ["撒下9,16"]}, {"name": "示每", "lesson": "趁人落难，口出咒骂", "witness": "示每是便雅悯人、扫罗家族的人。大卫逃避押沙龙、最狼狈时，他沿路咒骂、扔石头，骂大卫是'流人血的坏人'。大卫却不许人杀他，把申冤交给神。后来大卫返京，他又赶来求饶。趁人落难时落井下石，是卑劣的。", "summary": "便雅悯人，大卫逃难时咒骂他。", "prayer": "主啊，示每趁大卫落难咒骂他。求祢除去我落井下石、口出恶言的心，使我在别人患难时存怜悯；受辱时学大卫把申冤交给祢。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["趁人落难时落井下石、口出咒骂", "见风使舵，得势时又来求饶"], "applications": ["不在别人落难时落井下石", "管住口，不趁机咒骂、羞辱人", "效法大卫：受辱时把申冤交给神"], "scriptures": ["撒下16"]}, {"name": "亚比筛", "lesson": "忠勇过人，也需被约束的烈性", "witness": "亚比筛是洗鲁雅的儿子、约押的兄弟，大卫的勇士，曾独自救大卫脱离非利士巨人之手。他对大卫极其忠勇，却也烈性十足，两次要杀咒骂大卫的示每、要杀熟睡的扫罗，都被大卫拦下。忠勇若不被约束，容易越界。", "summary": "洗鲁雅之子，约押之兄，大卫的勇士。", "prayer": "主啊，亚比筛忠勇却烈性难收。求祢赐我忠诚与勇敢，又以祢的怜悯约束我的烈性，使我不越过该有的界限。阿们。", "tags": ["其他", "混合型"], "follow": ["对所忠之人极其忠诚、舍命相护", "勇敢果决，危难中挺身而出"], "caution": ["烈性过头，动辄要取人性命", "需要被更高的怜悯与智慧约束"], "applications": ["以忠诚和勇敢服事，但让烈性受约束", "危难中挺身，却不越过怜悯的界限", "学习在该饶恕、该交托时收手"], "scriptures": ["撒上26", "撒下10"]}, {"name": "亚撒黑", "lesson": "勇猛却莽撞，快跑丧了命", "witness": "亚撒黑是洗鲁雅的儿子、约押的兄弟，大卫的勇士，脚快如野鹿。他在战场上紧追押尼珥不舍，押尼珥再三劝他转开，他却不听，终被押尼珥反手刺死。难得的勇猛与速度，因莽撞不听劝而断送了性命。", "summary": "洗鲁雅之子，跑得快，被押尼珥所杀。", "prayer": "主啊，亚撒黑勇猛却莽撞丧命。求祢使我善用所赐的才能，又有听劝的智慧，勇敢而不鲁莽，知道何时当收手。阿们。", "tags": ["其他", "混合型"], "follow": ["有勇猛、敏捷的过人之处"], "caution": ["恃才逞勇、莽撞不听劝", "在该收手时不肯收手"], "applications": ["发挥恩赐时也要听得进忠告", "勇猛而不莽撞，知道何时收手", "不恃才逞强，以致害己"], "scriptures": ["撒下2"]}, {"name": "雅朔班", "lesson": "勇士之首，一举击杀众敌", "witness": "雅朔班（又名约设巴设）是大卫勇士中的首领。他曾一次举枪杀了三百人（一作八百人），勇冠群雄。他把过人的勇力完全摆在保护神所膏立之王的事上——恩赐越大，越当用在对的地方。", "summary": "大卫勇士之首，又名约设巴设。", "prayer": "主啊，雅朔班勇冠群雄，尽忠护卫膏立之王。求祢使我把最强的恩赐用在祢的工作上，作带头立标杆的人，得胜归荣耀给祢。阿们。", "tags": ["其他", "正面榜样"], "follow": ["把过人的恩赐用在保护、成全神的工作上", "在勇士中作带头、立标杆的人"], "caution": ["不恃勇自夸，把荣耀归给神"], "applications": ["把你最强的恩赐摆在神的事工上", "作团队中立标杆、带头的人", "得胜时把荣耀归给神，不自夸"], "scriptures": ["代上11:11"]}, {"name": "以利亚撒（大卫勇士）", "lesson": "坚守到底，手粘在刀把上", "witness": "以利亚撒是大卫三勇士之一。一次与非利士人争战，众人退去，他却独自站住击杀敌人，直到手发酸、'手粘在刀把上'，那一天耶和华藉他大行拯救。当别人都退了，他还在坚持——胜利常属于那不肯放手的人。", "summary": "大卫三勇士之一。", "prayer": "主啊，以利亚撒坚守到手粘刀把，祢就藉他大行拯救。求祢赐我坚持到底的勇力，在众人退去时仍站立得稳，直到看见祢的拯救。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在众人退去时仍坚守岗位", "坚持到底，直到神成就拯救"], "caution": ["不在艰难中随众退缩"], "applications": ["当别人都放弃时，你仍坚守该守的", "在属灵的争战中坚持到底、不放手", "相信神会藉坚持到底的人施行拯救"], "scriptures": ["撒下23:9"]}, {"name": "沙玛（大卫勇士）", "lesson": "独守一块豆田的勇气", "witness": "沙玛是大卫三勇士之一。一次非利士人成群而来，众民都逃跑了，他却独自站在一块红豆田中守住，击杀非利士人，耶和华使以色列大获全胜。为了守住一块看似不起眼的'豆田'，他独自站住——忠心不挑岗位的大小。", "summary": "大卫三勇士之一，独守豆田击败非利士人。", "prayer": "主啊，沙玛为一块豆田独自站住，祢就使以色列得胜。求祢赐我坚守本分的勇气，哪怕岗位不起眼、众人都退，我仍站立得稳。阿们。", "tags": ["其他", "正面榜样"], "follow": ["为所托之地独自站住，不随众逃跑", "看重看似不起眼却当守的岗位"], "caution": [], "applications": ["为你当守的'豆田'（本分）坚守，哪怕别人都退了", "不因岗位不起眼就轻易放弃", "相信神在忠心坚守者身上施行拯救"], "scriptures": ["撒下23:11"]}, {"name": "洗鲁雅", "lesson": "一位母亲，养出三个猛将", "witness": "洗鲁雅是大卫的姊妹，约押、亚比筛、亚撒黑三位勇士的母亲。她的名字总是与三个儿子连在一起。她养育的儿子忠勇过人，却也烈性难驯——母亲塑造的，既是勇力，也当是品格。", "summary": "大卫的姊妹，约押、亚比筛、亚撒黑之母。", "prayer": "主啊，洗鲁雅养出三员猛将。求祢帮助为人父母的，既培养儿女的勇力，也塑造受祢约束的品格。阿们。", "tags": ["女性", "混合型"], "follow": ["养育下一代的勇气与担当"], "caution": ["勇力之外，更要塑造受约束的品格"], "applications": ["既培养儿女的能力，也塑造其品格", "看重母亲对下一代深远的影响", "为儿女的刚强求神加上柔和与节制"], "scriptures": ["代上2:16"]}, {"name": "希兰", "lesson": "以专长与资源，成全神的工", "witness": "希兰是推罗王，与大卫、所罗门交好，供应香柏木、工匠与技术，成全了圣殿的建造。他虽是外邦君王，却以自己的资源与专长参与在神的工程里——神也使用'界外'的祝福。", "summary": "推罗王，供应建殿的材料。", "prayer": "主啊，推罗王希兰以资源专长成全了建殿的工。求祢使我也甘心摆上所长，参与祢的工作，与众人同心建造祢的家。阿们。", "tags": ["君王", "正面榜样"], "follow": ["以自己的资源、专长成全神的工作", "与神的百姓建立互信的合作"], "caution": ["合作中仍要以神为中心，不被利益主导"], "applications": ["把你的专业与资源摆上，参与神国的建造", "与不同背景的人建立互信合作", "看见神能藉'界外'之人成就祂的工"], "scriptures": ["王上5"]}, {"name": "哈达", "lesson": "旧恨不消，成为日后的敌人", "witness": "哈达是以东王室的后裔，幼年逃往埃及躲过约押的剿杀，心里一直记恨。所罗门晚年偏离神时，神就兴起哈达作他的敌人。未了的旧恨，往往在人软弱时卷土重来。", "summary": "以东王室后裔，所罗门晚年的敌人。", "prayer": "主啊，哈达怀着旧恨成为所罗门的敌人。求祢医治我心里的创伤与苦毒，免得它生根结仇，使我成为饶恕而非记恨的人。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["让幼年的创伤化为终生的记恨", "伺机报复，成为他人衰败时的祸患"], "applications": ["处理心里的旧恨，免得它伺机反噬", "不在别人软弱时落井下石", "求神医治创伤，化解仇恨的根"], "scriptures": ["王上11:14-22"]}, {"name": "利逊", "lesson": "趁人偏离，兴起为敌", "witness": "利逊是亚兰人，聚集一伙人占据大马士革，在所罗门偏离神的晚年成为以色列的敌人。神兴起他作管教的器皿。强敌的兴起，常与神百姓属灵的偏离相伴而来。", "summary": "大马士革的亚兰人，所罗门的敌人。", "prayer": "主啊，所罗门偏离时，利逊就兴起为敌。求祢使我守住与祢的关系，不给仇敌可乘之机，也不趁人软弱去攻击人。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["趁人软弱偏离时兴起为敌", "以割据、敌对扩张自己"], "applications": ["明白属灵的偏离会招来'敌人'的兴起", "守住与神的关系，就是守住保障", "不趁人之危去攻击、扩张"], "scriptures": ["王上11:23-25"]}, {"name": "尼八", "lesson": "儿子的恶，冠在父亲的名下", "witness": "尼八是耶罗波安的父亲。圣经反复称北国诸王行'尼八的儿子耶罗波安所行的恶，使以色列陷在罪里'。尼八本人无甚记载，他的名字却因儿子设立金牛犊的大罪而被反复提起。儿女的影响，也会回照到父辈的名。", "summary": "耶罗波安的父亲。", "prayer": "主啊，尼八的名因儿子的大罪被反复提起。求祢帮助我引导下一代走正路，不使家族之名因后代的悖逆蒙羞。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（警醒）儿女的恶行，会令家族之名蒙羞"], "applications": ["看重对儿女的属灵引导，免得殃及家声", "为儿女走正路、不陷众人于罪祷告", "明白家族之名与后代的行为相连"], "scriptures": ["王上11:26"]}, {"name": "洗鲁阿", "lesson": "寡妇之子，也能被神兴起（或败坏）", "witness": "洗鲁阿是耶罗波安的母亲，一个寡妇。她的儿子从所罗门的臣仆被神兴起、得了北国十支派。然而耶罗波安却以金牛犊使全以色列陷在罪里。同一个母亲养大的孩子，可以被神高举，也可以走向败坏——关键在乎他自己的选择。", "summary": "耶罗波安的母亲，寡妇。", "prayer": "主啊，洗鲁阿的儿子蒙高举却带头犯罪。求祢帮助我在艰难中养育下一代，也保守蒙恩高举的人不致堕落，谨守到底。阿们。", "tags": ["女性", "混合型"], "follow": ["（为母提醒）在艰难中（寡居）养育儿女"], "caution": ["（背景）儿子被高举后却带头犯罪，令人叹息"], "applications": ["在艰难处境（如单亲）中仍尽心养育", "为被神高举的人祷告，免得他高举后堕落", "明白蒙恩之后更要谨守，不辜负"], "scriptures": ["王上11:26"]}, {"name": "示撒", "lesson": "离弃神，保障随之失去", "witness": "示撒是埃及王，在罗波安离弃耶和华律法的第五年北上攻打耶路撒冷，夺走圣殿和王宫的金宝，连所罗门所造的金盾牌都被掠去，只能用铜盾牌替代。一离弃神，昔日的荣耀与保障就接连流失。", "summary": "埃及王，攻打耶路撒冷夺取圣殿宝物。", "prayer": "主啊，罗波安离弃祢，示撒就来掠夺。求祢使我紧紧守住与祢的关系，不让昔日的恩典因我的偏离而流失。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["趁人离弃神、失去保护时入侵掠夺", "掠夺神殿与圣物，目中无神"], "applications": ["明白离弃神时，属灵的保障会随之失去", "守住与神的关系，就是守住真正的保障", "不趁人之危去掠夺"], "scriptures": ["王上14:25-26"]}, {"name": "所罗门的外邦妃嫔", "lesson": "枕边的影响，能偏转一颗智慧的心", "witness": "所罗门娶了许多外邦的妃嫔，她们各自引入本国的偶像。所罗门年老时，'他的妃嫔诱惑他的心去随从别神'，那位最有智慧的王，竟为她们建起邱坛。最亲密之人的潜移默化，能把一颗向神的心，一点点偏转过去。", "summary": "使所罗门的心偏离耶和华的外邦女子。", "prayer": "主啊，外邦妃嫔偏转了所罗门向祢的心。求祢保守我在最亲密的关系中仍向祢专一，也使我成为把人引向祢的影响，而非拉离祢的。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["在最亲密的关系中引入偏离神的影响", "以情感潜移默化地拉人随从别神"], "applications": ["谨慎最亲密关系对你信仰方向的影响", "在亲密关系中作把人引向神、而非拉离神的一方", "守住对神的专一，不被枕边风偏转"], "scriptures": ["王上11:1-8"]}, {"name": "西缅（雅各之子）", "lesson": "血气的烈怒，需要被神管理", "witness": "西缅是雅各与利亚的次子，为妹妹底拿受辱，与利未用诡计屠了示剑全城。他有护亲的烈性，却以残暴越过了公义的界限，临终被父亲预言后裔要分散在以色列中。烈怒若不被神管理，就成了咒诅。", "summary": "雅各与利亚的次子，西缅支派的祖先，为底拿向示剑报仇。", "prayer": "主啊，西缅的烈怒越界成了残暴。求祢管理我里面的血气与怒气，使我以公义和忍耐面对冤屈，不让烈性害人害己。阿们。", "tags": ["族长", "混合型"], "follow": ["对家人的受辱有真实的痛与担当"], "caution": ["以血气的烈怒越过公义的界限", "用诡计与过度的报复处理冤屈"], "applications": ["义愤来临时，把它交给神，不任凭血气", "以公义而非私刑处理被冒犯的事", "求神管理你的烈性，使之成为祝福而非破坏"], "scriptures": ["创29:33", "创34:25"]}, {"name": "利未（雅各之子）", "lesson": "被分散的，神也能使之被分别为圣", "witness": "利未是雅各的三子，曾与西缅一同因血气屠城，被预言要分散在以色列中。然而到了出埃及，利未支派因站在耶和华一边，这分散竟被神转化为分布全地的祭司与教导职分——咒诅被恩典翻转为服事。", "summary": "雅各与利亚的三子，利未支派与祭司体系的祖先。", "prayer": "主啊，祢把利未的分散翻转为分别为圣的服事。求祢也将我的亏缺与破碎，因祢的恩典转化为事奉祢、祝福人的器皿。阿们。", "tags": ["族长", "混合型"], "follow": ["在关键时刻站在神一边", "让神把过去的亏缺转化为服事的呼召"], "caution": ["年少时的血气曾带来咒诅，需引以为戒"], "applications": ["把人生的'分散'与亏缺交给神，求祂转化为祝福", "在抉择时刻坚定站在神一边", "看重教导与事奉的呼召"], "scriptures": ["创29:34", "出6:16"]}, {"name": "巴沙", "lesson": "靠杀戮上位，也走前人的老路", "witness": "巴沙篡夺拿答的王位，杀灭耶罗波安全家应验了预言，自己却照样行耶罗波安的恶，使以色列陷在罪里。他被神使用施行审判，却没有从被审判者的下场吸取教训，最终自家也遭同样的咒诅。", "summary": "篡夺拿答王位，行恶的北国王。", "prayer": "主啊，巴沙除灭恶王，自己却走同样的老路。求祢使我从别人的跌倒中得着鉴戒，不重蹈覆辙，行祢看为正的事。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["靠杀戮、政变攫取权力", "被神用来审判别人，自己却不引以为戒", "重蹈前人陷国于罪的覆辙"], "applications": ["不靠不义手段攫取地位", "从别人的失败中吸取教训，而非重蹈", "掌权后行在神眼中看为正的事"], "scriptures": ["王上15:16-16:7"]}, {"name": "以拉（以色列王）", "lesson": "醉生梦死，祸患临门不知", "witness": "以拉是巴沙的儿子，作以色列王。当军队在前线争战，他却在家宰的府里喝醉，被部下心利刺杀，巴沙全家随之被灭。身居高位却沉湎逸乐、玩忽职守，祸到临头还浑然不觉。", "summary": "巴沙之子，北国王，醉酒时被心利所弑。", "prayer": "主啊，以拉醉酒误事，祸到临头仍不知。求祢使我在所托的责任上清醒警醒，不沉迷逸乐，作忠心儆醒的人。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["在当尽责时沉湎逸乐、玩忽职守", "以醉酒麻痹自己，失去警觉"], "applications": ["在责任当头时不放纵享乐", "保持清醒与警觉，不被逸乐麻痹", "看重所托的职分，不玩忽职守"], "scriptures": ["王上16:8-10"]}, {"name": "心利", "lesson": "七日的王位，换来永远的骂名", "witness": "心利是以拉的部下，趁王醉酒弑君篡位，却只作了七日王。暗利率军围城，心利见大势已去，就放火烧宫自焚而死。靠背叛抢来的权位，转眼成空，只留下'弑君者'的骂名。", "summary": "作王仅七日的篡位者。", "prayer": "主啊，心利靠弑君篡位，七日而亡。求祢使我远离背叛与诡诈的捷径，以忠诚和正直行事，不贪一时之得。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["靠背叛、弑君攫取权位", "抢来的地位根基浮浅，转瞬即逝"], "applications": ["不靠背叛与不义去夺取你想要的", "记得不义得来的，往往转眼成空", "在忠诚与捷径之间，选择忠诚"], "scriptures": ["王上16:8-20"]}, {"name": "提比尼", "lesson": "争竞落败，也提醒纷争的代价", "witness": "暗利得国时，以色列民分为两半：一半随提比尼，一半随暗利。两派相争，提比尼落败而死，暗利得胜。一场王位之争，使本就软弱的北国更加分裂内耗。", "summary": "与暗利争夺王位失败。", "prayer": "主啊，提比尼在争位中落败，北国更显分裂。求祢使我不卷入无谓的派系之争，作促进合一、建造群体的人。阿们。", "tags": ["君王", "混合型"], "follow": [], "caution": ["卷入权力的派系之争", "使群体在内耗中更加分裂"], "applications": ["不轻易卷入派系与权力的争竞", "在分歧中寻求合一，减少内耗", "把精力放在建造而非争位上"], "scriptures": ["王上16:21-22"]}, {"name": "撒迦利雅（以色列王）", "lesson": "王朝的终点，应验神的话", "witness": "撒迦利雅是耶户的四世孙、耶户王朝的末代王，只作了六个月就被沙龙当众弑杀，正应验了神对耶户'子孙四代坐以色列国位'的话。神的应许与限度，一字不落地成就。", "summary": "耶户王朝末代，作王六个月被弑。", "prayer": "主啊，撒迦利雅作了耶户王朝的末代，应验了祢的话。求祢使我不倚仗过去的福分，自己存敬畏的心行义到底。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["承袭王朝却延续行恶的传统", "王朝的福分用尽，审判随之而来"], "applications": ["不倚仗家族过去的福分，自己要行义", "记得神的话必然应验，不可轻忽", "珍惜并续写而非耗尽属灵的产业"], "scriptures": ["王下15:8-12"]}, {"name": "沙龙（以色列王）", "lesson": "篡位一月，印证了审判", "witness": "沙龙弑撒迦利雅篡位，终结了耶户王朝，却只作了一个月的王，就被米拿现所杀。北国后期的弑君如走马灯，沙龙不过是其中一环——背叛带来背叛，流血招来流血。", "summary": "弑撒迦利雅篡位，作王仅一个月。", "prayer": "主啊，沙龙弑君篡位，转眼被弑。求祢使我不入暴力与背叛的循环，以正直和敬畏面对权力与冲突。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以弑君篡位开始，也以被弑收场", "卷入冤冤相报的暴力循环"], "applications": ["拒绝以暴力和背叛解决权力问题", "不参与冤冤相报的循环", "求神赐你在动荡中持守正直"], "scriptures": ["王下15:10-15"]}, {"name": "米拿现", "lesson": "残暴又苟安，留下沉重代价", "witness": "米拿现是北国王，以极残暴手段巩固权位，又向亚述王纳重银求得扶持，把负担转嫁给百姓。他靠外力苟安一时，却为北国的灭亡埋下伏笔。残暴加苟且，代价由后人承担。", "summary": "残暴的北国王，向亚述纳贡。", "prayer": "主啊，米拿现残暴苟安，贻害后人。求祢使我不以伤害人来自保，不为苟安牺牲他人，作顾念人、敬畏祢的人。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以残暴手段巩固权力", "靠贿赂强敌换取苟安，牺牲百姓"], "applications": ["不以伤害他人来巩固自己的地位", "不为眼前苟安牺牲长远与他人的利益", "掌权时顾念百姓的重担"], "scriptures": ["王下15:14-22"]}, {"name": "比加辖", "lesson": "承袭的王位，挡不住内部的背叛", "witness": "比加辖继承父亲米拿现作以色列王，行耶和华眼中看为恶的事，在位仅两年就被自己的军长比加所弑。承袭而来的权位，若无敬畏与根基，转眼就被身边人夺去。", "summary": "米拿现之子，被比加所弑。", "prayer": "主啊，比加辖承袭王位却行恶被弑。求祢使我承接的不只是位分，更是敬畏与正直，在所处之位上行祢看为正的事。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["承袭权位却承袭了同样的恶", "在动荡中疏于防备身边的野心"], "applications": ["不要只承袭地位，更要承袭正直与敬畏", "在位时行神看为正的事", "对身边的野心保持清醒"], "scriptures": ["王下15:23-26"]}, {"name": "比加", "lesson": "弑君与结盟，加速国家的崩塌", "witness": "比加弑比加辖篡位，又与亚兰王利汛结盟攻打犹大，招来亚述的报复，北国大片土地与人民被掳。他想靠武力与同盟自强，反而加速了国家的崩塌，最后也被何细亚所弑。", "summary": "北国王，与利汛联合攻犹大，国土被亚述夺取。", "prayer": "主啊，比加靠弑君与结盟自强，反加速败亡。求祢赐我在危机中不孤注一掷，不靠错误的同盟，单单寻求祢的指引。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["靠弑君与军事冒险求强", "错误的结盟引火烧身"], "applications": ["不靠暴力与冒险的联盟解决困局", "审慎判断结盟的后果", "在危机中寻求神，而非更大的赌注"], "scriptures": ["王下15:27-31"]}, {"name": "耶户（哈拿尼之子）", "lesson": "既要责备，也要肯定", "witness": "耶户是先见哈拿尼的儿子，既责备约沙法不该与恶王亚哈结盟，也肯定他'除掉木偶、立定心意寻求神'的善。他的责备带着分寸与公允——指出错处，也看见好处。", "summary": "责备约沙法与亚哈结盟的先知。", "prayer": "主啊，耶户责备约沙法也肯定他的善。求祢使我指正人时有分寸与公允，既说真话，也看见并肯定别人的美善。阿们。", "tags": ["先知", "正面榜样"], "follow": ["指正别人时，既说该说的责备，也肯定其善", "以公允而非一味否定待人"], "caution": ["不因要责备就抹杀对方的优点"], "applications": ["纠正人时，先肯定其可取之处再指出问题", "保持评价的公允与分寸", "为有权位的人祷告，也敢于提醒他们"], "scriptures": ["代下19:1-3"]}, {"name": "亚撒利雅（俄德之子）", "lesson": "及时的勉励，点燃改革", "witness": "亚撒利雅是俄德的儿子，在亚撒得胜归来时迎上去说：你们若寻求神，就必寻见；离弃祂，祂必离弃你们。一句及时的勉励，坚固了亚撒的心，推动了一场除偶像、修祭坛的复兴。", "summary": "劝勉亚撒推行宗教改革的先知。", "prayer": "主啊，亚撒利雅一句及时的话点燃了改革。求祢使我成为及时勉励人的口，把人的心转向寻求祢，推动归正与复兴。阿们。", "tags": ["先知", "正面榜样"], "follow": ["在关键时刻给人及时的属灵勉励", "把人的心转向寻求神"], "caution": ["勉励要建立在神的话上，不流于空话"], "applications": ["在别人得胜或低谷时，给予合时的属灵鼓励", "以神的应许坚固人的信心", "作推动复兴与归正的声音"], "scriptures": ["代下15:1-8"]}, {"name": "撒迦利亚（耶何耶大之子）", "lesson": "忠心到死，血不白流", "witness": "撒迦利亚是大祭司耶何耶大的儿子。约阿施忘了他父亲的恩，当撒迦利亚奉神责备百姓时，竟下令在殿院里用石头打死他。他临死说：愿耶和华鉴察伸冤。忠心的殉道，神都记念、必追讨。", "summary": "因责备约阿施而被石头打死的祭司。", "prayer": "主啊，撒迦利亚忠心传话至死，祢必为他伸冤。求祢使我忠心到底，受屈时把伸冤交给祢，也使我作不忘恩的人。阿们。", "tags": ["祭司", "正面榜样"], "follow": ["忠心传讲神的话，至死不改", "把伸冤交给鉴察万事的神"], "caution": ["（警戒约阿施）忘恩负义、以怨报德"], "applications": ["忠于神的托付，即使有危险也不退缩", "受冤屈时把伸冤交托给神", "不忘恩，不以怨报答曾帮助你的人"], "scriptures": ["代下24:20-22"]}, {"name": "乌利亚祭司", "lesson": "逢迎掌权者，扭曲了圣坛", "witness": "乌利亚是亚哈斯时期的祭司。王从大马士革看中一座异教祭坛的样式，吩咐照样建造，乌利亚就一一照办，把耶和华的铜坛挪到一旁。他用顺从换取王的欢心，却把神的圣坛改得面目全非。", "summary": "照大马士革坛样式为亚哈斯筑坛的祭司。", "prayer": "主啊，乌利亚为讨好亚哈斯改造了祢的坛。求祢使我不为讨好人而妥协祢的真理，守护敬拜的纯正，顺从祢过于顺从人。阿们。", "tags": ["祭司", "警戒为主"], "follow": [], "caution": ["为讨好掌权者而妥协信仰的原则", "把世俗的样式搬进神圣的敬拜"], "applications": ["不为讨好上位者而妥协真理与原则", "守护敬拜的纯正，不随流俗", "在压力下分辨：该顺从人还是顺从神"], "scriptures": ["王下16:10-16"]}, {"name": "希勒家", "lesson": "一卷重见天日的律法，带来全国复兴", "witness": "希勒家是约西亚时的大祭司，在修殿时发现了失落已久的律法书。他没有压下这惊人的发现，而是立刻呈报，引发了约西亚痛悔、洁净全地的大复兴。忠心守护并传递神的话，能改变一个时代。", "summary": "约西亚时的大祭司，发现律法书。", "prayer": "主啊，希勒家寻得律法书，带来全国复兴。求祢使我珍视、传递祢的话，不让它蒙尘，叫它在我和身边人中带来更新。阿们。", "tags": ["祭司", "正面榜样"], "follow": ["珍视并传递神的话，不隐藏", "在本职中忠心，带出更大的影响"], "caution": ["不要让神的话在'仓库'里蒙尘"], "applications": ["重新拾起被你冷落的神的话", "把所领受的真理传递出去，不私藏", "相信神的话能带来真实的更新"], "scriptures": ["王下22"]}, {"name": "沙番", "lesson": "忠实呈报，作王与神之间的桥", "witness": "沙番是约西亚的书记，把希勒家发现的律法书原原本本读给王听，又忠实办理修殿事务。他不是先知，却以一个文官的忠实，把神的话准确地送到王面前，促成了改革。", "summary": "约西亚时的书记，宣读律法书。", "prayer": "主啊，沙番忠实地把祢的话读给王听，促成了改革。求祢使我在本职上忠实准确，作连接真理与人心的桥梁。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在本职岗位上忠实、准确地办事", "作连接真理与决策者的桥梁"], "caution": ["不删改、不粉饰所当传达的信息"], "applications": ["在文书、行政等岗位上忠实尽责", "准确传达信息，不夹带私意", "看重'不起眼'的本职对大局的影响"], "scriptures": ["王下22"]}, {"name": "亚希甘", "lesson": "用自己的影响力护卫真理的人", "witness": "亚希甘是书记沙番的儿子、约西亚的重臣。当耶利米因传神的话面临死亡威胁，是亚希甘出面保护，使他不至被交在百姓手中处死。他用自己的地位与影响，护卫了一个说真话却不受欢迎的先知。", "summary": "沙番之子，保护耶利米。", "prayer": "主啊，亚希甘用地位护卫了耶利米。求祢使我善用所有的影响力，保护说真话、行公义的人，在群情汹涌时挺身护卫真理。阿们。", "tags": ["其他", "正面榜样"], "follow": ["用自己的地位与影响保护说真话的人", "在群情汹涌时挺身护卫义人"], "caution": ["不随众压制不受欢迎的真理传讲者"], "applications": ["用你的影响力保护说真话、行公义的人", "在群情激愤时作那个护卫义人的声音", "不因真理逆耳就附和打压"], "scriptures": ["王下22:12", "耶26:24"]}, {"name": "约拿达（利甲之子）", "lesson": "立下传统，造就世代的顺服", "witness": "约拿达是利甲族不饮酒、不盖房、寄居帐棚之传统的奠基者。数百年后，他的后裔利甲族人仍忠心遵守祖先的吩咐，被神立为顺服的榜样，对比悖逆的犹大。一个敬虔的家训，能造就世代的忠诚。", "summary": "利甲族不饮酒传统的奠基者。", "prayer": "主啊，约拿达立下的家训造就了利甲族世代的顺服。求祢帮助我为家庭立下敬虔的传统，以身作则，造就后代的忠诚。阿们。", "tags": ["其他", "正面榜样"], "follow": ["立下并传递敬虔、自律的家训", "为后代设立蒙福的属灵界限"], "caution": ["传统须服在神的旨意之下，不僵化"], "applications": ["为家庭立下敬虔、自律的好传统", "以身作则，使后代乐意遵守", "看重家训对世代的长远塑造"], "scriptures": ["王下10:15-23", "耶35"]}, {"name": "利甲族人", "lesson": "数百年如一日的顺服", "witness": "利甲族人世代谨守先祖约拿达的吩咐：不喝酒、不盖房、不种田、住帐棚。耶利米奉命用酒试他们，他们一概不喝。神就以他们的顺服，对比悖逆的犹大，应许他们必永远有人侍立在神面前。对所领受之命的长久持守，被神大大称许。", "summary": "顺服祖先吩咐、不喝酒的群体，被立为榜样。", "prayer": "主啊，利甲族数百年如一日地顺服，蒙祢称许。求祢使我对祢的吩咐长久持守、不打折扣，把敬虔的传统忠心守住、传下去。阿们。", "tags": ["其他", "正面榜样"], "follow": ["对所领受的吩咐长久、忠心地持守", "世代相传地守住家族的好传统"], "caution": [], "applications": ["对神的命令存长久持守、不打折的心", "守住家中敬虔自律的好传统", "让你的顺服成为对周围人的见证"], "scriptures": ["耶35"]}, {"name": "俄巴底（亚哈家宰）", "lesson": "在恶王手下，仍敬畏神、护卫先知", "witness": "俄巴底是亚哈王的家宰，'甚是敬畏耶和华'。在耶洗别大肆屠杀先知时，他冒死把一百个先知藏在洞里，以饼和水供养。身处恶王的宫廷，他却用自己的位置默默护卫神的仆人——黑暗中，仍有忠心的人。", "summary": "亚哈的家宰，敬畏神，藏匿一百个先知。", "prayer": "主啊，俄巴底在恶王宫中仍敬畏祢、护卫先知。求祢使我在败坏的环境中持守敬畏，用我的位置默默护卫祢的仆人与工作。阿们。", "tags": ["其他", "正面榜样"], "follow": ["身处败坏的环境，仍敬畏神", "冒险护卫、供养神的仆人"], "caution": ["不因环境黑暗就随波逐流"], "applications": ["在不利的环境中仍持守对神的敬畏", "用你的位置默默保护、供养神的工人", "相信黑暗中神总留下忠心的人，你可以是其一"], "scriptures": ["王上18:3-16"]}, {"name": "便哈达", "lesson": "狂傲叫阵，神必回应", "witness": "便哈达是亚兰王（数位同名），曾率三十二王围攻撒玛利亚，狂言要把城化为尘土。神却两次将他交在以色列手中，显明：不是因以色列强，乃要他们知道'耶和华是神'。狂傲的叫阵，神自有回应。", "summary": "亚兰王（数位同名），多次与以色列争战。", "prayer": "主啊，便哈达狂傲叫阵，祢却显明祢是神。求祢使我不以狂言压人，在威吓前仰望祢，并在经历中更深认识祢的主权。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以兵威狂言羞辱、恐吓对手", "屡败仍不认识那位掌权的神"], "applications": ["不以言语的狂傲恐吓、压制别人", "遇到恐吓时仰望神，而非被吓倒", "从经历中认识神的主权"], "scriptures": ["王上20", "王下6"]}, {"name": "利汛", "lesson": "结盟侵略，终被强权吞没", "witness": "利汛是亚兰王，与北国比加结盟夹攻犹大，逼得亚哈斯转投亚述。结果亚述大军南下，利汛被杀、大马士革被掳。靠侵略与结盟扩张的，最终被更大的强权吞没。", "summary": "亚兰王，与比加联合攻打亚哈斯。", "prayer": "主啊，利汛结盟侵略，终被强权吞没。求祢使我不靠欺压扩张，凡事寻求祢的智慧，走和平公义的道路。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以结盟侵略扩张势力", "引来更大的强权，自取灭亡"], "applications": ["不靠欺压邻舍来扩张自己", "审慎评估冒险扩张的后果", "在国际/人际的博弈中寻求神的智慧"], "scriptures": ["王下16:5-9"]}, {"name": "拉伯沙基", "lesson": "羞辱神的狂言，终被神堵住", "witness": "拉伯沙基是亚述王的将领，在耶路撒冷城下用犹大方言大声叫阵，羞辱、亵渎耶和华，动摇民心。希西家把他的话摊在神面前祷告，神当夜击杀亚述大军，堵住了一切狂言。", "summary": "亚述的将领，在耶路撒冷城下羞辱神。", "prayer": "主啊，拉伯沙基狂言羞辱祢，祢一夜之间堵住了他。求祢坚固我的信心，不被恐吓动摇，并谨守我的口尊祢为圣。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["以言语恐吓、亵渎，动摇人的信心", "把真神与假神相提并论，狂傲自大"], "applications": ["遇到亵渎与恐吓的言语，带到神面前祷告", "不被狂言动摇对神的信心", "谨守自己的口，不亵慢神圣的事"], "scriptures": ["王下18-19"]}, {"name": "提革拉毗列色", "lesson": "强权是神手中暂用的杖", "witness": "提革拉毗列色是亚述大帝，横扫列国，掳掠了以色列北部多地。亚哈斯曾向他纳贡求救，却引狼入室。圣经显明：这强权不过是神管教的杖——用完之后，杖也要被丢弃。", "summary": "亚述王，掳掠以色列北部。", "prayer": "主啊，提革拉毗列色不过是祢手中的杖。求祢使我不惧强权、不倚强权，认识列国兴衰都在祢的主权之下。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以强权征服掠夺，自以为不可一世", "成为别人'引狼入室'的祸患"], "applications": ["不倚仗强权，记得万王之上有神", "危机中不要病急乱投医、引狼入室", "看历史的兴衰，认识神的主权"], "scriptures": ["王下15:29", "王下16:7-10"]}, {"name": "撒缦以色", "lesson": "围城三年，印证背约的后果", "witness": "撒缦以色是亚述王，因何细亚背叛、转向埃及，就围困撒玛利亚三年，北国终于覆亡、百姓被掳。它的刀剑成了神对北国长久悖逆的审判句点——背约的后果，迟早临到。", "summary": "亚述王，围困撒玛利亚。", "prayer": "主啊，撒玛利亚因背约被撒缦以色所灭。求祢使我认真对待与祢的关系，不背离祢，趁今日回转，免得后果临到。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以兵威围困、灭国掳民", "成为审判的执行者却同样狂傲"], "applications": ["明白背离神的盟约，后果迟早临到", "在'围困'般的压力中省察自己的光景", "趁还有时候，回转归向神"], "scriptures": ["王下17:3-6"]}, {"name": "撒珥根", "lesson": "史册之外，神都掌管", "witness": "撒珥根是亚述大帝，以赛亚书记下他攻取亚实突的事。这位曾被史界质疑是否存在的王，如今考古已证实——再次印证神的话句句真实。列国的霸主来去，神的话却永远立定。", "summary": "亚述王，攻取亚实突。", "prayer": "主啊，撒珥根的事印证了祢话语的真实。求祢坚固我对祢话语的信靠，在列国兴衰中看见祢永不动摇的主权。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以武功自夸，目无上天的主宰"], "applications": ["信靠神话语的真实可靠，经得起检验", "不被霸权的声势迷惑，神更长久", "在历史的兴衰中看见神的主权"], "scriptures": ["赛20:1"]}, {"name": "以撒哈顿", "lesson": "强盛一时，仍在神的手中", "witness": "以撒哈顿是西拿基立的儿子，继位的亚述大帝，势力一度达到顶峰，连埃及也被他征服。然而再庞大的强权也终将过去——他迁来撒玛利亚的外族，后来成了撒玛利亚人的由来，神的历史仍照样推进。", "summary": "西拿基立之子，亚述王。", "prayer": "主啊，以撒哈顿强盛一时，仍在祢的手中。求祢使我不以势力自恃，谦卑认识万事万国都由祢掌管。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以强盛自恃，以为可永久掌控", "以迁徙混杂之策强行同化别族"], "applications": ["不因一时的强盛而自高", "记得最强的帝国也在神的手中", "看见神能从混乱的历史中继续推进祂的计划"], "scriptures": ["王下19:37", "拉4:2"]}, {"name": "施亚雅述", "lesson": "名字就是一篇盼望的信息", "witness": "施亚雅述是以赛亚的儿子，名字意为'余民必归回'。神吩咐以赛亚带着他去见亚哈斯王，这孩子的名字本身就是给那惊惶之王的信息：审判之后，神必留下归回的余民。他小小的存在，承载着神的盼望。", "summary": "以赛亚之子，名意为余剩的人必归回。", "prayer": "主啊，施亚雅述的名字宣告余民必归回。求祢使我在审判与惊惶中持守祢留余民的盼望，让我的生命也成为传递盼望的记号。阿们。", "tags": ["其他", "混合型"], "follow": ["以自己的存在承载神的盼望信息"], "caution": [], "applications": ["相信审判之中神总留下'归回的余民'的盼望", "让你的生命也成为传递盼望的记号", "在惊惶的时局中持守余民必存的应许"], "scriptures": ["赛7:3"]}, {"name": "玛黑珥沙拉勒哈施罢斯", "lesson": "圣经最长的名字，最短的警告", "witness": "他是以赛亚的儿子，名字意为'掳掠速临、抢夺快到'，是圣经中最长的人名。神吩咐起这名，作为给犹大的警告：在这孩子还不会叫父母之先，大马士革和撒玛利亚的财宝就要被亚述掳掠。一个名字，就是一则迫近的预言。", "summary": "以赛亚之子，名意为掳掠速临。", "prayer": "主啊，这孩子的名字宣告掳掠速临。求祢使我认真对待祢的警告，趁早回应、不轻忽，深信祢的话必按时应验。阿们。", "tags": ["其他", "混合型"], "follow": ["以自己的存在承载神的警告信息"], "caution": ["（警告）不可轻忽神所宣告迫近的审判"], "applications": ["认真对待神的警告，趁早回应", "明白神的预言必按时应验", "让生命成为传递神信息的记号"], "scriptures": ["赛8:1-4"]}, {"name": "米罗达巴拉但", "lesson": "殷勤的'好意'，也可能是试探", "witness": "米罗达巴拉但是巴比伦王，趁希西家病愈派使者来道贺送礼。希西家受宠若惊，把府库珍宝尽数显给他们看。以赛亚随即预言：这一切连同你的子孙，都要被掳到巴比伦去。殷勤的好意背后，藏着骄傲的试探。", "summary": "巴比伦王，派使者见希西家。", "prayer": "主啊，希西家因米罗达巴拉但的好意而炫耀，招来预言。求祢使我在恭维与顺境中保持谦卑警醒，不夸耀祢所赐的。阿们。", "tags": ["君王", "混合型"], "follow": [], "caution": ["（警戒希西家）被恭维冲昏头，炫耀所有", "看不出殷勤背后的图谋"], "applications": ["面对恭维与殷勤，保持清醒不张扬", "不向人炫耀神所赐的一切", "在顺境（病愈）中尤其要谨慎自守"], "scriptures": ["赛39", "王下20:12"]}, {"name": "以赛亚的妻子", "lesson": "与丈夫同负先知的使命", "witness": "以赛亚的妻子被称为'女先知'，为以赛亚生了名字本身就是预言的孩子（玛黑珥沙拉勒哈施罢斯）。她不只是先知的家属，更与丈夫一同背负传讲神信息的使命——连孩子的存在都成了给百姓的记号。", "summary": "被称为女先知，为以赛亚生子。", "prayer": "主啊，以赛亚的妻子与他同负使命。求祢使我与配偶同心，让我们的家庭一同成为传递祢信息、作祢见证的器皿。阿们。", "tags": ["女性", "正面榜样"], "follow": ["与配偶同心，一同承担属灵的使命", "让家庭也成为传递神信息的器皿"], "caution": [], "applications": ["与配偶同心服事，一同背负使命", "让你的家庭（包括儿女）成为见证", "看重夫妻在事奉上的同工"], "scriptures": ["赛8:3"]}, {"name": "西莱雅", "lesson": "忠心传递，把预言带到尽头", "witness": "西莱雅是尼利亚的儿子、巴录的兄弟。耶利米把一切论巴比伦的灾祸写在书上，交给西莱雅，吩咐他到巴比伦后宣读，再把书捆石头抛进幼发拉底河，象征巴比伦必如此沉下不再兴起。他忠心地把神的预言带到该到的地方、行该行的记号。", "summary": "尼利亚之子，巴录之兄，奉命将预言书带到巴比伦。", "prayer": "主啊，西莱雅忠心把预言带到巴比伦、行了记号。求祢使我忠心传递、执行祢所托付的话，并以行动印证我所信的真理。阿们。", "tags": ["其他", "正面榜样"], "follow": ["忠心传递、执行所托付的神的话", "以行动（记号）印证神的信息"], "caution": [], "applications": ["忠心完成神托付你传递的信息", "以具体行动配合所信的真理", "相信神的话必如预言所定的应验"], "scriptures": ["耶51:59-64"]}, {"name": "示玛雅（尼希兰人）", "lesson": "假冒先知，自招神的追讨", "witness": "示玛雅是被掳中的假先知，从巴比伦写信回耶路撒冷，要祭司压制耶利米、把他枷锁。耶利米宣告：神必追讨他，他的后裔必看不见神所要赐的福。冒神之名行己意的，神必追讨。", "summary": "从巴比伦写信攻击耶利米的假先知。", "prayer": "主啊，示玛雅假冒先知压制耶利米，自招追讨。求祢使我不冒祢的名行己意，谦卑领受真理，不压制祢所差的人。阿们。", "tags": ["先知", "警戒为主"], "follow": [], "caution": ["冒神之名说自己的话", "用职权压制真正传神话语的人"], "applications": ["不假借属灵权柄推行自己的意图", "尊重并保护忠心传讲真理的人", "在属灵的事上存战兢敬畏的心"], "scriptures": ["耶29:24-32"]}, {"name": "约哈难（加利亚之子）", "lesson": "善始却未善终，终究不肯听", "witness": "约哈难是犹大亡国后的军长，曾忠心追讨弑杀省长的以实玛利，救回被掳的余民，起初也来求问耶利米。然而当神的话不合他的心意（吩咐留在本地、不可下埃及），他就不肯听从，执意带众下了埃及。求问神，却只想听自己想听的，终归不顺服。", "summary": "犹大亡国后的军长，带百姓下埃及。", "prayer": "主啊，约哈难求问了祢，却不肯听祢的话。求祢使我求问祢时存真顺服的心，愿意接受不合己意的答案，真正照祢的话而行。阿们。", "tags": ["其他", "混合型"], "follow": ["有护卫余民、追讨凶手的担当", "愿意来求问神的心意"], "caution": ["求问神，却只接受合自己心意的答案", "明知神的吩咐仍执意己行"], "applications": ["求问神时，预备好接受不合己意的答案", "不要'问了又不听'，要真顺服", "在重大决定上，以神的话为准，而非自己的盘算"], "scriptures": ["耶40-43"]}, {"name": "以实玛利（尼探雅之子）", "lesson": "王室血统，沦为弑杀的凶手", "witness": "以实玛利是王室后裔，却受亚扪王指使，假意赴省长基大利的筵席，席间将他与同席的人尽行杀害，又掳走余民。高贵的出身没有拦住他的歹毒——血统不能担保品格。", "summary": "王室后裔，刺杀省长基大利。", "prayer": "主啊，以实玛利以王室之身行弑杀之恶。求祢洁净我的心，使我不以出身为作恶的资本，不被人利用去害人，以诚信待人。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["以诡诈与暴力夺权、泄愤", "受外力指使，残害自己的同胞"], "applications": ["不以出身、地位为作恶的资本", "拒绝被人利用去伤害他人", "以诚信待人，不设筵笑里藏刀"], "scriptures": ["耶41"]}, {"name": "尼布撒拉旦", "lesson": "毁城的人，却善待先知", "witness": "尼布撒拉旦是巴比伦的护卫长，奉命焚毁耶路撒冷、圣殿和王宫，掳走百姓。然而对耶利米，他却奉王命善待，给他自由、任他选择去留，还供给粮食。执行审判的手，也按神的安排护住了神的仆人。", "summary": "巴比伦的护卫长，焚毁耶路撒冷。", "prayer": "主啊，尼布撒拉旦毁城却善待耶利米。求祢使我在职责中仍存善心，也叫我看见祢的主权，连审判的手都在祢的掌管中。阿们。", "tags": ["其他", "混合型"], "follow": ["在职责之中仍善待该善待的人"], "caution": ["（背景）他是执行神审判的器皿，审判真实"], "applications": ["即使身负'拆毁'之职，也存善待人的心", "相信神能在审判中保全祂所要保全的", "看见神的主权连仇敌的手都能使用"], "scriptures": ["王下25:8-21", "耶39"]}, {"name": "尼布沙斯班", "lesson": "史册一笔，见证应验", "witness": "尼布沙斯班是巴比伦攻陷耶路撒冷时的一位官长，名字与同僚一同被记在城破之日。这些外邦官员的名字，成了'耶路撒冷照神的话被攻取'这一应验的历史注脚。神的话，连细节都不落空。", "summary": "巴比伦的官长。", "prayer": "主啊，尼布沙斯班的名字成了祢话语应验的注脚。求祢使我敬畏祢话语的真实，认真回应祢的警告，不存侥幸。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（背景）耶路撒冷的陷落是悖逆的后果"], "applications": ["敬畏神话语的真实，连细节都必应验", "从历史的细节中看见神主权的痕迹", "认真对待神的警告，不存侥幸"], "scriptures": ["耶39:13"]}, {"name": "尼甲沙利薛", "lesson": "坐在城门口的权贵，也在神手中", "witness": "尼甲沙利薛是巴比伦的高官，城破后与众官长一同'坐在中门'——握有审断之权。这些显赫一时的权贵，不过是神用来成就审判的器皿；权势再大，仍在那位真正掌权者的手中。", "summary": "巴比伦的官长。", "prayer": "主啊，尼甲沙利薛坐在权力的中门，仍是祢手中的器皿。求祢使我不被权势迷惑，敬畏那位真正掌权到永远的祢。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["以为坐在'权力的中门'便可永久掌断"], "applications": ["不被显赫的权位迷惑，神在其上", "记得人间的权柄都是暂借、受限的", "在权力者面前仍敬畏那位真正掌权的神"], "scriptures": ["耶39:3,13"]}, {"name": "布西", "lesson": "把信仰的根，传给下一代", "witness": "布西是先知以西结的父亲，身为祭司。圣经只记下他的名，但正是这祭司之家，养育出在被掳之地仍忠心传神话语的以西结。默默传承信仰的父辈，常是下一代属灵生命的根。", "summary": "以西结的父亲，祭司。", "prayer": "主啊，布西这祭司之家养育了以西结。求祢使我忠心地把信仰的根传给下一代，在平凡中为他们的属灵生命扎根。阿们。", "tags": ["祭司", "混合型"], "follow": ["在家庭中默默传承信仰的根基", "以自己的身份与职分影响下一代"], "caution": ["不忽略对子女属灵生命的栽培"], "applications": ["看重把信仰传给儿女、后辈", "在平凡中作下一代属灵生命的根", "相信家庭的属灵传承被神记念"], "scriptures": ["结1:3"]}, {"name": "亚施毗拿", "lesson": "位高的太监，以善意待人", "witness": "亚施毗拿是巴比伦王的太监长，奉命挑选但以理等少年受训。当但以理求他容许不吃王膳，他虽有顾虑（怕王见他们面黄），却以善意相待，默许了试验之路。一个外邦官员的体谅，为但以理的忠贞留出了空间。", "summary": "巴比伦的太监长，管理但以理等人。", "prayer": "主啊，亚施毗拿以善意待但以理，为他的忠贞留了空间。求祢使我在职权中以善意体谅人，为别人持守原则留出余地。阿们。", "tags": ["其他", "混合型"], "follow": ["在职权范围内以善意、通融待人", "体谅他人的难处与坚持"], "caution": ["善意中仍要兼顾职责的稳妥"], "applications": ["在管理岗位上以善意体谅下属的难处", "为别人持守原则留出空间", "在制度与人情之间寻求两全的智慧"], "scriptures": ["但1:3-7"]}, {"name": "亚略", "lesson": "奉命行事，也能存一分体恤", "witness": "亚略是巴比伦王的护卫长，奉命去杀尽巴比伦的哲士（包括但以理）。但以理用'婉言'求他宽限，他便容但以理进去见王求时日。身负王命的执行者，仍在缝隙里给了智慧人一线生机。", "summary": "巴比伦王的护卫长。", "prayer": "主啊，亚略奉命行事却给了但以理转圜的机会。求祢使我在职责中仍存体恤，为人留一线生机。阿们。", "tags": ["其他", "混合型"], "follow": ["在执行职务时仍存一分体恤", "给人合理的申诉与转圜空间"], "caution": [], "applications": ["执行规定时，也为人留一线转圜", "以体恤待处境艰难的人", "在职责与人情间寻求智慧"], "scriptures": ["但2:14-25"]}, {"name": "大利乌（玛代人）", "lesson": "敬重神仆，胜过臣仆的诡计", "witness": "玛代人大利乌中了臣仆的圈套，被迫把但以理扔进狮坑，却整夜禁食难眠。天一亮就跑去呼喊，见但以理蒙神保全，便下令全国都当敬畏但以理的神。他虽一时软弱，终究站在了神这边。", "summary": "在伯沙撒之后掌权，将但以理投入狮坑又救他。", "prayer": "主啊，大利乌虽一时软弱，终究敬重了但以理和他的神。求祢使我不因面子妥协，敬重忠心爱祢的人，引人敬畏祢。阿们。", "tags": ["君王", "混合型"], "follow": ["敬重忠心事神的人", "看见神的作为，就引导众人敬畏神"], "caution": ["因爱面子、怕臣仆而一时妥协立恶法"], "applications": ["不因面子或人言而做违心、害人的决定", "为身边忠心爱主的人提供支持", "看见神的作为，就带动别人一同敬畏祂"], "scriptures": ["但6"]}, {"name": "耶斯列（何西阿之子）", "lesson": "名字里的审判，也藏着盼望", "witness": "耶斯列是先知何西阿的长子，神吩咐起这名字，作为对耶户家流血、对北国审判的记号。然而'耶斯列'本意是'神栽种'——在审判的名字里，神也埋下了重新栽种、复兴的盼望。", "summary": "何西阿的长子，象征审判的名字。", "prayer": "主啊，耶斯列的名字既是审判也是盼望的'神栽种'。求祢使我在管教中看见祢栽种、复兴的心意，顺服祢的安排。阿们。", "tags": ["其他", "混合型"], "follow": ["顺服神，即使所托带着难解的意义"], "caution": ["（背景警戒）耶户家滥流人血，招致审判"], "applications": ["在难解的处境中相信神有更深的安排", "看见神的管教里也藏着复兴的盼望", "顺服神交托的角色，哪怕不被理解"], "scriptures": ["何1:4"]}, {"name": "罗路哈玛", "lesson": "'不蒙怜悯'的名字，藏着怜悯的应许", "witness": "罗路哈玛是先知何西阿的女儿，名字意为'不蒙怜悯'，作为神对悖逆之以色列的审判记号。然而神紧接着应许：日后必有转机，'不蒙怜悯的'要重得怜悯。审判的名字里，埋着恢复的盼望。", "summary": "何西阿的女儿，名意为不蒙怜悯。", "prayer": "主啊，罗路哈玛的名字宣告审判，祢却应许怜悯必临。求祢使我在管教中仰望祢恢复的怜悯，也为远离祢的人祷告归回。阿们。", "tags": ["女性", "混合型"], "follow": ["在审判的记号中仍持守怜悯必临的盼望"], "caution": ["（警告）悖逆使人一度落到'不蒙怜悯'"], "applications": ["在管教中仍仰望神怜悯的恢复", "相信神的审判里藏着恢复的应许", "为'一度不蒙怜悯'的人祷告归回"], "scriptures": ["何1:6"]}, {"name": "罗阿米", "lesson": "'非我民'之后，是'我民'的应许", "witness": "罗阿米是何西阿的儿子，名字意为'非我民'，宣告神与悖逆之以色列关系的断绝。然而神随即应许：从前在什么地方对他们说'你们不是我的子民'，将来必对他们说'你们是永生神的儿子'。最深的断绝里，神预备了最深的接纳。", "summary": "何西阿的儿子，名意为非我民。", "prayer": "主啊，罗阿米的名字宣告'非我民'，祢却应许必称他们为神的儿子。求祢使我深信祢恢复的大爱，也为疏离祢的人祷告重归。阿们。", "tags": ["其他", "混合型"], "follow": ["持守'必再被称为神子民'的恢复盼望"], "caution": ["（警告）悖逆使人一度沦为'非我民'"], "applications": ["在关系疏离中仰望神恢复的应许", "相信神能把'非我民'重新接纳为儿女", "为与神疏远的人祷告归回"], "scriptures": ["何1:9"]}, {"name": "亚米太", "lesson": "先知之父，名字留在源头", "witness": "亚米太是先知约拿的父亲，迦特希弗人。圣经记下他的名，作为约拿身份的源头。一个不显眼的父亲，养育出那位被神差往尼尼微的先知——尽管约拿的顺服一波三折，他的根仍在这个家。", "summary": "约拿的父亲。", "prayer": "主啊，亚米太养育了先知约拿。求祢使我在不显眼处忠心，作下一代蒙召者的根，为他们将来事奉祢的呼召祷告。阿们。", "tags": ["其他", "混合型"], "follow": ["默默作下一代蒙召者的根"], "caution": [], "applications": ["看重养育下一代蒙召者的责任", "在不显眼处忠心，影响却可能深远", "为儿女将来的呼召祷告"], "scriptures": ["拿1:1", "王下14:25"]}, {"name": "比利家", "lesson": "先知之父，承上启下", "witness": "比利家是先知撒迦利亚的父亲、易多的儿子，身处归回重建的世代。他自己事迹无多，却是连接先知世家的一环，养育出鼓励百姓建殿的撒迦利亚。承上启下的一代，也在神的计划中。", "summary": "撒迦利亚先知的父亲。", "prayer": "主啊，比利家承接先知世家，养育了撒迦利亚。求祢使我忠心承上启下，把所领受的信仰传给下一代。阿们。", "tags": ["其他", "混合型"], "follow": ["在世代之间承上启下，忠心传承"], "caution": [], "applications": ["看重自己在信仰世代中的承接位置", "忠心把所领受的传给下一代", "相信承上启下的一代也蒙神记念"], "scriptures": ["亚1:1"]}, {"name": "易多", "lesson": "属灵的影响，隔代结果", "witness": "易多是先知撒迦利亚的祖父，也被记为先知/先见。两三代之后，他家中兴起了归回时期重要的先知撒迦利亚。属灵的影响常常隔代发酵——今日的忠心，会在子孙身上结出果子。", "summary": "撒迦利亚先知的祖父。", "prayer": "主啊，易多的忠心隔代结出撒迦利亚的果子。求祢使我今日忠心爱祢，为子孙积存属灵的产业，影响我看不见的将来。阿们。", "tags": ["先知", "混合型"], "follow": ["以今日的忠心，为子孙后代积存属灵的产业", "看重隔代的属灵影响"], "caution": ["不轻看自己今日忠心的长远价值"], "applications": ["相信你今日的信仰会影响子孙后代", "为后代的属灵生命祷告、积存祝福", "忠心走好这一代，把棒交下去"], "scriptures": ["亚1:1", "拉5:1"]}, {"name": "设巴萨", "lesson": "带着圣物归回，重启敬拜", "witness": "设巴萨是被掳归回的早期领袖，古列把从圣殿掳去的金银器皿点交给他带回耶路撒冷，并立下圣殿根基。他低调地承接了'归回与重建'的第一棒，使中断的敬拜得以重启。", "summary": "被立为犹大省长，带回圣殿器皿的归回领袖。", "prayer": "主啊，设巴萨带着圣物归回，重启了敬拜。求祢使我在荒废与中断之后，忠心承接重建的责任，把敬拜带回正轨。阿们。", "tags": ["其他", "正面榜样"], "follow": ["忠心承接归回与重建的责任", "看重把'圣物'（神圣的托付）带回正轨"], "caution": ["重建之路漫长，需要持守不灰心"], "applications": ["在荒废之后，作那个重启的人", "忠心保管并归还神圣的托付", "为属灵的'重建'摆上你的一份"], "scriptures": ["拉1:8-11", "拉5:14"]}, {"name": "约萨达", "lesson": "在被掳中，守住祭司的香火", "witness": "约萨达是被掳到巴比伦的祭司，自己未能回归，却生养了归回后的大祭司耶书亚。国破、殿毁、被掳异乡，祭司的香火却没有断——他在黑暗中守住了传承，使复兴有了接棒的人。", "summary": "耶书亚大祭司的父亲。", "prayer": "主啊，约萨达在被掳中守住了祭司的香火，养育了耶书亚。求祢使我在艰难中持守信仰，为下一代守住属灵的传承。阿们。", "tags": ["祭司", "混合型"], "follow": ["在患难流离中持守信仰与身份", "为下一代守住属灵的传承"], "caution": ["不因环境艰难就放弃所承接的圣职传统"], "applications": ["在流离、不利的环境中持守信仰", "纵然自己看不到果子，也为下一代守住", "相信你守住的传承，神必接续使用"], "scriptures": ["拉3:2", "该1:1"]}, {"name": "哈拿尼（尼希米之兄）", "lesson": "一句真实的报告，点燃重建", "witness": "哈拿尼是尼希米的兄弟，从犹大来，如实报告耶路撒冷城墙拆毁、城门被火焚烧、余民大遭凌辱的光景。正是这真实的报告，刺痛并点燃了尼希米回去重建的心志。一句忠实的话，能开启一场复兴。", "summary": "尼希米的兄弟，被派管理耶路撒冷。", "prayer": "主啊，哈拿尼如实的报告点燃了尼希米重建的心。求祢使我作说真话的人，以真实的负担激励改变，不粉饰、不回避。阿们。", "tags": ["其他", "正面榜样"], "follow": ["如实报告所见的实情，不粉饰", "以真实的负担激励行动"], "caution": ["不报喜不报忧，掩盖真实需要"], "applications": ["如实反映你所看见的需要与光景", "用真实的负担去激励该行动的人", "不粉饰太平，让真相催生改变"], "scriptures": ["尼1:2", "尼7:2"]}, {"name": "示玛雅（阻挠尼希米）", "lesson": "受雇的'属灵建议'，要分辨", "witness": "这位示玛雅受多比雅、参巴拉收买，假意警告尼希米躲进圣殿避险，想引他犯规、败坏名声。尼希米却分辨出'神并没有差遣他'，拒绝中计。包着属灵外衣的建议，也需要分辨真伪。", "summary": "受雇恐吓尼希米的假先知。", "prayer": "主啊，尼希米识破了示玛雅受雇的诡计。求祢赐我分辨的灵，不被属灵外衣的恐吓与建议所惑，稳行在祢的旨意中。阿们。", "tags": ["先知", "警戒为主"], "follow": [], "caution": ["被人收买，以'属灵建议'引人犯错", "用恐吓、危言耸听操纵他人"], "applications": ["对披着属灵外衣的建议保持分辨", "遇恐吓时不慌张，先求问神的心意", "不被收买去损害别人的事工与名声"], "scriptures": ["尼6:10-13"]}, {"name": "挪亚底", "lesson": "女先知的名分，用错了地方", "witness": "挪亚底是一位女先知，却与一群假先知一同受雇，要使尼希米惧怕、犯错。她有'先知'的名分，却站在了拦阻神工作的一边。属灵的恩赐与名分，若不顺服神，反成拦阻。", "summary": "恐吓尼希米的女先知。", "prayer": "主啊，挪亚底以先知之名拦阻尼希米。求祢使我把属灵的恩赐用在成全祢的工上，而非拦阻；常省察我站在哪一边。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["以属灵名分行拦阻神工作的事", "受雇恐吓、动摇行善的人"], "applications": ["不以属灵身份去拦阻别人行神的工", "常省察自己站在成全还是拦阻的一边", "拒绝被收买去恐吓、动摇人"], "scriptures": ["尼6:14"]}, {"name": "哈拿尼雅（尼希米治理者）", "lesson": "忠信敬畏，堪当托付", "witness": "哈拿尼雅是被尼希米派去管理耶路撒冷营楼的人，因为他'是忠信的，又敬畏神过于众人'。尼希米选人，看的不是关系，而是忠信与敬畏。这两样，使他堪当重任。", "summary": "忠信敬畏神，被派管理耶路撒冷营楼。", "prayer": "主啊，哈拿尼雅因忠信敬畏被委以重任。求祢使我作忠信、敬畏祢的人，在所托的岗位上可靠尽责。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以忠信与敬畏神赢得托付", "在所托的岗位上尽责可靠"], "caution": [], "applications": ["让'忠信、敬畏神'成为你被人信任的根基", "在岗位上做可靠、可托付的人", "选人用人，也看重忠信与敬畏"], "scriptures": ["尼7:2"]}, {"name": "细利斯", "lesson": "献毒计的妻子，也预感败亡", "witness": "细利斯是哈曼的妻子。当哈曼忿恨末底改，是她和友人献计：立一个高五十肘的木架，把末底改挂上去。可当哈曼开始走下坡，她又改口说：你在末底改面前必定败落。她既助纣为虐，又见风预言败亡。", "summary": "哈曼的妻子，献计立木架害末底改。", "prayer": "主啊，细利斯为哈曼献了害人的毒计。求祢使我在家中作劝善的声音，不助人作恶，也不见风使舵只图自保。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["为亲人出谋，却是害人的毒计", "见利时助恶，见势败时又抽身"], "applications": ["不为亲友出'害人'的主意", "在家庭中作劝善而非助恶的声音", "不做见风使舵、只顾自保的人"], "scriptures": ["斯5-6"]}, {"name": "哈曼十子", "lesson": "恶的传承，同归败亡", "witness": "哈曼的十个儿子继承了父亲对犹大人的仇恨，在那场反扑中一同被除，十人的名字被一并列出。父亲所走的恨恶之路，儿子们一同走到了尽头。罪与恨若在家族中传承，带来的是全家共负的结局。", "summary": "哈曼的十个儿子，与父一同灭亡。", "prayer": "主啊，哈曼十子承袭父恨，同归败亡。求祢帮助我斩断家族中仇恨与恶的传承，作打破循环的人，带领家走向祢的祝福。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["承袭父辈的仇恨与恶行", "全家同走悖逆之路，同负其果"], "applications": ["不让仇恨与恶在家族中代代相传", "在家族中作打破罪之循环的那一个", "为家族的属灵方向警醒、祷告"], "scriptures": ["斯9:7-10"]}, {"name": "希该", "lesson": "善待所托，助人蒙恩", "witness": "希该是管理后宫女子的太监。以斯帖被带进宫时，希该'喜悦她，恩待她'，赶紧给她当用的香品、份饭和七个宫女，把她安置在最好的地方。他在职权之内的善意，默默成全了日后拯救犹大人的以斯帖。", "summary": "管理后宫女子的太监，善待以斯帖。", "prayer": "主啊，希该恩待以斯帖，默默成全了拯救。求祢使我善待所照管的人，用我的位置成全别人的蒙福。阿们。", "tags": ["其他", "混合型"], "follow": ["在职权之内善待所托付的人", "以恩待成全别人的蒙福"], "caution": [], "applications": ["善待落在你照管之下的人", "用你的位置成全别人的好处", "相信一个小小的恩待，神能大大使用"], "scriptures": ["斯2:8-15"]}, {"name": "沙甲", "lesson": "尽本分的无名管事", "witness": "沙甲是管理妃嫔的太监，在以斯帖记中只被提了名与职。他在波斯宫廷庞大的体系里，默默尽着自己的一份本分。圣经记下他的名，提醒我们：体系中每个尽责的小角色，神都看见。", "summary": "管理妃嫔的太监。", "prayer": "主啊，沙甲在宫廷体系中默默尽责。求祢使我在所在的体系里忠心尽本分，深知祢看见每个尽责的小角色。阿们。", "tags": ["其他", "混合型"], "follow": ["在庞大的体系中默默尽本分"], "caution": [], "applications": ["在大机构、大体系里忠心尽自己的一份", "不轻看'小角色'的尽责", "相信神看见每个默默尽本分的人"], "scriptures": ["斯2:14"]}, {"name": "哈波拿", "lesson": "关键一句话，推动公义", "witness": "哈波拿是侍立在王前的太监。当哈曼的恶被揭露，正是他开口说：哈曼为救王有功的末底改所预备的木架还立在他家里呢！王就吩咐把哈曼挂在其上。一句适时的话，把公义推到了实处。", "summary": "指出哈曼木架的太监。", "prayer": "主啊，哈波拿一句话推动了公义的成就。求祢使我在关键时刻敢于发声，让我的言语服务于祢的公义。阿们。", "tags": ["其他", "混合型"], "follow": ["在关键时刻说出推动公义的话"], "caution": [], "applications": ["在关键时刻，敢于说出促成公义的话", "留意身边的不公，适时发声", "让自己的发言服务于公义而非逢迎"], "scriptures": ["斯7:9"]}, {"name": "比革他", "lesson": "守门的人，却图害主人", "witness": "比革他是看守宫门的太监，本当护卫王的安全，却与提列同谋下手害王。他被末底改揭发，落得挂在木头上的结局。受托守护的人反成内患，是最危险的背叛。", "summary": "图谋杀王的太监。", "prayer": "主啊，比革他受托守门却图害王，终被揭发。求祢使我在受托的位置上忠心护卫，不因不满而背叛信任我的人。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["受托守护，却图谋伤害", "以内部之便行背叛之实"], "applications": ["在受托守护的位置上存真实的忠心", "不因不满而背叛信任你的人", "记得暗中的图谋终必败露"], "scriptures": ["斯2:21-23"]}, {"name": "提列", "lesson": "心怀怨恨，谋害恩主", "witness": "提列是守门的太监，与比革他同因恼恨，图谋下手害亚哈随鲁王。阴谋被末底改察觉、揭发，二人被挂在木头上。心怀怨恨而谋害自己所当效忠的人，终被揭露受刑。", "summary": "与比革他同谋害王的太监。", "prayer": "主啊，提列因恼恨谋害王，终被揭发受刑。求祢除去我心里的怨恨，使我对当效忠的人忠信，不容阴谋在暗处滋长。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["因恼恨而图谋伤害当效忠的人", "以阴谋背叛信任你的人"], "applications": ["处理心里的恼恨，不让它酿成阴谋", "对所当效忠的人存忠信", "记得暗中的阴谋，神必使之败露"], "scriptures": ["斯2:21-23"]}, {"name": "东方博士", "lesson": "循着星光，长途来朝拜君王", "witness": "东方博士是外邦的智者，看见那星，就不远千里前来，定意要拜'那生下来作犹太人之王的'。他们在伯利恒见了婴孩，俯伏敬拜，献上黄金、乳香、没药，又顺服梦中的指示，不回去见希律。外邦人循着微光真诚寻求，终于寻见了真君王。", "summary": "从东方来拜见婴孩耶稣的智者。", "prayer": "主啊，东方博士循星光远来朝拜祢、献上至宝。求祢使我也真诚寻求祢，寻见就俯伏敬拜、献上最好的，并顺服祢的指引。阿们。", "tags": ["其他", "正面榜样"], "follow": ["循着神所赐的光真诚寻求，不辞路远", "寻见主就俯伏敬拜、献上至宝", "顺服神的指示，不与恶势力妥协"], "caution": [], "applications": ["循着你所得的亮光，认真寻求主", "寻见主，就献上你最好的敬拜与所有", "顺服神的指引，不向'希律'式的势力妥协"], "scriptures": ["太2"]}, {"name": "牧羊人", "lesson": "卑微的牧人，头一批听见喜信", "witness": "牧羊人在伯利恒野地夜间看守羊群，天使却向这群社会底层的人显现，报告大喜的信息：'今天在大卫的城里，为你们生了救主。'他们就急忙去看，见了就把这事传开，又归荣耀给神。救主降生的喜讯，头一批临到的竟是卑微的牧人。", "summary": "伯利恒野地里得见主降生的牧人。", "prayer": "主啊，救主降生的喜讯头一批临到卑微的牧人。求祢使我也急忙寻见祢，见了就传扬开来，把荣耀归给祢。阿们。", "tags": ["其他", "正面榜样"], "follow": ["听见喜信就急忙前去寻见主", "见了主就传扬、归荣耀给神"], "caution": [], "applications": ["相信福音的喜讯也临到卑微的你", "听见主的呼召就立刻回应、前去", "见了主就把好消息传开，荣耀归神"], "scriptures": ["路2:8-20"]}, {"name": "希律大帝", "lesson": "惧怕失去王位的人，连婴孩也不放过", "witness": "希律大帝多疑而残暴，听见'犹太人的王'降生，竟下令杀光伯利恒两岁以内的男婴。他用尽手段保住王位，却保不住自己的结局。把权位看得高过一切的人，会为它做出最黑暗的事。", "summary": "屠杀伯利恒婴孩的犹太王。", "prayer": "主啊，希律大帝为保王位连婴孩都不放过。求祢挪去我心里对地位与掌控的偏执，使我的安全感建立在祢身上，不伤害任何人。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["把权位看得高过一切，甚至不惜伤害无辜", "以多疑与残暴来保住自己拥有的"], "applications": ["省察自己是否为'保住所有'而伤害他人", "放下对地位与掌控的偏执", "把人生的安全感建立在神而非权位上"], "scriptures": ["太2"]}, {"name": "希律安提帕", "lesson": "良心未泯，却被面子与情欲拖垮", "witness": "希律安提帕囚禁施洗约翰，心里却'敬畏他、乐意听他'——良心尚未全死。可是为了在生日宴上不失面子，他竟因一个起誓杀了约翰；后来又戏弄受审的耶稣。被面子与情欲牵着走的人，会一步步背弃所知的良善。", "summary": "杀施洗约翰、审问耶稣的分封王。", "prayer": "主啊，希律安提帕为面子杀了约翰，违背了良心。求祢使我不为情欲与面子出卖所知的良善，听了真理就甘心遵行。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["为面子、情欲牺牲良心所知的对的事", "明知是义人，仍不肯付代价护卫"], "applications": ["不为面子和场面做违背良心的事", "谨慎你的承诺与起誓，不被绑架", "听见真理时，要行出来而非只'乐意听'"], "scriptures": ["可6", "路23"]}, {"name": "希律腓力", "lesson": "被夺去妻子的人，牵进一桩罪案", "witness": "希律腓力是希罗底的前夫。他的兄弟希律安提帕夺了他的妻子希罗底，施洗约翰因责备这桩乱伦的婚姻而被下监、被杀。希律腓力本人着墨不多，却牵在一桩因情欲与权势而起的罪案之中。", "summary": "希罗底的前夫。", "prayer": "主啊，希律家因情欲权势酿成大罪。求祢使我守住婚姻与道德的界限，不被情欲权势缠累，远离一切因私欲而起的恶。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（背景）权势与情欲交织，酿成杀义人之罪"], "applications": ["看见情欲与权势纠缠所酿的恶果", "守护婚姻的界限，不越界、不夺取", "为被卷入他人罪案而受害的人代求"], "scriptures": ["可6:17"]}, {"name": "希罗底", "lesson": "怀恨义人，借刀杀人", "witness": "希罗底因施洗约翰责备她与希律安提帕的乱伦婚姻，就怀恨在心，要杀他。她借女儿在宴上的舞蹈、借希律的轻率起誓，要来了约翰的头。被真理刺中却不肯悔改的人，会想方设法除掉那说真话的人。", "summary": "唆使杀施洗约翰的妇人。", "prayer": "主啊，希罗底怀恨约翰、借刀杀人。求祢使我被真理责备时甘心悔改，不记恨、不报复，以悔改而非除掉真理来回应。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["被真理责备时，怀恨而非悔改", "借机、借人之手除掉说真话的人"], "applications": ["被指出错处时选择悔改，而非记恨", "不借他人之手去报复、除掉对头", "守护婚姻与道德，不文过饰非"], "scriptures": ["可6"]}, {"name": "希罗底的女儿", "lesson": "被当作工具的舞步", "witness": "她在希律的生日宴上跳舞，使王欢喜起誓应许；她受母亲希罗底指使，求来了施洗约翰的头。年轻的她沦为母亲仇恨的工具，一支舞断送了一位先知的性命。被人利用去成就恶，是何等可叹。", "summary": "为希律跳舞、求施洗约翰头颅的少女。", "prayer": "主啊，希罗底的女儿被母亲利用，害了约翰。求祢赐我分辨，不被人利用去行恶，不为取悦人而参与不义。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["被人（尤其至亲）利用去行恶", "不分辨地顺从，成了害人的工具"], "applications": ["不被人利用去做伤害他人的事", "在'听话'与'是非'之间学会分辨", "不因取悦人而参与恶事"], "scriptures": ["可6:22"]}, {"name": "居里扭", "lesson": "一道户口，定准了降生的时间地点", "witness": "居里扭作叙利亚巡抚时，行了一次报名上册。路加用这次普查为耶稣的降生定下历史坐标，也正是这道政令，使约瑟带着马利亚回到伯利恒——应验了弥赛亚生于伯利恒的预言。连一次行政普查，都在神的计划里。", "summary": "叙利亚巡抚，报名上册时在任。", "prayer": "主啊，居里扭的一次普查成全了祢降生的预言。求祢使我在时势与政令的背后看见祢的手，深信万事都在祢的计划中。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": [], "applications": ["相信神能藉行政、时势成就祂的计划", "在'大环境'的安排中看见神的手", "不小看看似平常的时势对救恩史的作用"], "scriptures": ["路2:2"]}, {"name": "凯撒奥古斯都", "lesson": "帝王的谕旨，成就神的预言", "witness": "凯撒奥古斯都是罗马皇帝，一道'报名上册'的谕旨，看似只是帝国的行政，却使约瑟与马利亚回到伯利恒——正应验了弥赛亚必生于伯利恒的预言。最高的人间权力，也不过是成就神计划的棋子。", "summary": "耶稣降生时下令报名上册的罗马皇帝。", "prayer": "主啊，奥古斯都的谕旨成就了祢降生的预言。求祢使我看见万事万权都在祢的掌管之下，在大势中仍安稳信靠祢。阿们。", "tags": ["君王", "混合型"], "follow": [], "caution": ["以为人间权力至高，不知有在上掌权者"], "applications": ["看见神能藉世上的权力与时势成就祂的旨意", "在'大势'面前仍相信神在掌权", "不高估也不惧怕人间的权柄"], "scriptures": ["路2:1"]}, {"name": "提庇留", "lesson": "王朝更替，救恩照常推进", "witness": "提庇留是耶稣传道时期的罗马皇帝，路加特地以他在位的年份为施洗约翰出来传道定下时间坐标。帝国的权杖几经易手，神救恩的时间表却分毫不差地推进——'日期满足'的时候，主就来了。", "summary": "施洗约翰与耶稣传道时期的罗马皇帝。", "prayer": "主啊，提庇留在位时祢的救恩照常推进。求祢使我不被时局变动牵动，定睛于祢分毫不差的计划与时候。阿们。", "tags": ["君王", "混合型"], "follow": [], "caution": ["把目光只放在帝王权势的更替上"], "applications": ["相信神的救恩时间表不受政权更替影响", "在变动的时局中定睛于神的计划", "记得'日期满足'时神必成就祂的事"], "scriptures": ["路3:1"]}, {"name": "西庇太", "lesson": "甘心放手，让儿女回应主的呼召", "witness": "西庇太是雅各、约翰的父亲，加利利的渔夫。当耶稣呼召他两个儿子，他们立刻撇下父亲和渔船跟从了主。西庇太没有拦阻——他甘心放手，让儿子去回应更高的呼召，自己继续守着本业。", "summary": "雅各和约翰的父亲，加利利的渔夫。", "prayer": "主啊，西庇太甘心让两个儿子撇下渔船跟从祢。求祢使我也不拦阻所爱的人回应祢的呼召，在自己的本分上忠心。阿们。", "tags": ["其他", "混合型"], "follow": ["甘心放手，支持儿女回应神的呼召", "在平凡的本业中忠心"], "caution": ["不因私情或家业拦阻儿女跟随主"], "applications": ["支持家人回应神的呼召，不因私情拦阻", "在自己的岗位本业上忠心", "为儿女的属灵前途祷告并放手"], "scriptures": ["太4:21"]}, {"name": "亚勒腓", "lesson": "平凡的父亲，养出使徒", "witness": "亚勒腓是使徒马太（利未）和小雅各的父亲。他自己没有事迹被记载，却是两位门徒身份的源头。一个不显眼的父亲，把儿子交给了主的呼召——平凡的家，也能成为使徒的摇篮。", "summary": "马太（利未）与小雅各的父亲。", "prayer": "主啊，亚勒腓养育了马太与小雅各。求祢使我在不显眼处忠心养育下一代，愿他们将来回应祢的呼召。阿们。", "tags": ["其他", "混合型"], "follow": ["默默作下一代蒙召者的根"], "caution": [], "applications": ["看重养育下一代回应主呼召的责任", "在不显眼处忠心，影响却可能深远", "为儿女将来跟随主祷告"], "scriptures": ["可2:14", "可3:18"]}, {"name": "小雅各（亚勒腓之子）", "lesson": "十二使徒中安静的一位", "witness": "小雅各是亚勒腓的儿子，十二使徒之一，为别于西庇太的雅各而称'小雅各'。福音书几乎没有记下他的言行，他却名列主亲自拣选的十二人中。被主拣选、忠心跟随，不一定要轰轰烈烈。", "summary": "十二使徒之一，又称小雅各。", "prayer": "主啊，小雅各安静地名列十二使徒中。求祢使我甘心作安静忠心的跟随者，不求出头，只求被祢拣选、忠心到底。阿们。", "tags": ["使徒", "正面榜样"], "follow": ["蒙主拣选，安静而忠心地跟随", "不求出头，甘居众人之后"], "caution": [], "applications": ["甘心作安静却忠心的跟随者", "不因不被注目而轻看自己的服事", "相信被主拣选、忠心到底，就是荣耀"], "scriptures": ["可3:18"]}, {"name": "睚鲁的女儿", "lesson": "在主眼中，她只是睡了", "witness": "她是会堂主管睚鲁十二岁的独生女，病重而死。家里一片哀哭，耶稣却说'女儿不是死了，是睡着了'，就拉着她的手说'闺女，起来'。她的灵魂便回来，立刻起来行走。在掌管生命的主面前，死亡不过是一场可被唤醒的睡。", "summary": "被耶稣从死里救活的女孩。", "prayer": "主耶稣，祢一句话就唤醒了睚鲁的女儿。求祢使我把生死交托给祢，在最深的哀痛中仍信靠祢——在祢里面，死不过是睡。阿们。", "tags": ["女性", "正面榜样"], "follow": [], "caution": [], "applications": ["把所爱之人的生死交托给掌管生命的主", "在'已经太迟'的哀哭中仍存信心", "相信在主里，死亡是可被唤醒的睡"], "scriptures": ["可5:41-42"]}, {"name": "血漏的妇人", "lesson": "只要摸着主，就得医治", "witness": "她患血漏十二年，花尽所有、求遍医生反而更重，在律法上还是'不洁'、不可触碰的。她挤进人群，心想'只摸他的衣裳，就必痊愈'，一摸就立刻血止病愈。耶稣回头叫她'女儿'，说'你的信救了你'。绝望中孤注一掷地摸向主的信心，主必看见、必回应。", "summary": "摸耶稣衣裳就得医治。", "prayer": "主耶稣，血漏的妇人一摸祢的衣裳就得医治。求祢使我在绝望中仍以信心挤向祢，不因不配而退缩，深信祢必看见、必回应。阿们。", "tags": ["女性", "正面榜样"], "follow": ["在绝望中仍以信心挤向主", "不因自卑、不洁而退缩，只管摸主"], "caution": [], "applications": ["在久治不愈的难处中，仍以信心来到主前", "不因自觉不配而退缩，主必接纳", "相信哪怕只是'摸着'主，信心就蒙看见"], "scriptures": ["可5:25-34"]}, {"name": "毕士大池的病人", "lesson": "病了三十八年，主主动寻见", "witness": "他在毕士大池边躺了三十八年，没有人帮他下池，等候已成了绝望的习惯。耶稣主动来问：你要痊愈吗？一句'起来，拿你的褥子走吧'，就成就了三十八年等不来的医治。主常主动寻见那久病、无人理会的人。", "summary": "病了三十八年、被耶稣医好的人。", "prayer": "主耶稣，祢主动寻见躺卧三十八年的病人。求祢也来寻见我久未得医治之处，叫我听祢的话就起来而行，不再困在失望里。阿们。", "tags": ["其他", "正面榜样"], "follow": ["回应主的话，立刻起来而行", "不让长久的失望变成不肯起来的借口"], "caution": ["不困在'等候'与抱怨里，以致错过医治"], "applications": ["当主说'起来'，就以行动回应", "不让长年的困境磨成不信的习惯", "相信主会主动寻见久被忽略的人"], "scriptures": ["约5"]}, {"name": "生来瞎眼的人", "lesson": "得了医治，就勇敢作见证", "witness": "他生来瞎眼，耶稣用唾沫和泥抹他的眼，叫他去西罗亚池洗，他回来就看见了。法利赛人反复盘问、威吓，他却越辩越清楚：'他是个先知''若不是从神来的，什么也不能做。'最后被赶出会堂，耶稣却来寻见他、领他敬拜。得医治者最有力的见证，就是诚实说出'我本来瞎眼，如今能看见'。", "summary": "耶稣医好的生来瞎眼者，勇敢为主作见证。", "prayer": "主耶稣，生来瞎眼的人得看见，就勇敢为祢作证。求祢使我诚实见证祢在我身上的作为，在威吓中不退缩，深信祢必亲自寻见我。阿们。", "tags": ["其他", "正面榜样"], "follow": ["诚实见证主在自己身上的作为", "面对威吓盘问，越发清楚地为主辩明", "被弃绝时，主必亲自寻见"], "caution": [], "applications": ["以'我从前如何、如今如何'作朴实的见证", "在压力下不退缩，坚持你所经历的真实", "相信为主受排斥时，主必亲自来寻你"], "scriptures": ["约9"]}, {"name": "叙利腓尼基妇人", "lesson": "谦卑而执着的信心，蒙主称许", "witness": "她是叙利腓尼基的外邦妇人（迦南妇人），为被鬼附的女儿求耶稣。面对'不好拿儿女的饼丢给狗吃'的话，她不灰心，谦卑回应：'狗也吃主人桌上掉下来的碎渣。'耶稣大大称许：'妇人，你的信心是大的！'就医好了她的女儿。", "summary": "为女儿恳求、以信心蒙称许的外邦妇人（迦南妇人）。", "prayer": "主啊，叙利腓尼基妇人以谦卑执着的大信心蒙了称许。求祢赐我这样的信心，为所爱的人迫切恳求，在被拒时仍谦卑抓住祢的怜悯。阿们。", "tags": ["女性", "正面榜样"], "follow": ["以谦卑而执着的信心向主恳求", "为儿女（所爱的人）迫切代求", "在被拒时不灰心，反更谦卑"], "caution": [], "applications": ["为所爱的人迫切、不放弃地向主祈求", "在似乎被拒时仍以谦卑的信心坚持", "学她：既谦卑认己，又抓住主的怜悯"], "scriptures": ["可7:24-30"]}, {"name": "迦百农的百夫长", "lesson": "罗马军官，信心却最大", "witness": "迦百农的百夫长是罗马军官，为病危的仆人求耶稣。他深知权柄之下'说有就有'的道理，便说：你只要说一句话，我的仆人就必好了，我不敢当你到我舍下。耶稣稀奇，说'这么大的信心，在以色列中我没有遇见过'。一个外邦军人，信心却超过选民。", "summary": "信心大、求耶稣医治仆人的罗马军官。", "prayer": "主耶稣，迦百农百夫长以谦卑的大信心信靠祢的话。求祢也赐我这样的信心：深信祢一句话就足够，并以谦卑来到祢面前。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以谦卑而坚定的信心信靠主的话", "看重并爱护自己所辖之人"], "caution": [], "applications": ["像他一样，单信主的'一句话'就足够", "不论身份背景，都可以有大信心", "以谦卑（我不敢当）配搭信心"], "scriptures": ["太8:5-13"]}, {"name": "百夫长的仆人", "lesson": "主人的信心，带来他的医治", "witness": "他是迦百农百夫长所'珍贵'的仆人，病得快死了。主人不敢劳动耶稣进门，只求主'说一句话'，耶稣就医好了他。他自己未发一言，却因主人的信心与爱被远远地医治。有时，别人的代求成了我们蒙恩的通道。", "summary": "被耶稣远程医治的仆人。", "prayer": "主耶稣，百夫长的仆人因主人的信心得了医治。求祢教我为所珍惜的人迫切代求，也使我感恩那些为我向祢祈求的人。阿们。", "tags": ["其他", "正面榜样"], "follow": [], "caution": [], "applications": ["为你所珍惜的人（下属、家人）向主代求", "相信主一句话就能成就医治", "珍惜那些为你向主代求的人"], "scriptures": ["太8:5-13"]}, {"name": "十个长大麻风的", "lesson": "十人得洁净，一人懂感恩", "witness": "十个长大麻风的远远站着求耶稣怜悯，主叫他们去给祭司察看，他们去的时候就洁净了。然而只有一个（还是被人轻看的撒玛利亚人）回来，大声归荣耀给神、俯伏感谢。耶稣问：洁净的不是十个吗？那九个在哪里？蒙恩容易，感恩却稀少。", "summary": "被耶稣洁净，只有一个撒玛利亚人回来感恩。", "prayer": "主啊，十个麻风病人得洁净，只一个回来感恩。求祢使我不做那九个，蒙恩就回转，常常归荣耀给祢、献上感谢。阿们。", "tags": ["其他", "混合型"], "follow": ["蒙恩之后回转，归荣耀给神、献上感谢"], "caution": ["得了恩典就走，忘了回来感恩", "把神的怜悯视为理所当然"], "applications": ["蒙恩后记得回到神面前感谢", "不做'得了就走'的那九个", "常数算并为神的怜悯献上感恩"], "scriptures": ["路17:11-19"]}, {"name": "格拉森被鬼附的人", "lesson": "被群鬼捆锁，被主释放", "witness": "他被一'群'鬼附着，昼夜在坟茔野地里喊叫、用石头砍自己，铁链也锁不住。耶稣来，赶出群鬼，他就坐着、穿上衣服、心里明白过来。主吩咐他回家传扬主为他所做的大事。最深的捆锁，主能彻底释放。", "summary": "被群鬼所附、得耶稣释放的人。", "prayer": "主耶稣，祢释放了被群鬼捆锁的人，使他恢复神智。求祢释放一切被捆锁的人，也使我把祢在我身上的作为传扬出去。阿们。", "tags": ["其他", "正面榜样"], "follow": ["得释放后，回去传扬主的恩典", "在自己的家乡为主作见证"], "caution": [], "applications": ["相信主能释放最深的捆锁与黑暗", "蒙释放后，在自己熟悉的人中作见证", "为被各样捆锁辖制的人代求"], "scriptures": ["可5:1-20"]}, {"name": "迦拿婚筵的新郎", "lesson": "筵席缺乏处，主默默补足", "witness": "他是迦拿婚筵的新郎。婚宴中途酒用尽了——这在当时是极尴尬的失礼。耶稣却把水变成了上好的酒，管筵席的还以为是新郎留的好酒。主在他不知不觉间，默默补足了他的缺乏、遮盖了他的难堪。主的恩典常这样悄然临到。", "summary": "水变酒神迹中的新郎。", "prayer": "主耶稣，祢在新郎不知不觉间补足了筵席的缺乏。求祢也在我缺乏、难堪之处默默补足，叫我对祢暗中的恩典心存感恩。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": [], "applications": ["相信主会在你缺乏、难堪处默默补足", "把生活中的'酒用尽了'带到主面前", "为主常在暗处的恩典心存感恩"], "scriptures": ["约2:1-11"]}, {"name": "管筵席的", "lesson": "尝到好酒，却不知从何而来", "witness": "迦拿婚筵上，管筵席的尝了那水变的酒，惊讶地对新郎说：人都先摆上好酒……你倒把好酒留到如今！他尝到了神迹的美好，却不知是怎么来的——只有舀水的用人知道。神的作为常先临到那些默默顺命去舀水的人。", "summary": "尝出水变之酒的管筵席者。", "prayer": "主啊，管筵席的尝了好酒却不知出处。求祢使我享受祢所赐之福时，认出并感谢那位赐福的主，而非只顾享用。阿们。", "tags": ["其他", "混合型"], "follow": ["惊喜领受神所赐的美好"], "caution": ["只享用结果，却不认识赐下的主"], "applications": ["享受神所赐之福时，认出那位赐福的主", "愿作那'舀水'的人，知道神迹的源头", "在生活的'好酒'中归荣耀给神"], "scriptures": ["约2:9"]}, {"name": "彼拉多的妻子", "lesson": "一个梦，一次未被听见的劝阻", "witness": "彼拉多的妻子因耶稣的事在梦中受了许多苦，差人去对丈夫说：这义人的事你一点不可管。她凭着良心与那异梦，试图拦阻一桩不义的定罪，可惜彼拉多终究没有听。有时神会藉各样方式发出警告，问题在于人肯不肯听。", "summary": "因梦警告彼拉多不可定耶稣的罪。", "prayer": "主啊，彼拉多的妻子凭良心为义人发声。求祢使我也敏于祢的警示，敢为受冤的人说话，不在不义前沉默。阿们。", "tags": ["女性", "混合型"], "follow": ["凭良心为义人发声、出面劝阻", "对神所发的警示存敬畏"], "caution": [], "applications": ["凭良心为受冤的人发声，哪怕不被听", "留意神藉各样方式发出的警示", "不在不义的事上保持沉默"], "scriptures": ["太27:19"]}, {"name": "巴拉巴", "lesson": "该死的得释放，无罪的代他死", "witness": "巴拉巴是个作乱杀人的囚犯，本该被钉十字架。彼拉多却照节期惯例释放了他，把无罪的耶稣交去钉死。巴拉巴是一幅生动的福音图画：那本该我受的刑罚，被无罪的主担去了，我却白白得了释放。", "summary": "被释放代替耶稣的囚犯。", "prayer": "主耶稣，巴拉巴本该死，祢却代他、代我受了刑。求祢叫我常记念这白白的释放，以感恩和悔改回应祢舍命的爱。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（背景）众人宁要凶犯，不要基督"], "applications": ["默想：我就是那个该死却得释放的巴拉巴", "因主代我受死而存感恩、悔改的心", "不像众人那样，为私意舍弃基督"], "scriptures": ["太27"]}, {"name": "亚历山大（古利奈人之子）", "lesson": "背十字架之人的儿子", "witness": "亚历山大是古利奈人西门的儿子，与兄弟鲁孚一同被马可福音特别提名。父亲西门曾被强迫背耶稣的十字架，这一家后来显然成了信徒群体所认识的人。一次'被迫'的相遇，竟把全家带进了信仰。", "summary": "古利奈人西门的儿子，与鲁孚同被提名。", "prayer": "主啊，古利奈西门背了十字架，他的儿子也被记念。求祢使我珍惜家族与祢相遇的记忆，让上一代的经历成为我的根。阿们。", "tags": ["其他", "混合型"], "follow": ["承接父辈与十字架的属灵联结"], "caution": [], "applications": ["珍惜家族与基督相遇的属灵记忆", "让上一代的信仰经历成为自己的根", "相信一次'偶然'的相遇可能改变全家"], "scriptures": ["可15:21"]}, {"name": "埃提阿伯太监", "lesson": "真诚寻求的人，神必为他预备", "witness": "埃提阿伯太监是位高权重的财政大臣，大老远上耶路撒冷敬拜，归途仍在车上读以赛亚书。神特地差腓利去为他讲解，他一明白就立刻受洗，欢欢喜喜地走路。真心寻求的人，神必为他预备遇见祂的机会。", "summary": "腓利向他传福音并施洗的埃提阿伯财政大臣。", "prayer": "主啊，祢为真心寻求的埃提阿伯太监差来腓利。求祢使我持续寻求祢，明白就立刻顺服，也使我成为别人路上的引路人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["真诚、持续地寻求神，不因不懂而放弃", "一明白真理就立刻回应、受洗"], "caution": ["不因地位忙碌而忽略对神的寻求"], "applications": ["持续读经寻求，即使暂时不懂", "明白真理后，立刻以行动回应", "相信神会为真心寻求的人预备引路人"], "scriptures": ["徒8:26-39"]}, {"name": "马利亚（马可的母亲）", "lesson": "敞开家门，成为祷告的港湾", "witness": "马利亚是马可的母亲，把自己的家敞开作耶路撒冷教会聚集祷告的地方。彼得出监的那夜，众人正在她家中切切祷告。她以一个'开放的家'，默默托住了初代教会的祷告与团契。", "summary": "耶路撒冷家庭教会的主人。", "prayer": "主啊，马利亚敞开家门作教会祷告的港湾。求祢使我也乐意敞开所有，接待圣徒，成为托住群体祷告与团契的人。阿们。", "tags": ["女性", "正面榜样"], "follow": ["敞开家门接待、供应教会的聚集", "以好客与祷告托住群体"], "caution": ["不因怕麻烦或风险而关上接待的门"], "applications": ["把你的家、空间向团契与祷告敞开", "以接待和款待服事弟兄姊妹", "作群体中那个稳定的祷告港湾"], "scriptures": ["徒12:12"]}, {"name": "罗大", "lesson": "欢喜得忘了开门", "witness": "罗大是马可母亲家的使女。彼得被天使救出监，来敲门，罗大听出是他的声音，欢喜得顾不上开门，反跑进去报信，众人还不信她。一个小使女，成了神奇妙拯救的第一个见证人——神常把惊喜先交给最不起眼的人。", "summary": "彼得出监时报信的使女。", "prayer": "主啊，小使女罗大第一个认出蒙拯救的彼得。求祢使我以单纯的心为祢的作为欢喜，虽不被信也坚持所经历的真实。阿们。", "tags": ["女性", "正面榜样"], "follow": ["对神的作为存单纯的欢喜与确信", "虽人不信，仍坚持所听见的真实"], "caution": [], "applications": ["以单纯的心为神的作为欢喜", "别人不信时，仍坚持你所经历的", "相信神乐意把惊喜先给最不起眼的人"], "scriptures": ["徒12:13-15"]}, {"name": "亚迦布", "lesson": "领受预言，也甘心受苦", "witness": "亚迦布是初代教会的先知，曾预言天下大饥荒，使教会提早预备赈济；又在该撒利亚用保罗的腰带捆自己的手脚，预言保罗将在耶路撒冷被捆。他忠实传讲神的提示，帮助教会未雨绸缪。", "summary": "预言饥荒和保罗被捆的先知。", "prayer": "主啊，亚迦布忠实传讲预言，帮助教会预备。求祢使我对所领受的提醒忠实传递，也帮助身边的人未雨绸缪，坦然面对将来。阿们。", "tags": ["先知", "正面榜样"], "follow": ["忠实传递神的提醒，帮助群体预备", "以行动（而非只言语）传达信息"], "caution": ["传讲将临的患难时，不夸大也不隐瞒"], "applications": ["对将临的难处提早预备、未雨绸缪", "在群体中作传递神提醒的人", "面对预知的患难，仍存交托的心前行"], "scriptures": ["徒11:28", "徒21:10"]}, {"name": "犹大（巴撒巴）", "lesson": "受差传达，坚固众人", "witness": "犹大（巴撒巴）是耶路撒冷教会中的领袖，与西拉一同被差往安提阿，传达耶路撒冷会议的决议。他们也是先知，'用许多话劝勉弟兄，坚固他们'。受差传达，不只送达文件，更以话语坚固人心。", "summary": "耶路撒冷教会差往安提阿的领袖。", "prayer": "主啊，犹大忠心传达决议、坚固众人。求祢使我忠实传递所托的信息，并以劝勉的话坚固身边的弟兄姊妹。阿们。", "tags": ["其他", "正面榜样"], "follow": ["忠心传达所受托的信息", "以劝勉的话坚固弟兄"], "caution": [], "applications": ["忠实传达受托的信息，不夹带私意", "传达之余，以话语鼓励、坚固人", "在教会的决议与联络中作可靠的桥梁"], "scriptures": ["徒15:22-32"]}, {"name": "西面（尼结）", "lesson": "多元同工，同心带领教会", "witness": "西面（称尼结，意为'黑色'，或为非洲背景）是安提阿教会的先知和教师之一，与古利奈人路求、希律的乳兄马念、巴拿巴、扫罗同列。这是一个跨地域、跨背景的多元团队，他们一同事奉、禁食祷告，差出了保罗与巴拿巴。", "summary": "安提阿教会的先知和教师。", "prayer": "主啊，西面与不同背景的同工在安提阿同心事奉，差出了宣教士。求祢使我在多元的团队中同心配搭，以祷告寻求祢的差遣。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在多元的团队中同心事奉", "以禁食祷告寻求差遣的方向"], "caution": [], "applications": ["在跨背景的团队中同心配搭", "看重多元同工对宣教的祝福", "以祷告与禁食寻求神的差遣"], "scriptures": ["徒13:1"]}, {"name": "马念", "lesson": "王宫长大，却选择跟从主", "witness": "马念是与分封王希律安提帕'一同长大'的，如今却是安提阿教会的先知和教师之一。当昔日的玩伴希律杀了施洗约翰、戏弄耶稣，马念却走上了截然不同的路——委身基督、事奉教会。同样的出身，可以有完全不同的选择。", "summary": "与希律安提帕一同长大的安提阿教会领袖。", "prayer": "主啊，马念与希律一同长大，却选择跟从祢、事奉教会。求祢使我不被出身与旧圈子辖制，定意委身于祢，走与世俗分别的路。阿们。", "tags": ["其他", "正面榜样"], "follow": ["不被出身、人脉决定属灵的方向", "委身基督，与世俗的旧圈子分别"], "caution": [], "applications": ["不让出身、旧圈子决定你的属灵选择", "即使周围的人远离神，你仍可选择跟从", "把过往的资源（人脉、背景）转向事奉主"], "scriptures": ["徒13:1"]}, {"name": "以吕马", "lesson": "敌挡真道，自陷黑暗", "witness": "以吕马（又名巴耶稣）是个行法术的假先知，极力敌挡保罗，要拦阻方伯听信真道。保罗被圣灵充满，定睛斥责他'弄诡诈、行奸恶'，使他暂时瞎眼。敌挡真道、拦阻人信主的，把自己推入了黑暗。", "summary": "又名巴耶稣，敌挡保罗被罚瞎眼的术士。", "prayer": "主啊，以吕马敌挡真道、拦阻人信主，自陷黑暗。求祢使我永不拦阻人归向祢，远离诡诈，作引人就近祢的人。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["以诡诈、法术敌挡真道", "拦阻别人寻求、相信神"], "applications": ["绝不拦阻别人寻求真理、归向神", "远离一切诡诈、行邪术的事", "省察自己是否在拦阻人亲近神"], "scriptures": ["徒13:8-11"]}, {"name": "腓立比的狱卒", "lesson": "一夜之间，从看守到信主", "witness": "他是腓立比的狱卒，半夜地大震动、监门全开时，以为囚犯都逃了，就要自尽。保罗大声拦住他。他战兢俯伏，问'我当怎样行才可以得救'，当夜全家信主受洗，又给保罗西拉洗伤、摆饭。神的拯救，能在一夜之间翻转一个人的全家。", "summary": "因地震信主、全家受洗的狱卒。", "prayer": "主啊，腓立比狱卒一夜之间全家归向祢。求祢使我真心寻求救恩、立刻回应，并带领我的家一同信靠、服事祢。阿们。", "tags": ["其他", "正面榜样"], "follow": ["真心寻求得救之道，立刻回应", "信主后以爱心款待、服事神的仆人", "带全家一同归向主"], "caution": [], "applications": ["认真问'我当怎样行才可以得救'", "信了就立刻受洗、行动回应", "盼望并带领全家一同归主"], "scriptures": ["徒16:25-34"]}, {"name": "被鬼附的使女", "lesson": "得释放，胜过被利用", "witness": "她是腓立比一个被巫鬼附身的使女，主人靠她行卜大得财利。她一连多日跟着保罗喊叫，保罗就奉耶稣的名赶出那鬼。她得了释放，主人却因发财的指望断了而恼怒控告保罗。在主眼中，一个人的得释放，远比被人利用赚钱更宝贵。", "summary": "保罗赶出她身上的巫鬼。", "prayer": "主啊，祢释放了那被利用牟利的使女。求祢使我看重人的得释放过于其用处，为被辖制的人争取自由，奉祢的名抵挡黑暗。阿们。", "tags": ["女性", "混合型"], "follow": [], "caution": ["（背景）被人当作牟利的工具"], "applications": ["看重人的得释放过于其'利用价值'", "为被辖制、被利用的人代求、争取自由", "奉主的名抵挡辖制人的黑暗权势"], "scriptures": ["徒16:16-19"]}, {"name": "底米丢", "lesson": "利益受损，煽动一城", "witness": "底米丢是以弗所制造亚底米银龛的银匠。因保罗传道使人离弃偶像，他的生意受损，便煽动同行喊'大哉以弗所人的亚底米'，闹得满城混乱。当福音触动了人的钱袋，反对往往来得最猛烈——他打着宗教旗号，护的其实是利益。", "summary": "以弗所的银匠，煽动反对保罗的暴乱。", "prayer": "主啊，底米丢为私利假借宗教煽动暴乱。求祢使我诚实面对自己的动机，不以属灵为幌子护私利，也不被群体的狂热裹挟。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["以宗教为幌子，实为护卫私利", "煽动群众情绪，制造混乱"], "applications": ["省察：我反对某事，是为真理还是为私利？", "不打着属灵旗号护卫自己的利益", "不煽动、不被煽动卷入群体的狂热"], "scriptures": ["徒19:24-29"]}, {"name": "亚里达古", "lesson": "患难同当的忠实同伴", "witness": "亚里达古是马其顿人，保罗忠心的同伴。他在以弗所暴乱中与保罗一同被抓，又一路陪保罗坐船去罗马，甚至成了保罗的'同坐监'。从风波到牢狱，他始终相随——真同伴，是患难中不离开的那一个。", "summary": "马其顿人，保罗忠心的同伴与同囚。", "prayer": "主啊，亚里达古患难中始终与保罗相随。求祢使我作患难不离的忠实同伴，甘心与人同担风险，陪人走过低谷。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在患难中与人不离不弃地相随", "甘心与所跟随的人同当风险"], "caution": [], "applications": ["在朋友、同工的患难中不离开", "甘心与人同担风险与代价", "作那个'同坐监'式的忠实同伴"], "scriptures": ["徒19:29", "徒27:2"]}, {"name": "所巴特", "lesson": "陪保罗同行的庇哩亚人", "witness": "所巴特是庇哩亚人，保罗末次旅程的同伴之一。庇哩亚人素以'天天考查圣经、查验所听是否如此'著称，所巴特很可能正是这群人结出的果子，如今成了陪伴使徒、参与宣教的同工。", "summary": "庇哩亚人，保罗的同伴。", "prayer": "主啊，所巴特从查考圣经的庇哩亚成为保罗的同伴。求祢使我以扎实的真理为根，甘心陪伴、参与祢福音的工作。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以查考圣经的根基委身服事", "甘作宣教旅程中的同伴"], "caution": [], "applications": ["以扎实的查经为服事打根基", "甘心陪伴、支持福音的工人", "在团队中作可靠的同行者"], "scriptures": ["徒20:4"]}, {"name": "西公都", "lesson": "陪保罗走完旅程的帖城人", "witness": "西公都是帖撒罗尼迦人，在保罗末次旅程中作同伴之一，与亚里达古等一同同行。他没有惊人事迹，却是那批一路陪伴、护送使徒的忠实同工之一。同行到底，本身就是一种忠心。", "summary": "帖撒罗尼迦人，保罗的同伴。", "prayer": "主啊，西公都一路陪伴保罗的旅程。求祢使我作忠实的同伴，陪伴、护送祢的工人，以同行到底的忠心服事祢。阿们。", "tags": ["其他", "正面榜样"], "follow": ["甘作宣教旅程中忠实的同伴", "陪伴、护送神的工人"], "caution": [], "applications": ["甘心陪伴、护送服事主的人", "在团队中作可靠的同行者", "看重'一路同行'的忠心"], "scriptures": ["徒20:4"]}, {"name": "特罗非摩", "lesson": "同工也会病，服事有其有限", "witness": "特罗非摩是以弗所人，保罗的同伴，曾因他被误以为被带进圣殿而引发耶路撒冷的骚乱。后来保罗说'我留特罗非摩在米利都，他病了'。连大有能力的保罗也没有医好同工的病——服事有神所定的界限，治病的主权在神。", "summary": "以弗所人，保罗的同伴。", "prayer": "主啊，连保罗也把病了的特罗非摩留在米利都。求祢使我接受服事的有限，把医治的主权交给祢，在软弱中仍彼此扶持、忠心同行。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在健康与软弱中都忠心同行"], "caution": ["不把'医治'当作衡量信心或恩典的尺子"], "applications": ["接受服事与身体都有其有限，主权在神", "在同工生病软弱时彼此扶持", "不因疾病未得医治就怀疑神的爱"], "scriptures": ["徒21:29", "提后4:20"]}, {"name": "犹推古", "lesson": "睡着坠楼，主仍施恩", "witness": "犹推古是个少年人，保罗在特罗亚讲道直到半夜，他坐在窗台上沉沉睡去，从三层楼坠下，被扶起来时已经死了。保罗下去伏在他身上，他便活了过来，众人大得安慰。软弱、失态如他，主的恩典仍然临到。", "summary": "听道睡着坠楼、被保罗救活的少年。", "prayer": "主啊，犹推古睡着坠楼，祢仍施恩使他活过来。求祢帮助我听道警醒，也叫我在软弱时仍信靠祢的恩典与扶持。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["听道时当尽力警醒，不放纵困倦"], "applications": ["听道、亲近神时尽力保持警醒", "即使软弱失态，也仰望主的恩典", "在聚会中彼此担待软弱的人"], "scriptures": ["徒20:9-12"]}, {"name": "腓力的四个女儿", "lesson": "同一个家，四个说预言的女儿", "witness": "腓力的四个女儿都是处女，都说预言。传福音的腓力，养育出四个被圣灵使用、传讲神话语的女儿。一个敬虔、向神敞开的家，能成为属灵恩赐的沃土——四个孩子一同被神使用，是何等的祝福。", "summary": "是处女、说预言的四姊妹。", "prayer": "主啊，腓力的四个女儿都说预言。求祢使我的家成为属灵恩赐的沃土，叫家中各人都向祢敞开、被祢使用。阿们。", "tags": ["女性", "正面榜样"], "follow": ["在敬虔的家中向神的恩赐敞开", "甘心被圣灵使用，传讲神的话"], "caution": [], "applications": ["营造一个让儿女属灵恩赐成长的家", "鼓励家中每个人被神使用", "看重并支持姊妹们的属灵恩赐"], "scriptures": ["徒21:9"]}, {"name": "革老丢吕西亚", "lesson": "依法护卫，救人于乱", "witness": "革老丢吕西亚是耶路撒冷的千夫长。当众人要打死保罗，他出面救下；得知有四十多人起誓要杀保罗，他连夜派重兵护送保罗安全转往该撒利亚。他依着罗马的法度，几次三番护住了保罗的性命。秉公执法，也能成为保护无辜的盾牌。", "summary": "保护保罗的千夫长。", "prayer": "主啊，革老丢吕西亚依法几次救护了保罗。求祢使我在权责中秉公护卫无辜，在危机中果断行动，作保护人的盾牌。阿们。", "tags": ["其他", "混合型"], "follow": ["依法秉公，护卫无辜的性命", "在危机中果断行动救人"], "caution": [], "applications": ["在你的权责范围内保护无辜的人", "秉公执法，不徇情也不枉法", "在危机中果断行动，而非旁观"], "scriptures": ["徒21-23"]}, {"name": "腓力斯", "lesson": "听了道，却等'方便的时候'", "witness": "腓力斯是罗马巡抚。保罗讲到公义、节制、将来的审判，他甚觉恐惧，说'你暂且去吧，等我得便再叫你'；他又指望保罗送他银钱，就把保罗关了两年。他被真理触动，却一再拖延，把'方便的时候'等成了永远的错过。", "summary": "拖延审判保罗的罗马巡抚。", "prayer": "主啊，腓力斯被真理触动却拖延、贪利。求祢使我不把回应祢的时机一再拖延，趁感动还在的时候就回转、顺服。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["被真理触动却一再拖延回应", "贪图利益，把决定无限期搁置"], "applications": ["不把回应真理拖到'得便的时候'", "不让利益与拖延偷走悔改的时机", "被神的话触动时，就当下回应"], "scriptures": ["徒23-24"]}, {"name": "土西拉", "lesson": "听了道，却仍停在原地", "witness": "土西拉是腓力斯巡抚的犹太妻子。保罗在他们面前讲'公义、节制、将来的审判'，腓力斯甚觉恐惧。她身为犹太人、近在真理之侧，却随丈夫一同把保罗搁置。离真理最近的人，也可能始终不作回应。", "summary": "腓力斯的犹太妻子。", "prayer": "主啊，土西拉近在真理旁却未回应。求祢使我听了祢的道就及时回应，不因身边人的冷淡而错过，不把决定一再搁置。阿们。", "tags": ["女性", "混合型"], "follow": [], "caution": ["近在真理之侧，却始终不作回应", "随身边的人一同搁置该有的决定"], "applications": ["听了真理，就当及时回应，不要搁置", "不因身边人的冷淡而错过真理", "近水楼台，更要把握亲近神的机会"], "scriptures": ["徒24:24"]}, {"name": "非斯都", "lesson": "求公道，却为讨好人妥协", "witness": "非斯都是接替腓力斯的巡抚。他查不出保罗有该死的罪，本可释放他，却为'讨犹太人的喜欢'问保罗是否愿上耶路撒冷受审，逼得保罗只好上诉于该撒。他也曾大声说保罗'癫狂'。明知无罪却为讨好人而不肯秉公，是掌权者常有的妥协。", "summary": "接替腓力斯审问保罗的巡抚。", "prayer": "主啊，非斯都明知保罗无罪却为讨好人妥协。求祢使我秉公行事，不为讨好人而妥协公义，也不轻看我所不理解的真理。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["明知无罪却为讨好人而不秉公", "以'癫狂'轻看自己不能理解的信仰"], "applications": ["秉公行事，不为讨好任何一方而妥协", "不轻看、嘲讽自己不理解的信仰", "在压力下持守公正的判断"], "scriptures": ["徒25-26"]}, {"name": "希律亚基帕一世", "lesson": "逼迫教会、窃取荣耀的下场", "witness": "希律亚基帕一世为讨好犹太人，杀了使徒雅各，又下手捉拿彼得。后来他在众人'这是神的声音'的欢呼中欣然受之，不归荣耀给神，立刻被虫所咬、气绝而死。逼迫神的教会、窃取神的荣耀，审判随之而来。", "summary": "杀雅各、囚彼得，后被虫咬而死。", "prayer": "主啊，亚基帕一世逼迫教会、窃取荣耀，立遭审判。求祢使我不为讨好人敌对祢的工，凡事把荣耀单单归给祢。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["为讨好人而逼迫、杀害神的仆人", "贪图人的称颂，把荣耀据为己有"], "applications": ["不为讨好任何人而敌对神的工作", "把一切称赞与荣耀归给神", "警惕'被人捧高'时的属灵危险"], "scriptures": ["徒12"]}, {"name": "希律亚基帕二世", "lesson": "差一点，不等于真信", "witness": "希律亚基帕二世听保罗申辩时说：'你想稍微一劝，便叫我作基督徒啊！'他被真理触动，却停在'差一点'。他承认保罗无罪，却没有为自己的灵魂做出决定。离神最近的一步，有时也是最难迈的一步。", "summary": "听保罗申辩的王。", "prayer": "主啊，亚基帕二世差一点就信，却终究止步。求祢不让我停在'差一点'的边缘，叫我完全地回应祢、委身于祢。阿们。", "tags": ["君王", "混合型"], "follow": [], "caution": ["被真理触动，却始终停在'差一点'", "以理智欣赏福音，却不肯委身"], "applications": ["不要停在'差一点信'的边缘，做出决定", "被真理触动时，就完全地回应", "为那些'离神不远'却未决志的人祷告"], "scriptures": ["徒25-26"]}, {"name": "百尼基", "lesson": "陪王听道，却只是过客", "witness": "百尼基是希律亚基帕二世的姊妹，与弟弟一同'大张威势'地来听保罗申辩。她见证了那场有力的申诉，听见了福音，却如威势的排场一样，来了又去，没有留下回应。听过、见过，不等于信过。", "summary": "亚基帕二世的姊妹。", "prayer": "主啊，百尼基听过保罗的申辩却只是过客。求祢使我不以旁观的心态对待祢的真理，听见就真实回应，不擦肩而过。阿们。", "tags": ["女性", "混合型"], "follow": [], "caution": ["以看热闹、讲排场的心态对待福音", "听过却不回应，擦肩而过"], "applications": ["不以旁观、看热闹的心态对待真理", "听了福音就当认真回应，而非过客", "省察：我是真信，还是只是听过？"], "scriptures": ["徒25:13"]}, {"name": "犹流", "lesson": "善待囚徒的百夫长", "witness": "犹流是御营里的百夫长，奉命押送囚犯保罗去罗马。一路上他宽待保罗，准他去朋友家受照应；船难时又因要保全保罗，拦阻了兵丁杀囚犯的打算。一个尽责的军官，以人道与善意待他所押送的囚徒。", "summary": "押送保罗去罗马、善待他的百夫长。", "prayer": "主啊，犹流以善意宽待并保全了保罗。求祢使我在职责中以人道待人，在该护卫无辜时挺身而出，尽责又存仁慈。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在职责中以人道、善意待人", "该护卫时挺身护卫无辜"], "caution": [], "applications": ["在职务中以善意、人道对待所管的人", "在该护卫弱者时挺身而出", "让尽责与仁慈并行"], "scriptures": ["徒27"]}, {"name": "部百流", "lesson": "患难中接待陌生人", "witness": "部百流是米利大岛的首领。保罗船难漂到岛上，他热情接待一行人三天；保罗又为他患热病、痢疾的父亲祷告医治，全岛的病人都来得了医治。一次海难中的接待，成了福音临到全岛的契机。好客向陌生人敞开的门，神能大大使用。", "summary": "米利大岛的首领，接待保罗。", "prayer": "主啊，部百流接待了船难的保罗，福音就临到全岛。求祢使我向落难的陌生人敞开门，深信一次接待能成为祢恩典临到的通道。阿们。", "tags": ["其他", "正面榜样"], "follow": ["热情接待落难的陌生人", "以好客成为福音临到的契机"], "caution": [], "applications": ["向落难、陌生的人敞开接待的门", "相信一次善意的接待，神能大大使用", "在患难相遇中传递神的爱"], "scriptures": ["徒28:7-8"]}, {"name": "马利亚（罗马教会）", "lesson": "为弟兄姊妹多多劳苦", "witness": "她是保罗在罗马书问安的马利亚，被称为'为你们多受劳苦的'。她不是哪位著名的马利亚，只是罗马教会中一位为众肢体辛勤付出的姊妹。'为你们多受劳苦'——这是使徒对一位默默服事者最实在的褒奖。", "summary": "在罗马为信徒多多劳苦的姊妹。", "prayer": "主啊，这位马利亚为众肢体多多劳苦。求祢使我也甘心为弟兄姊妹辛勤付出，在群体中默默服事，不求人的称许。阿们。", "tags": ["女性", "正面榜样"], "follow": ["为弟兄姊妹甘心多多劳苦", "在群体中默默服事众人"], "caution": [], "applications": ["甘心为身边的肢体辛勤付出", "不求人知，只为众人的益处劳苦", "看重'为弟兄姊妹劳苦'的服事"], "scriptures": ["罗16:6"]}, {"name": "尼利亚的姊妹", "lesson": "连'姊妹'也被一同记念", "witness": "她是尼利亚的姊妹，保罗问安时与弟弟一同被提及，连名字都没有单独留下，只称'尼利亚的姊妹'。然而圣灵仍把她记在圣经里。在神眼中，最不起眼、最'附带'被提的人，也一样被看见、被记念。", "summary": "保罗所问安的圣徒。", "prayer": "主啊，连'尼利亚的姊妹'祢都记念。求祢使我深信再不起眼的我祢都看见，也使我去看见、珍惜那些容易被忽略的人。阿们。", "tags": ["女性", "正面榜样"], "follow": ["在最不起眼处仍被神看见"], "caution": [], "applications": ["相信再不起眼的你，神都看见、记念", "不轻看自己'附带'的、隐藏的服事", "去看见并珍惜那些容易被忽略的人"], "scriptures": ["罗16:15"]}, {"name": "德丢", "lesson": "代笔的手，也在事奉", "witness": "德丢是替保罗代笔写罗马书的人，他在书信末了插了一句：我这代书的德丢，在主里问你们安。这封改变历史的书信，有他执笔的辛劳。幕后的、技术性的服事（代笔、文书），同样是宝贵的事奉。", "summary": "代笔写罗马书的人。", "prayer": "主啊，德丢以代笔之手参与了罗马书的写成。求祢使我以自己的专长幕后服事祢，在不显眼的岗位上忠心事奉。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以幕后、技术性的服事参与神的工", "在不显眼的岗位上忠心"], "caution": [], "applications": ["以你的专长（文书、技术等）服事神", "看重幕后、辅助性的事奉价值", "在不署名的工作中也存事奉的心"], "scriptures": ["罗16:22"]}, {"name": "该犹（马其顿人）", "lesson": "风波中被牵连的同伴", "witness": "该犹是马其顿人，保罗的同行者，在以弗所的暴乱中与亚里达古一同被群众抓住、拖进戏园。他因与保罗同行而被牵连进危险。跟随、同行神的工人，有时要一同承受随之而来的风波。", "summary": "保罗的马其顿同伴，在以弗所暴乱中被抓。", "prayer": "主啊，该犹因与保罗同行被卷进暴乱。求祢使我甘心与祢的工人同行、同担风波，在危险中彼此守望，不轻易退出。阿们。", "tags": ["其他", "混合型"], "follow": ["甘与神的工人同行，也同担风波"], "caution": [], "applications": ["跟随、同行时，也预备好同担风险", "在风波中与同伴彼此守望", "不因牵连的代价就退出同行"], "scriptures": ["徒19:29"]}, {"name": "该犹（约翰三书）", "lesson": "按真理行，接待远人", "witness": "该犹是约翰三书的收信人，约翰'诚心所爱的'。他'按真理而行'，又忠心接待那些为主名出外、素不相识的传道人，与那不接待人的丢特腓恰成对比。爱心与真理在他身上并行——这正是约翰为他大大欢喜的缘由。", "summary": "约翰所爱、忠心接待弟兄的人。", "prayer": "主啊，该犹按真理而行、忠心接待远人。求祢使我爱心与真理并行，乐意接待为祢名奔走的工人，作约翰所喜悦的那种人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["按真理而行，言行一致", "忠心接待为主名出外的工人"], "caution": [], "applications": ["让你的爱心与真理一同彰显", "接待、供应那些为福音奔走的人", "不学丢特腓的排外，要学该犹的好客"], "scriptures": ["约三1"]}, {"name": "括土", "lesson": "一句问安里的弟兄", "witness": "括土是保罗书信末了问安中提到的'兄弟'。关于他，圣经只留下这一个身份与名字。然而'弟兄'二字已足够珍贵——在基督里，他与使徒、与众圣徒同属一家。", "summary": "保罗问安中提到的弟兄。", "prayer": "主啊，括土以'弟兄'之名被记念。求祢使我珍惜在祢里同作弟兄姊妹的身份，以真实的弟兄之爱待主内的人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以'弟兄'的身份与众圣徒同属一家"], "caution": [], "applications": ["珍惜'在基督里同作弟兄'的身份", "以弟兄之情待主内的人", "相信单单'是主内弟兄'已是恩典"], "scriptures": ["罗16:23"]}, {"name": "亚利多布家的人", "lesson": "一家归主，一同被记念", "witness": "亚利多布家的人是保罗在罗马书问安的一家。使徒不是只问安一个人，而是连'一家'一同记念。福音临到的，常是一个家、一个群体；在主里，全家同被挂念、同蒙恩典。", "summary": "保罗问安的一家。", "prayer": "主啊，亚利多布一家一同被记念。求祢使福音临到我的全家，叫我们一同归入祢里，在主里同蒙恩典、同被记念。阿们。", "tags": ["其他", "混合型"], "follow": ["盼望、带领全家一同归入主里", "在家庭层面活出、承载信仰"], "caution": [], "applications": ["为自己的全家归主祷告、努力", "让信仰成为全家共同的实际", "珍惜'一家在主里被记念'的恩典"], "scriptures": ["罗16:10"]}, {"name": "拿其数家的人", "lesson": "一家在主里，被使徒挂念", "witness": "拿其数家的人是保罗在罗马书问安的一家，特别注明是'在主里的人'。在一个大户人家（可能拿其数本人未必信主）之中，有一群属主的人。即使身处不信的环境，他们仍在主里聚集、被使徒记念——在哪里都能有属神的群体。", "summary": "保罗问安、在主里的一家。", "prayer": "主啊，拿其数家中那在主里的人也被记念。求祢使我即使身处不信的环境，仍持守信仰、与肢体聚集，作属祢的群体。阿们。", "tags": ["其他", "混合型"], "follow": ["即使身处不信的环境，仍在主里聚集", "在大环境中作属神的小群体"], "caution": [], "applications": ["在不信的家庭或职场中，仍持守信仰", "与处境相近的肢体彼此扶持、聚集", "相信在哪里都能有属主的群体"], "scriptures": ["罗16:11"]}, {"name": "鲁孚的母亲", "lesson": "待人如己出的母亲心肠", "witness": "她是鲁孚的母亲，保罗说'她就是我的母亲'。她显然曾以母亲般的关怀照顾过保罗——煮饭、缝补、嘘寒问暖。这些不起眼的母性关怀，温暖了一位四处奔波的使徒，被他一生感念。母亲般的爱，是最朴实也最被记念的服事。", "summary": "待保罗如同母亲的姊妹。", "prayer": "主啊，鲁孚的母亲以母爱照顾了保罗。求祢使我也以这样朴实、温暖的关怀服事人，在生活的细处供应、体贴神的工人。阿们。", "tags": ["女性", "正面榜样"], "follow": ["以母亲般的关怀照顾神的工人", "在生活的细处温暖、供应人"], "caution": [], "applications": ["以母亲般的细心关怀身边的人", "在饮食起居等小事上服事神的工人", "看朴实的关怀为宝贵的服事"], "scriptures": ["罗16:13"]}, {"name": "革来氏家里的人", "lesson": "为了合一，如实报告纷争", "witness": "革来氏家里的人把哥林多教会结党纷争的实情告诉了保罗，促使他写信劝勉、维护合一。他们不是搬弄是非，而是出于对教会的关切，如实反映问题，好让纷争得着医治。为合一而诚实反映问题，与造谣生事截然不同。", "summary": "向保罗报告哥林多纷争的人。", "prayer": "主啊，革来氏家的人为合一如实报告了纷争。求祢使我说话出于爱与建造，为群体的合一诚实反映问题，而非搬弄是非。阿们。", "tags": ["其他", "混合型"], "follow": ["出于对群体的关切，如实反映问题", "为合一而非为搬弄是非地说话"], "caution": ["反映问题要出于爱与建造，不为搬弄是非"], "applications": ["为群体的益处，诚实反映该被处理的问题", "区分'为建造的反映'与'搬弄是非'", "以促成合一为说话的动机"], "scriptures": ["林前1:11"]}, {"name": "所提尼", "lesson": "从对头到同工，恩典翻转人生", "witness": "所提尼原是哥林多管会堂的，曾在审判台前被打；后来却成了基督徒，与保罗一同具名写信给哥林多教会。神的恩典能把昔日的对头变为今日的同工——没有谁是恩典够不着的。", "summary": "与保罗同具名写信的弟兄。", "prayer": "主啊，祢把会堂主管所提尼变成了保罗的同工。求祢使我相信祢恩典的翻转大能，不轻看任何人，也甘心被祢更新使用。阿们。", "tags": ["其他", "正面榜样"], "follow": ["经历恩典后，转身成为同工", "放下旧身份，委身于福音"], "caution": ["不因人过去的身份而断定他不能改变"], "applications": ["相信神能翻转任何人，包括曾经的对头", "为自己或别人的'转变'存盼望", "经历恩典后，投身于服事"], "scriptures": ["林前1:1", "徒18:17"]}, {"name": "司提反一家", "lesson": "初熟的果子，专以服事为念", "witness": "司提反一家是亚该亚'初结的果子'，保罗为他们施了洗。他们'专以服事圣徒为念'，保罗嘱咐众人要顺服这样的人。一家人同心，把服事众圣徒当作自己专一的心志——这是何等美好的全家事奉。", "summary": "亚该亚初结的果子，专以服事圣徒为念。", "prayer": "主啊，司提反一家专以服事圣徒为念。求祢使我和我家也同心服事祢的群体，以服事人为专一的心志，荣耀祢的名。阿们。", "tags": ["其他", "正面榜样"], "follow": ["全家同心，专以服事圣徒为念", "作群体里值得顺服、效法的服事者"], "caution": [], "applications": ["让全家一同投入服事神的群体", "以服事人为自己专一的心志", "尊重并跟随那些专心服事的人"], "scriptures": ["林前16:15-17"]}, {"name": "福徒拿都", "lesson": "远来补足，叫人快活", "witness": "福徒拿都与司提反一家、亚该古一同从哥林多来见保罗，'补足了哥林多人的不足'，使保罗的心畅快。他们的到来本身就是安慰，他们的服事补上了缺口。保罗嘱咐众人要敬重这样的人。", "summary": "从哥林多来见保罗的同工。", "prayer": "主啊，福徒拿都远来补足、叫保罗畅快。求祢使我主动去补别人的缺乏，以探访与服事带给人安慰。阿们。", "tags": ["其他", "正面榜样"], "follow": ["主动前去补足别人的缺乏", "以到访与服事带给人安慰"], "caution": [], "applications": ["主动探访、补足肢体的需要", "让你的出现成为别人的安慰", "敬重那些默默补缺、服事人的人"], "scriptures": ["林前16:17"]}, {"name": "亚该古", "lesson": "远道而来，使人心里快活", "witness": "亚该古与司提反一家、福徒拿都一同从哥林多来见保罗，'补足了哥林多人的不足'，使保罗和众人心里快活。他们的到来与服事，像一阵及时的安慰。有些人的出现，本身就是给人的鼓励。", "summary": "与福徒拿都同来的同工。", "prayer": "主啊，亚该古的到来使保罗心里快活。求祢使我成为补足别人不足、带来安慰的人，我的探访能给人鼓励。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以到访与服事补足别人的不足", "成为使人心里快活的安慰者"], "caution": [], "applications": ["主动去探访、补足别人的需要", "让自己的出现成为别人的鼓励", "在肢体疲乏时送上及时的服事"], "scriptures": ["林前16:17"]}, {"name": "革勒免", "lesson": "名字写在生命册上的同工", "witness": "革勒免是腓立比教会与保罗'一同劳苦'的同工之一。保罗说他和别的同工的'名字都在生命册上'。地上的事迹或许无多传扬，他的名字却记在天上那本更重要的册子里——这才是真正的荣耀。", "summary": "腓立比与保罗同劳的同工。", "prayer": "主啊，革勒免与保罗同劳，名字记在生命册上。求祢使我甘心为福音劳苦，以名字被祢记在天上为最大的荣耀与安慰。阿们。", "tags": ["其他", "正面榜样"], "follow": ["与人一同为福音劳苦", "看重名字记在天上，过于地上的传扬"], "caution": [], "applications": ["甘心与人一同为福音劳苦", "以'名字在生命册上'为最大的安慰", "不求地上的名声，只求被神记念"], "scriptures": ["腓4:3"]}, {"name": "宁法", "lesson": "把家献作教会的聚会所", "witness": "宁法是老底嘉一带的姊妹，'在她家里'有一处教会。她敞开自己的家，让信徒得以聚集敬拜、团契。在还没有教堂的时代，正是这样一个个敞开的家，托住了初代教会的聚集。", "summary": "在家里设立教会的姊妹。", "prayer": "主啊，宁法把家献作教会聚集之所。求祢使我也乐意敞开所有，供肢体聚集团契，以居所服事祢的群体。阿们。", "tags": ["女性", "正面榜样"], "follow": ["敞开自己的家，供信徒聚集团契", "以居所服事神的群体"], "caution": [], "applications": ["把你的家、空间向团契聚会敞开", "以接待和地方供应支持教会", "看重'家庭聚会'这一服事的价值"], "scriptures": ["西4:15"]}, {"name": "亚腓亚", "lesson": "家庭教会里被记念的姊妹", "witness": "亚腓亚是腓利门书开头被问安的姊妹，很可能是腓利门的妻子，与那在他们家中的教会相关。她与家人一同接待教会、参与服事。在家庭与教会交织的服事里，她的名字被郑重提及。", "summary": "腓利门书所问安的姊妹。", "prayer": "主啊，亚腓亚与家人一同服事教会。求祢使我的家庭也成为承载团契、接待肢体的所在，与家人同心服事祢。阿们。", "tags": ["女性", "正面榜样"], "follow": ["与家人一同参与、接待教会的服事", "在家庭层面承载教会的团契"], "caution": [], "applications": ["让你的家庭参与、支持教会的团契", "与家人同心服事主", "看重'家中的教会'这一服事形态"], "scriptures": ["门2"]}, {"name": "耶数（犹士都）", "lesson": "少数中仍忠心的犹太同工", "witness": "耶数（又名犹士都）是保罗的犹太同工之一。保罗特别提到，'奉割礼的人中，只有这几个人是为神国与我一同做工的，也曾叫我心里得安慰'。在多数同胞远离时，他仍站在保罗一边——成为少数中忠心的安慰。", "summary": "保罗的犹太同工。", "prayer": "主啊，犹士都在少数中仍与保罗同工、叫他得安慰。求祢使我在多数人远离时仍忠心站立，成为同伴心里的安慰。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在多数人远离时，仍忠心站立", "成为同工心里的安慰"], "caution": [], "applications": ["在多数人退去时，甘作忠心的少数", "成为疲乏同工的安慰者", "不随大流，坚定站在神国一边"], "scriptures": ["西4:11"]}, {"name": "革勒士", "lesson": "受差前往，各奔工场", "witness": "革勒士是保罗的同工，保罗在书信末了提到'革勒士往加拉太去了'。同工们各按需要被差往不同的地方。他的离开不是离弃，而是被分派去别处做工。福音的扩展，正需要这样甘心奔赴各方工场的人。", "summary": "去了加拉太的同工。", "prayer": "主啊，革勒士被差往加拉太做工。求祢使我甘心被祢差到所需要的地方，各按其位，一同扩展祢福音的疆界。阿们。", "tags": ["其他", "混合型"], "follow": ["甘心被差往所需要的工场", "各按其位，扩展福音的疆界"], "caution": [], "applications": ["甘心被神差到需要你的地方", "不留恋一处，愿往各方做工", "看同工的分散为福音疆界的扩展"], "scriptures": ["提后4:10"]}, {"name": "加布", "lesson": "为同工存留所需的人", "witness": "加布是特罗亚的一位弟兄，保罗把外衣、书卷和皮卷留在他家。一句'你来的时候把我留在加布那里的外衣带来'，让我们看见：他是个可托付、为同工存留所需之物的人。可靠的接待与保管，也是服事。", "summary": "保罗把外衣存放在他家的人。", "prayer": "主啊，保罗把所需之物存在加布那里。求祢使我作可托付、办事可靠的人，以接待和后勤忠心参与祢的工作。阿们。", "tags": ["其他", "混合型"], "follow": ["可托付，为同工妥善存留所需", "以接待与保管参与服事"], "caution": [], "applications": ["作可托付、办事可靠的人", "以接待、保管、后勤参与神的工作", "看重不显眼却必要的'后勤'服事"], "scriptures": ["提后4:13"]}, {"name": "亚历山大（铜匠）", "lesson": "多多敌对，神必报应", "witness": "亚历山大是个铜匠，'多多地敌对'保罗、抵挡所传的道。保罗提醒提摩太要防备他，并说'主必照他所行的报应他'。明知真理却执意敌对的人，把自己放在了与神为敌的位置上。", "summary": "多多敌对保罗的铜匠。", "prayer": "主啊，铜匠亚历山大多多敌对祢的真理。求祢使我永不站在抵挡祢的一边，对拦阻福音的存防备，把伸冤交托给祢。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["明知真理仍执意敌对、抵挡", "以行动多方拦阻福音"], "applications": ["不站在敌对真理、拦阻福音的一边", "对'多多敌对'真理的人有所防备", "把伸冤交给按公义报应的主"], "scriptures": ["提后4:14"]}, {"name": "亚历山大（以弗所人）", "lesson": "被推到风口浪尖的人", "witness": "亚历山大是以弗所暴乱中被犹太人推出来、想要分诉的人，却因他是犹太人，众人一见就喧嚷了两个钟头。他被卷进一场不属于自己的混乱，想说话也说不成。乱局之中，人常身不由己。", "summary": "以弗所暴乱中被推出来的犹太人。", "prayer": "主啊，亚历山大被卷进以弗所的喧嚷里。求祢使我在群体的混乱中保持清醒，不随声附和，不被人推入不该卷入的风波。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（背景）被卷入群众的喧嚷与混乱"], "applications": ["在群体的混乱中保持清醒，不随喧嚷", "不被人推到不该卷入的风口", "在嘈杂中分辨该说与不该说的"], "scriptures": ["徒19:33"]}, {"name": "腓吉路", "lesson": "患难中离弃，令人痛心", "witness": "腓吉路是保罗提到'凡在亚细亚的人都离弃我'中的一个。当保罗被囚、最需要支持时，他选择了离开。离弃不是公开的敌对，而是在患难中悄悄抽身——这种退缩同样令人痛心。", "summary": "在亚细亚离弃保罗的人。", "prayer": "主啊，腓吉路在保罗受难时离弃了他。求祢使我不在人患难时抽身，作靠得住、不离弃的人，与受苦的肢体同行到底。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["在他人患难、最需要时悄悄抽身", "为自保而离弃当扶持的人"], "applications": ["在朋友、同工患难时不退缩、不离弃", "省察自己是否在'安全'时才肯同行", "作患难中靠得住的人"], "scriptures": ["提后1:15"]}, {"name": "黑摩其尼", "lesson": "患难中一同退去的人", "witness": "黑摩其尼与腓吉路一同，是保罗所说'凡在亚细亚的人都离弃我'中被点名的两个。在保罗最艰难、最需要支持的时候，他选择了退去。离弃常常不是轰轰烈烈的背叛，而是在患难中悄然抽身——这同样让人痛心。", "summary": "与腓吉路一同离弃保罗的人。", "prayer": "主啊，黑摩其尼在保罗受难时离弃了他。求祢使我不在人患难时抽身，作坚守不离、靠得住的人，与受苦者同行到底。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["在人患难、最需要时悄然抽身", "随大流一同退去，不肯坚守"], "applications": ["在朋友、同工受难时坚守不离", "不随众抽身，作患难中靠得住的人", "省察自己是否只在顺境时才肯同行"], "scriptures": ["提后1:15"]}, {"name": "罗以", "lesson": "隔代的信心，代代相传", "witness": "罗以是提摩太的外祖母，她'无伪的信'先住在自己心里，再传给女儿友尼基，又传到外孙提摩太。三代相传的信心，成就了一位忠心的福音同工。属灵的产业，可以这样一代代传下去。", "summary": "提摩太的外祖母，有真实信心。", "prayer": "主啊，罗以的信心传了三代，结出提摩太的果子。求祢使我持守无伪的信，作儿孙的属灵榜样，把信仰代代传下去。阿们。", "tags": ["女性", "正面榜样"], "follow": ["持守'无伪的信'，作隔代的属灵榜样", "主动参与孙辈的信仰栽培"], "caution": ["不轻看祖辈对孙辈属灵生命的影响"], "applications": ["以真实的信心影响儿孙两代", "主动参与下一代、下下一代的信仰教养", "为子孙的属灵生命持续祷告"], "scriptures": ["提后1:5"]}, {"name": "友尼基", "lesson": "把真信仰，亲手传给孩子", "witness": "友尼基是提摩太的母亲，一位敬虔的犹太信徒。保罗说提摩太'无伪之信'是先在外祖母罗以和母亲友尼基心里。她从小把圣经和真信仰教导给提摩太，养育出保罗最得力的属灵儿子。", "summary": "提摩太的母亲，敬虔的犹太信徒。", "prayer": "主啊，友尼基把无伪的信传给了提摩太。求祢使我以真实的信仰生活影响家人，从小把祢的话栽种在下一代心里。阿们。", "tags": ["女性", "正面榜样"], "follow": ["从小以圣经和真信仰教养儿女", "以自己'无伪的信'作榜样"], "caution": ["不把信仰传承的责任完全外包给他人"], "applications": ["从小带孩子认识圣经与真神", "以真实（无伪）的信仰生活作榜样", "相信家庭的信仰教养影响深远"], "scriptures": ["提后1:5", "徒16:1"]}, {"name": "亚拿尼亚（撒非喇之夫）", "lesson": "为美名，向圣灵说谎", "witness": "亚拿尼亚与妻子撒非喇卖了田产，私自留下几分，却谎称全数献上。问题不在留钱（本是自由的），而在'欺哄圣灵'、为博美名而撒谎。彼得一语道破，他当场仆倒断气。在神面前的虚假，远比贫穷可怕。", "summary": "与妻子撒非喇同谋欺哄圣灵而死。", "prayer": "主啊，亚拿尼亚为美名欺哄圣灵而亡。求祢使我在祢面前全然诚实，奉献事奉不慕虚名，不向祢做表面功夫。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["为博美名而在奉献、事奉上撒谎", "以为对神也可以做表面功夫"], "applications": ["奉献与事奉量力而诚实，不慕虚名", "在神面前全然真实，不做表面功夫", "夫妻同心行善，而非同谋作假"], "scriptures": ["徒5:1-6"]}, {"name": "丢特腓", "lesson": "好作首领，关上接待的门", "witness": "丢特腓是约翰三书中那位'好作首领'的人。他不接待出外传道的弟兄，还禁止别人接待、把接待的人赶出教会，甚至用恶言妄论使徒约翰。爱权、排外、容不下别人，使他成了教会里的反面教材。", "summary": "好作首领、不接待弟兄的人。", "prayer": "主啊，丢特腓好作首领、不接待弟兄。求祢除去我里面爱权、排外的心，使我谦卑接待、尊重肢体，不贪恋掌控。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["好作首领，容不下别人", "不接待弟兄，还拦阻别人接待", "用恶言妄论属灵的长者"], "applications": ["不贪恋'作首领'的地位与掌控", "敞开接待的门，不排斥外来的肢体", "尊重属灵长者，不以恶言妄论人"], "scriptures": ["约三9-10"]}, {"name": "低米丢", "lesson": "众人都给他作美好的见证", "witness": "低米丢是约翰三书中被称许的人，'有众人给他作见证，又有真理给他作见证'。他的为人，得到群体一致的好评，连真理本身都印证他。一个名声立在真理之上的人，何等可贵。", "summary": "众人给他作美好见证的人。", "prayer": "主啊，低米丢有众人和真理为他作见证。求祢使我以真理立身，活出经得起检验的好见证，荣耀祢的名。阿们。", "tags": ["其他", "正面榜样"], "follow": ["以真理立身，赢得众人真实的好评", "让自己的见证经得起真理的印证"], "caution": [], "applications": ["追求名声立在真理之上，而非逢迎", "让你的为人经得起众人与真理的检验", "作一个'有美好见证'的人"], "scriptures": ["约三12"]}, {"name": "米迦勒", "lesson": "天使长，为神的子民争战", "witness": "米迦勒是天使长，在但以理书中为以色列争战，在犹大书中与魔鬼争辩摩西的尸首时'尚且不敢用毁谤的话'，在启示录中率天军与大龙争战。他大有能力，却凡事不僭越、单凭主的权柄。能力越大，越当谦卑顺服。", "summary": "天使长，与龙争战。", "prayer": "主啊，天使长米迦勒大有能力却谦卑顺服祢。求祢使我无论有何能力都不僭越，凭祢的权柄站立，为祢的子民忠心争战。阿们。", "tags": ["其他", "正面榜样"], "follow": ["大有能力却不僭越，凭主的权柄行事", "为神的子民忠心争战"], "caution": ["不以毁谤、亵慢对待属灵的权势"], "applications": ["越有能力越要谦卑，不靠己僭越", "在属灵争战中倚靠主的权柄，而非自夸", "以敬畏的态度对待属灵的事"], "scriptures": ["但10", "犹9", "启12"]}, {"name": "尼哥拉党人", "lesson": "主所恨恶的妥协之教", "witness": "尼哥拉党人是初代教会中的一个异端群体，主在写给以弗所和别迦摩教会的信中两次提到——以弗所教会'恨恶他们的行为'，这正合主的心意；别迦摩却容让了他们。他们大概主张可以与偶像、淫乱的世俗妥协。主明说：这是我所恨恶的。", "summary": "主所恨恶的异端群体。", "prayer": "主啊，尼哥拉党人的行为是祢所恨恶的。求祢使我分辨并拒绝引人妥协世俗的教导，恨恶罪却爱罪人，守护群体的纯正。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["主张与偶像、淫乱、世俗妥协", "在教会内引入'放纵也无妨'的教导"], "applications": ["对引人妥协世俗的'教导'存警惕", "像以弗所教会那样恨恶罪的行为", "不容让会腐蚀群体的异端与放纵"], "scriptures": ["启2:6,15"]}, {"name": "耶洗别（推雅推喇）", "lesson": "教会里的'耶洗别'，诱人妥协", "witness": "她是启示录中推雅推喇教会里那'自称是先知的妇人耶洗别'，引诱主的仆人行奸淫、吃祭偶像之物。主借旧约恶后之名称呼她，警告这种'在教会内部诱人妥协、与世俗淫乱'的危险。主给她悔改的机会，她却不肯。", "summary": "推雅推喇教会中自称先知、诱惑人的妇人。", "prayer": "主啊，推雅推喇的'耶洗别'诱人妥协沉沦。求祢使我分辨并远离教会内引人妥协的影响，不与世俗苟合，珍惜祢给的悔改机会。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["在教会内部自封权柄，诱人妥协", "引诱信徒与世俗、偶像苟合", "给了悔改机会仍不肯回转"], "applications": ["警惕教会内'诱人妥协'的声音与影响", "不与世俗、偶像的价值观苟合", "珍惜并把握神所给的悔改机会"], "scriptures": ["启2:20"]}, {"name": "龙", "lesson": "古蛇魔鬼，败局已定的仇敌", "witness": "龙是启示录中的大红龙，'就是那古蛇，名叫魔鬼，又叫撒但，是迷惑普天下的'。它要吞吃将生的孩子，与天使长米迦勒争战，又逼迫圣徒。然而它已被摔下，日子无多，最终被扔在火湖里。它凶猛狂怒，却是个败局已定、终被踩在脚下的仇敌。", "summary": "大红龙，就是古蛇魔鬼，敌对神和教会。", "prayer": "主啊，那古蛇魔鬼虽狂怒，却已被祢定了终局。求祢使我认清真正的仇敌，靠羔羊的血与真道胜过它，在逼迫中站立得稳。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["（认清仇敌）它是迷惑、控告、逼迫的源头", "它的狂怒源于自知日子无多"], "applications": ["认清真正的仇敌是魔鬼，而非人", "靠羔羊的血与所见证的道胜过它", "在它的狂怒逼迫中站稳，深知它败局已定"], "scriptures": ["启12"]}, {"name": "兽", "lesson": "亵渎与逼迫，终归火湖", "witness": "启示录中的'兽'从海里上来，得了龙的权柄，开口亵渎神，又向圣徒争战、得胜他们，迫使万民拜它、受它的印记。它是地上敌对神之政权与势力的象征，猖狂一时，结局却是被扔在火湖里。最嚣张的逼迫势力，神已定了它的终局。", "summary": "从海中上来、敌对神、亵渎神的兽。", "prayer": "主啊，那亵渎逼迫的兽终归火湖。求祢使我认清并抵挡敌对祢的势力，宁可受苦也不向它屈服，深信祢已定了它的结局。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["亵渎神、逼迫圣徒、强迫人效忠", "以权势胁迫人敬拜、受印记"], "applications": ["认清并抵挡敌对神的势力与价值体系", "宁可受害，也不向'兽'下拜、受印记", "在逼迫中持守，深信仇敌已定终局"], "scriptures": ["启13"]}, {"name": "假先知（启示录）", "lesson": "行异能迷惑人，终被神除灭", "witness": "启示录中的假先知（又称从地里上来的兽）行大奇事，迷惑住在地上的人去拜那兽与兽像。它以宗教的外貌、超自然的现象，把人引向敌对神的敬拜，最终与兽一同被扔在火湖里。能行神迹的，未必出于神——要凭真理分辨。", "summary": "与兽一同迷惑世人的假先知。", "prayer": "主啊，假先知行异能迷惑人，终被除灭。求祢赐我凭真理分辨的灵，不被神迹奇事迷惑，单单敬拜祢这位独一的真神。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["以异能、奇事迷惑人离开真神", "披宗教外衣，引人拜偶像、随从兽"], "applications": ["不凭神迹奇事，而凭真理分辨真假", "警惕披着属灵外衣的迷惑", "只敬拜独一的真神，不随从任何'兽'"], "scriptures": ["启16:13", "启19:20"]}, {"name": "大淫妇巴比伦", "lesson": "繁华淫乱的'巴比伦'，倾覆只在一时", "witness": "大淫妇巴比伦是启示录中那骑在朱红色兽上、'坐在众水之上'的城邦象征，代表悖逆神、奢华淫乱、逼迫圣徒的世界体系。她极尽繁华，却在一时之间倾倒——'巴比伦大城倾倒了'。神呼召祂的子民：从她出来，免得沾染她的罪、同受她的灾。", "summary": "象征敌对神之城邦的大淫妇。", "prayer": "主啊，大淫妇巴比伦极尽繁华却一时倾倒。求祢呼召我从她出来，不沾染世界的淫乱与悖逆，不贪恋必倾覆的荣华。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["沉醉于悖逆神之世界体系的繁华淫乱", "与'巴比伦'的罪同流，贪恋其荣华"], "applications": ["从悖逆神的价值体系中分别出来", "不贪恋、不沉醉于世界的繁华淫乱", "记得最繁华的体系也会一时倾覆"], "scriptures": ["启17-18"]}, {"name": "两个见证人", "lesson": "忠心作见证，死了又活", "witness": "两个见证人是启示录中身穿毛衣、传道作见证的两位。他们尽了职分后被兽所杀，尸首陈列三天半，众人欢喜；神却使生气进入他们，他们就站起来，被接到天上。忠心的见证者纵然被杀，神必使他们复活、得荣耀——见证主的人，结局在神手中。", "summary": "穿毛衣传道、被杀又复活的两位见证人。", "prayer": "主啊，两个见证人忠心至死，祢却使他们复活升天。求祢使我忠心作祢的见证，纵然受害，仍深信祢复活的大能与荣耀。阿们。", "tags": ["其他", "正面榜样"], "follow": ["忠心作见证，直到尽了所托的职分", "纵然受害，仍信靠神使人复活的大能"], "caution": [], "applications": ["忠心为主作见证，不惧抵挡", "相信为主受害的，神必使之复活得荣", "在见证遭嗤笑、逼迫时仍站立"], "scriptures": ["启11"]}, {"name": "以利米勒", "lesson": "为躲饥荒而离开，却失去更多", "witness": "以利米勒是拿俄米的丈夫，伯利恒（意为'粮仓'）人。遇饥荒时，他带全家迁往摩押寄居，想保住性命家业，结果客死异乡，两个儿子也死在那里。为躲一时的难处而离开神的产业之地，代价远超想象。", "summary": "拿俄米的丈夫，因饥荒带全家迁往摩押，客死他乡。", "prayer": "主啊，以利米勒为躲饥荒离开伯利恒，却失去更多。求祢使我在难处中信靠祢的供应，不凭自保的盘算擅离祢所安置之地。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["为躲避眼前的难处而离开神所赐之地", "以自保的盘算取代对神的信靠"], "applications": ["在难处中，先问神的心意，不只盘算自保", "不轻易离开神安置你的位置", "把生计的忧虑交托给供应的神"], "scriptures": ["得1:1-3"]}, {"name": "玛伦", "lesson": "他的离世，成了路得归主的转折", "witness": "玛伦是以利米勒的长子，娶摩押女子路得为妻，无子而死在摩押。他的早逝看似全然的损失，神却藉此把路得带回伯利恒、归入神的子民，成为大卫与基督的先祖。神能从最深的失丧中，带出意想不到的救赎。", "summary": "以利米勒之子，路得的前夫，死于摩押。", "prayer": "主啊，玛伦早逝，祢却藉此把路得带进了救恩的谱系。求祢使我在失丧中仍信靠祢，深知祢能从最深的损失中带出意想不到的救赎。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（背景）离开神之地的婚姻与际遇值得反思"], "applications": ["相信神能从失丧与死亡中带出救赎", "在看似全是损失的事上，仰望神的转机", "记得你生命的影响可能远超你所见"], "scriptures": ["得1:2-5"]}, {"name": "基连", "lesson": "离乡的下一代，凋零异乡", "witness": "基连是以利米勒的次子，在摩押娶了俄珥巴为妻，却没有留下后嗣就死在那里。父亲为避难带来的迁离，使这一代凋零在异乡。上一代的选择，常深深影响下一代的际遇。", "summary": "以利米勒之子，俄珥巴的丈夫，死于摩押。", "prayer": "主啊，基连凋零在摩押异乡。求祢引导我为家庭所作的选择，使我不让一代的偏离成为下一代的损失，带领全家走在祢的道中。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["（承袭提醒）上一代离开神之地的选择，影响下一代"], "applications": ["意识到自己的选择会影响儿女的际遇", "为家庭的方向求神的引导", "不让一代的偏离成为下一代的损失"], "scriptures": ["得1:2-5"]}, {"name": "亚希暖", "lesson": "患难中相随的妻子", "witness": "亚希暖是耶斯列人，大卫的妻子，暗嫩的母亲。她在大卫逃亡的艰难岁月里相随，曾在洗革拉一同被掳又被救回。她不显赫，却是大卫颠沛流离时同甘共苦的伴侣。", "summary": "耶斯列人，大卫的妻子，暗嫩的母亲。", "prayer": "主啊，亚希暖在大卫的颠沛中相随。求祢使我在所爱之人的患难中不离不弃，作同甘共苦、默默扶持的人。阿们。", "tags": ["女性", "混合型"], "follow": ["在患难中与所爱的人同甘共苦", "默默支持，不求显赫"], "caution": [], "applications": ["在配偶或家人的艰难中不离不弃", "看重患难中相随的情谊", "在不显眼的支持中忠心"], "scriptures": ["撒上25:43"]}, {"name": "以特买", "lesson": "名列勇士榜的无名者", "witness": "以特买是大卫勇士名单中的一位（摩押人，出自外邦）。他没有惊天的事迹被记下，却名列那批为大卫出生入死的勇士之中。在英雄的名册上，他是忠心却'无名'的一员——神的名册上，从不漏记忠心的人。", "summary": "摩押人，大卫的勇士之一。", "prayer": "主啊，以特买名列勇士却无显赫事迹。求祢使我甘心作忠心却无名的一员，跨越出身委身于祢，深信祢的名册记念每一个忠心人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在团队中忠心，纵然不被单独表彰", "跨越出身，委身于所效忠的"], "caution": [], "applications": ["甘心做团队里'榜上有名却无单独事迹'的忠心一员", "跨越出身的局限，委身于神的事", "相信神的名册不漏记任何忠心的人"], "scriptures": ["代上11:46"]}, {"name": "希勒斯", "lesson": "勇士榜上忠心的一员", "witness": "希勒斯是大卫的勇士之一（巴勒提人/比伦人），名列那批为大卫征战的勇士名单中。他没有单独的事迹被详述，却以忠勇跻身英雄之列。在团队里默默尽忠的人，神都一一记下他们的名。", "summary": "巴勒提人，大卫的勇士之一。", "prayer": "主啊，希勒斯名列勇士，忠心征战。求祢使我甘作团队中默默尽忠的一员，与众同心，深知祢记念每一个忠心的人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在团队中默默尽忠，共担征战"], "caution": [], "applications": ["甘心作团队中忠心却不出风头的一员", "与众人同心承担当尽的责任", "相信神记下每一个忠勇者的名"], "scriptures": ["撒下23:26"]}, {"name": "希莱", "lesson": "尼陀法的勇士，忠心无声", "witness": "希莱是尼陀法人，大卫的勇士之一。和许多勇士一样，他的名字被记在册上，事迹却无声无息。他代表那一群为王出生入死、却不为后人所详知的忠勇之士——他们的忠心，神都看见。", "summary": "尼陀法人，大卫的勇士之一。", "prayer": "主啊，希莱忠心却无声。求祢使我甘心在无人知晓处尽忠，看重被祢记念过于被人传颂，在群体里尽好我的一份。阿们。", "tags": ["其他", "正面榜样"], "follow": ["无声无息地忠心服事", "在群体中尽自己的一份力"], "caution": [], "applications": ["即使不被详知，也甘心忠勇服事", "看重'被神记念'胜过'被人传颂'", "在团队里尽好自己无声的一份"], "scriptures": ["撒下23:29"]}, {"name": "亚吉", "lesson": "神能在外邦人手中预备庇护", "witness": "亚吉是迦特的非利士王。大卫走投无路时投奔他，他不但收留，还把洗革拉城赐给大卫居住。一个外邦王，竟成了神为受逼迫之大卫预备的暂时庇护所——神的看顾，常透过意想不到的人。", "summary": "迦特的非利士王，大卫逃避扫罗时投奔他。", "prayer": "主啊，祢藉外邦王亚吉为逃难的大卫预备庇护。求祢使我也成为接纳落难者的人，并相信祢的看顾常临到意想不到之处。阿们。", "tags": ["君王", "混合型"], "follow": ["以宽容善待落难、寄居的人"], "caution": ["大卫在此处也曾以假话求存，提醒在庇护中仍要诚实"], "applications": ["向落难寄居的人伸出接纳的手", "看见神也能藉'外人'来供应你", "在艰难处境中仍持守诚实"], "scriptures": ["撒上27:1-12"]}, {"name": "哈嫩", "lesson": "错疑善意，自取其辱与其祸", "witness": "哈嫩是亚扪王拿辖之子。大卫派使者来吊唁致意，他却听信谗言，疑心使者是奸细，羞辱他们、剃去半边胡须。这一错疑引发战争，亚扪惨败。把善意当恶意，代价极大。", "summary": "亚扪王，羞辱大卫的使者，引发战争。", "prayer": "主啊，哈嫩错疑善意、羞辱使者，自招败亡。求祢使我不听谗言、不妄加猜疑，以善意待人，免得因误解酿成大祸。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["听信谗言，把别人的善意错当恶意", "以羞辱回应好意，激起本可避免的冲突"], "applications": ["不轻信挑拨，先以善意理解他人", "遇到示好时，不要疑神疑鬼地羞辱对方", "为自己的猜疑可能引发的后果负责"], "scriptures": ["撒下10"]}, {"name": "拿辖", "lesson": "羞辱人的强横，招来败亡", "witness": "拿辖是亚扪王，围困基列雅比时，竟以剜出右眼羞辱全城为立约条件。他的残暴反成了扫罗被立为王后头一场得胜的契机——神用他的强横，成就了对以色列的拯救。", "summary": "亚扪王，围困基列雅比，被扫罗击败。", "prayer": "主啊，拿辖以羞辱人逞强，终被击败。求祢使我尊重每个人的尊严，绝不以势压人，也求祢搭救一切落在绝境中的人。阿们。", "tags": ["君王", "混合型"], "follow": [], "caution": ["以羞辱、践踏人的尊严来彰显权势", "欺凌处于绝境、无力反抗的人"], "applications": ["绝不以羞辱他人来显示自己的强势", "顾念落在绝境中之人的尊严", "相信神能扭转强横者所设的局"], "scriptures": ["撒上11"]}, {"name": "以未米罗达", "lesson": "一念之仁，黑暗中的微光", "witness": "以未米罗达是巴比伦王，登基后竟把被囚三十七年的犹大王约雅斤从牢里提出来，给他高位、与他同席用饭直到死。在被掳的漫长黑暗里，这一念之仁像一束微光，预示神对祂子民的怜悯尚未断绝。", "summary": "巴比伦王，释放被囚的约雅斤并恩待他。", "prayer": "主啊，祢藉以未米罗达善待被囚的约雅斤，显出黑暗中的怜悯。求祢使我也以仁慈待落难的人，作传递祢怜悯的微光。阿们。", "tags": ["君王", "混合型"], "follow": ["以仁慈善待落难、被囚的人", "在权力中施行怜悯"], "caution": ["善待人的同时，仍要敬畏赐权柄的神"], "applications": ["善用你的权力或影响去恩待落难者", "在别人的'牢狱'低谷中送去一束光", "相信神的怜悯在黑暗中仍然运行"], "scriptures": ["王下25:27-30"]}, {"name": "苏撒拿", "lesson": "以财物供给主的妇女之一", "witness": "苏撒拿是跟随耶稣、用自己的财物供给主和门徒的妇女之一，与抹大拉的马利亚、约亚拿同被路加提名。她们的供给，默默托住了主的传道团队。被提名的这几位之外，还有'许多别的妇女'——服事主的，从不缺这样默默奉献的人。", "summary": "供给耶稣和门徒所需的妇女之一。", "prayer": "主啊，苏撒拿用财物供给祢的传道之工。求祢使我也甘心以资源供给祢的事工，在幕后默默奉献，托住祢的工作。阿们。", "tags": ["女性", "正面榜样"], "follow": ["以自己的财物供给主的工", "在幕后默默奉献、托住事工"], "caution": [], "applications": ["以钱财、资源供给神的事工", "看重幕后供给型的服事", "与同心的姊妹一起奉献服事"], "scriptures": ["路8:3"]}, {"name": "尼禄", "lesson": "逼迫之火，烧不尽福音", "witness": "尼禄是保罗上诉的罗马皇帝，传统上保罗与彼得都在他的逼迫中殉道。这位以残暴著称的皇帝想用火与刀扑灭信仰，福音却越烧越旺。最凶猛的逼迫，也挡不住神国的扩展。", "summary": "保罗上诉的罗马皇帝（该撒），传统上保罗殉道时期的皇帝。", "prayer": "主啊，尼禄的逼迫烧不尽祢的福音。求祢坚固一切在压力与逼迫中的信徒，使我深信祢的国度胜过世上一切强权。阿们。", "tags": ["君王", "警戒为主"], "follow": [], "caution": ["以权力与暴力逼迫信仰", "以为能用强权扑灭真理"], "applications": ["在逼迫与压力中持守信仰，不退缩", "相信福音的能力胜过一切强权", "为今日受逼迫的信徒祷告"], "scriptures": ["徒25:11", "提后4:16-17"]}, {"name": "迷失的羊", "lesson": "一只迷羊，牧人撇下九十九只去寻", "witness": "迷失的羊是耶稣比喻中的主角：一百只羊走失了一只，好牧人就撇下九十九只，去找那迷失的，直到找着，就欢欢喜喜扛在肩上回来。耶稣说，一个罪人悔改，在天上也要这样为他欢喜。每一只迷羊，在牧人眼中都值得被寻回。", "summary": "比喻中失而复得的羊，象征罪人悔改、牧人寻回。", "prayer": "主啊，祢是撇下九十九只去寻一只迷羊的好牧人。求祢寻回我每一次的走失，也使我有牧人的心，去寻找迷失的人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["像迷羊一样，甘愿被牧人寻回", "效法好牧人，去寻找迷失的人"], "caution": ["不要远离羊群、独自走失"], "applications": ["相信你迷失时，主必撇下九十九只来寻你", "去寻找那些迷失、走偏的人", "为一个罪人的悔改而真心欢喜"], "scriptures": ["路15:3-7"]}, {"name": "讥诮的强盗", "lesson": "近在咫尺，却讥诮救恩", "witness": "他与耶稣同钉十字架，却和旁人一同讥诮：'你不是基督吗？可以救自己和我们吧！'救主就在他身边，他却以讥诮代替了求告。同样的处境，悔改的强盗得了乐园，他却在嘲讽中错过了。离救恩最近的人，也可能硬着心错失。", "summary": "与耶稣同钉、讥诮主的另一个强盗。", "prayer": "主啊，讥诮的强盗近在祢旁却错失了乐园。求祢软化我的心，使我不以质疑讥诮待祢，趁还有时候就谦卑求告祢。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["以讥诮、试探的态度对待基督", "近在咫尺却硬心错过救恩"], "applications": ["不以讥诮、质疑的态度对待主", "趁还有机会时谦卑求告，而非嘲讽", "省察：我离主很近，却真认识祂吗？"], "scriptures": ["路23:39"]}, {"name": "文士", "lesson": "通晓律法，却可能错过律法的主", "witness": "文士是抄写、教导律法的专家，本该最认识神的话。然而许多文士'能说不能行'，把重担捆在别人身上，自己一个指头也不肯动，甚至与法利赛人一同抵挡、定罪耶稣。最熟悉圣经的人，也可能与圣经所指向的主擦肩而过。", "summary": "抄写、教导律法的宗教学者群体，常与耶稣冲突。", "prayer": "主啊，文士通晓律法却错过了律法的主。求祢使我不只懂祢的话，更去遵行；不言行不一，叫我的知识引我更认识祢。阿们。", "tags": ["其他", "混合型"], "follow": ["看重对神话语的认识与教导（其本职之善）"], "caution": ["能说不能行，言行不一", "把重担加给人，自己却不肯担", "熟悉圣经却抵挡圣经所指向的主"], "applications": ["不只懂得神的话，更要去行", "不把难担的重轭只加给别人", "让对圣经的认识引你认识主自己"], "scriptures": ["太23"]}, {"name": "法利赛人", "lesson": "严守外表，却忽略了内心", "witness": "法利赛人热心守律法与传统，在当时极受敬重。然而耶稣多次责备他们：洗净杯盘的外面，里面却盛满勒索与放荡；把薄荷茴香献上十分之一，却忽略了公义、怜悯、信实。他们中也有尼哥底母、保罗这样真寻求的人——外表的虔诚，需要内心的真实来充满。", "summary": "严守律法传统的犹太教派，常被耶稣责备假冒为善。", "prayer": "主啊，法利赛人守了外表却忽略内心。求祢使我里外一致，不假冒为善，看重公义、怜悯与信实，以谦卑代替自义。阿们。", "tags": ["其他", "混合型"], "follow": ["热心追求圣洁与遵行（其本意之善）"], "caution": ["注重外表、规条，忽略内心与怜悯", "假冒为善，以敬虔的外貌掩盖里面的污秽", "自义地论断、轻看别人"], "applications": ["追求里外一致的真实，而非表面虔诚", "不忽略公义、怜悯、信实这些'更重的'", "以谦卑代替自义，不轻看他人"], "scriptures": ["太23"]}, {"name": "撒都该人", "lesson": "只取今生，便失了复活的盼望", "witness": "撒都该人是当时的祭司贵族阶层，把持圣殿，只承认摩西五经，不信复活、不信天使。他们用'七个兄弟娶同一妻子'的难题试探耶稣，主回答：你们错了，因为不明白圣经，也不晓得神的大能。只信今生、不信复活的人，把自己关在了狭小的世界里。", "summary": "祭司贵族教派，不信复活。", "prayer": "主啊，撒都该人不信复活，被祢指为不明白圣经、不晓得大能。求祢使我持守复活的盼望，既明白祢的话，也信靠祢的大能。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["不信复活与超然，只取今生现实", "以理性的难题试探、否定神的大能", "把持宗教权位，却失了真信仰"], "applications": ["持守复活与永生的盼望，不只看今生", "明白圣经、也信靠神的大能，两者并重", "不让现实主义掏空信仰的超然维度"], "scriptures": ["太22:23"]}, {"name": "希律党人", "lesson": "政治的算计，与对头联手害主", "witness": "希律党人是拥护希律王朝、亲罗马的政治群体。他们本与法利赛人立场对立，却为了除掉耶稣而联手——'法利赛人就出去，同希律党的人商议怎样可以除灭耶稣'。又来用纳税的问题试探主。当政治算计盖过真理，昔日的对头也能为除掉基督而结盟。", "summary": "拥护希律王朝的政治群体，与法利赛人合谋陷害耶稣。", "prayer": "主啊，希律党人为除灭祢与对头联手。求祢使我不让政治算计盖过对祢的忠诚，以真理判断是非，不为私怨结党。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["以政治立场与算计取代对真理的忠诚", "为除掉眼中钉，与对头结盟"], "applications": ["不让政治立场凌驾于对真理的忠诚", "警惕'为了对付某人'而结成的联盟", "以真理而非利害来判断是非"], "scriptures": ["可3:6"]}, {"name": "基比亚的利未人", "lesson": "自身的失责，酿成大乱", "witness": "他是带妾经过基比亚的利未人。当恶人围屋，他竟把妾推出去顶替自己，任其受害致死，事后又把尸身分送各支派激起公愤，引发内战。他既是受害一方，自己的自保与冷酷也难辞其咎——乱世中，连受害者也可能失了人性。", "summary": "带妾返家、在基比亚遭遇暴行的利未人。", "prayer": "主啊，基比亚的利未人为自保推出了妾，酿成大乱。求祢保守我的良心不被乱世侵蚀，危难中不牺牲他人，处理冤屈寻求公义而非报复。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["为自保把别人推向危险", "以激烈手段宣泄，引发更大的流血"], "applications": ["危难中不以牺牲他人来保全自己", "处理冤屈时寻求公义，而非煽动更大的暴力", "省察：乱世的风气是否也侵蚀了我的良心"], "scriptures": ["士19"]}, {"name": "利未人的妾", "lesson": "黑暗时代里无名的受害者", "witness": "她是基比亚那位利未人的妾，在士师时代的乱世里，被恶人凌辱致死，引发了以色列内战。圣经如实记下这桩惨剧，正是要显明'那时以色列中没有王，各人任意而行'之世代的黑暗与残忍。", "summary": "在基比亚被凌辱致死，引发支派内战。", "prayer": "主啊，基比亚的暴行夺去了这无名妾的性命。求祢怜悯一切受暴力侵害的人，使我持守公义，作保护软弱者的人，不随乱世任意而行。阿们。", "tags": ["女性", "警戒为主"], "follow": [], "caution": ["（时代警戒）无王无法、任意而行带来的残暴", "对软弱者的漠视与暴行"], "applications": ["为遭受暴力侵害的无名者哀哭、代求", "在'人人任意而行'的风气中持守公义", "成为保护软弱者的人，而非漠视者"], "scriptures": ["士19"]}, {"name": "希斯仑", "lesson": "默默无名，却在救恩谱系中", "witness": "希斯仑是法勒斯的儿子，圣经几乎没有记载他的事迹，但他是犹大支派承上启下的一环，名字稳稳地写在大卫与基督的家谱里。神的救赎计划，正是藉着无数这样'只留下名字'的人代代相传。", "summary": "法勒斯之子，犹大支派、大卫与基督谱系的一环。", "prayer": "主啊，希斯仑虽默默无名，却在祢救恩的谱系中。求祢使我安于平凡的本分，忠心承接，深知我的名字祢都记念。阿们。", "tags": ["其他", "混合型"], "follow": ["在平凡甚至默默无名中，忠心地承上启下", "看重'被记念在神的名册上'胜过被人记得"], "caution": ["不因不被人注意而轻看自己的位置"], "applications": ["在不起眼的角色中忠心，你也在神的故事里", "看重为下一代承接信仰的责任", "相信神记念每一个默默尽本分的人"], "scriptures": ["得4:18", "太1:3"]}, {"name": "兰", "lesson": "家谱里的隐形一环", "witness": "兰（又作亚兰）是希斯仑的儿子、亚米拿达的父亲，弥赛亚谱系中的一环。圣经几乎没有记载他的事迹，但少了这一环，从法勒斯到大卫、到基督的链条就接不起来。隐形的一环，也是不可或缺的。", "summary": "希斯仑之子，弥赛亚谱系一环（又作亚兰）。", "prayer": "主啊，兰虽隐于家谱，却是不可或缺的一环。求祢使我甘心在不被看见处忠心，深知祢的救恩链条里也有我的一环。阿们。", "tags": ["其他", "混合型"], "follow": ["甘作家谱中隐形却不可或缺的一环"], "caution": ["不因不被记载而轻看自己的价值"], "applications": ["在不被看见的位置忠心，你也在神的链条里", "看重承上启下的责任", "相信神记念每一个隐形的环节"], "scriptures": ["得4:19", "太1:3"]}, {"name": "亚米拿达", "lesson": "为下一代预备道路", "witness": "亚米拿达是兰的儿子、拿顺的父亲，女儿以利沙巴嫁给亚伦作大祭司的妻子。他自己事迹无多，却生养、联结起出埃及一代的领袖，为犹大支派的兴起预备了道路。", "summary": "拿顺之父，弥赛亚谱系一环。", "prayer": "主啊，亚米拿达为下一代的领袖预备了道路。求祢使我忠心养育、联结，为后来者铺路，成为祢工作中隐藏的祝福。阿们。", "tags": ["其他", "混合型"], "follow": ["默默养育、联结，为下一代预备道路", "以家庭联结服事神的群体"], "caution": ["不轻看为下一代铺路的价值"], "applications": ["为下一代的兴起默默铺路", "看重家庭在神群体中的联结作用", "相信你今日的养育影响深远"], "scriptures": ["得4:19", "太1:4"]}, {"name": "拿顺", "lesson": "带头跟随，作群体的表率", "witness": "拿顺是犹大支派的首领，在旷野安营起行时，犹大营总是头一个出发跟随神的引导；献坛的礼物他也率先献上。他是基督家谱中的一环，更是'带头顺服'的表率——别人观望时，他先迈步。", "summary": "犹大支派的首领，弥赛亚谱系一环。", "prayer": "主啊，拿顺带头跟随祢的引导、率先摆上。求祢使我在群体中作顺服的表率，别人观望时我先迈步，以行动荣耀祢。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在群体中带头顺服、率先跟随", "以行动作他人的表率"], "caution": ["不在该带头时退到人后观望"], "applications": ["在需要有人先迈步时，甘心作那一个", "以身作则，带动身边的人跟随神", "把'带头'看作责任而非荣耀"], "scriptures": ["民1:7", "得4:20"]}, {"name": "撒门", "lesson": "迎娶外邦的喇合，恩典临到家谱", "witness": "撒门是拿顺的儿子、波阿斯的父亲。按传统，他娶了耶利哥的妓女喇合为妻——一个因信归入神民的外邦女子。藉着这桩婚姻，恩典与外邦人一同被编进了弥赛亚的家谱。", "summary": "波阿斯之父，娶喇合，弥赛亚谱系一环。", "prayer": "主啊，撒门迎娶了归信的喇合，恩典就临到家谱。求祢除去我心里的成见，使我接纳一切因信归祢的人，正如祢接纳了我。阿们。", "tags": ["其他", "混合型"], "follow": ["接纳因信归主的人，不论其出身", "让恩典跨越身份与种族的界限"], "caution": ["不以出身论断神所接纳的人"], "applications": ["接纳并尊重因信归主、出身不同的人", "看见神的家谱里满了恩典与接纳", "不让成见拦阻你接纳神所接纳的"], "scriptures": ["得4:21", "太1:5"]}, {"name": "撒拉铁", "lesson": "被掳之中，谱系仍未断", "witness": "撒拉铁是被掳之王约雅斤的儿子、所罗巴伯的父亲。国破家亡、王朝似乎断绝，大卫的灯却没有熄灭——这条谱系穿过被掳的黑暗，一直延伸到基督。神的应许，黑暗也遮不住。", "summary": "约雅斤之子，所罗巴伯之父，被掳后谱系一环。", "prayer": "主啊，撒拉铁在被掳中承接了大卫的谱系，祢的灯总不熄灭。求祢使我在黑暗低谷中仍持守盼望，深信祢的应许必不落空。阿们。", "tags": ["其他", "混合型"], "follow": ["在国族的黑暗与低谷中，持守身份与盼望"], "caution": ["不因环境绝望就以为神的应许落空"], "applications": ["在人生的'被掳'低谷里，持守神给你的应许", "相信神的计划能穿过最黑的时期", "为家族与下一代守住信仰的灯"], "scriptures": ["拉3:2", "太1:12"]}, {"name": "该南", "lesson": "在平凡的代际中默默传承", "witness": "该南是以挪士的儿子，亚当敬虔家谱的第四代。圣经只记下他生子、又活了多少年、就死了。他没有惊天事迹，却是这条通向挪亚、亚伯拉罕之谱系中不可缺的一环。", "summary": "以挪士之子，亚当敬虔家谱第四代。", "prayer": "主啊，该南在家谱中默默承传。求祢使我安于自己的位置，忠心地把信仰传下去，深知祢看重每一代的忠心。阿们。", "tags": ["其他", "混合型"], "follow": ["在平凡无名中，忠心承上启下", "看重把信仰的血脉传下去"], "caution": ["不轻看自己'只是其中一代'的价值"], "applications": ["安于平凡，在自己这一代忠心", "把信仰当作产业传给下一代", "相信神记念每一个默默承传的人"], "scriptures": ["创5:9-14"]}, {"name": "玛勒列", "lesson": "生命短长不在己，忠心在己", "witness": "玛勒列是该南的儿子，亚当家谱中的一代。创世记第五章为他写下同样的句式：生子、活了若干年、就死了。死亡笼罩每一代，而敬虔的香火却在'就死了'的间隙中一代代传续。", "summary": "该南之子，亚当家谱一代。", "prayer": "主啊，玛勒列的一生也归于'就死了'，敬虔却得以传续。求祢教我数算年日，在有限里忠心，把盼望存在那胜过死亡的祢身上。阿们。", "tags": ["其他", "混合型"], "follow": ["在有限的年日里，忠心承接所托", "把握神所量给的年日传承信仰"], "caution": ["不因生命短暂而虚度，也不因平凡而懈怠"], "applications": ["数算自己的日子，过有忠心的一生", "在有限的年日里把信仰传下去", "坦然面对'就死了'的现实，把盼望放在神"], "scriptures": ["创5:12-17"]}, {"name": "雅列", "lesson": "作敬虔之人（以诺）的父亲", "witness": "雅列是玛勒列的儿子、以诺的父亲。他自己事迹无多，却养育出那位'与神同行、被神取去'的以诺。默默无闻的父亲，有时正是非凡儿女信仰的根。", "summary": "玛勒列之子，以诺之父。", "prayer": "主啊，雅列养育出与祢同行的以诺。求祢使我忠心养育下一代，作他们信仰的根，纵然无名，也以儿女的敬虔为荣。阿们。", "tags": ["其他", "混合型"], "follow": ["默默养育，作下一代信仰的根", "为儿女的属灵生命扎根"], "caution": ["不忽略对子女敬虔生命的栽培"], "applications": ["看重对儿女属灵生命的养育", "甘心作'非凡儿女'背后无名的根", "为下一代能'与神同行'祷告"], "scriptures": ["创5:15-20"]}, {"name": "拉麦", "lesson": "在劳苦中盼望神的安慰", "witness": "拉麦是玛土撒拉的儿子、挪亚的父亲。他给儿子起名'挪亚（安慰）'，说：这儿子必为我们的操作和手中的劳苦安慰我们，因为神咒诅了地。他在劳苦的世代里，把盼望寄托在神所应许的安慰上。", "summary": "玛土撒拉之子，挪亚之父。", "prayer": "主啊，拉麦在劳苦中盼望安慰，神就藉挪亚施行拯救。求祢在我的重担中赐下祢的安慰，使我满怀盼望地养育下一代。阿们。", "tags": ["其他", "混合型"], "follow": ["在劳苦中持守对神安慰的盼望", "以信心为下一代命名、立志"], "caution": ["不让世代的劳苦压垮对神的盼望"], "applications": ["在重压与劳苦中，仰望神的安慰", "以信心和盼望养育、期许下一代", "相信神能从你的后代兴起祝福"], "scriptures": ["创5:25-31"]}, {"name": "含", "lesson": "轻看长辈，招来咒诅", "witness": "含是挪亚的儿子、迦南的父亲。他看见父亲醉酒赤身，不但不遮盖，反倒出去张扬。结果他的后裔迦南受了咒诅。一时的轻看与张扬，带来了世代的后果。", "summary": "挪亚之子，迦南之父。", "prayer": "主啊，含因张扬父亲的羞辱招来咒诅。求祢除去我里面轻看与张扬人的心，使我以遮盖和敬重待人。阿们。", "tags": ["其他", "混合型"], "follow": [], "caution": ["轻看、张扬长辈或他人的羞辱", "以嘲笑代替遮盖与敬重"], "applications": ["遇见别人的失态，选择遮盖而非张扬", "存敬重的心对待长辈", "记得轻慢的态度会带来长远的后果"], "scriptures": ["创9:18-25"]}, {"name": "雅弗", "lesson": "同心行善，蒙神扩张", "witness": "雅弗是挪亚的儿子，与闪一同倒退着进去遮盖了父亲。挪亚祝福他说：愿神使雅弗扩张，使他住在闪的帐棚里。他以敬重同心行了善，也承受了'扩张'的祝福，后裔分布在列邦。", "summary": "挪亚之子，列邦分布之祖之一。", "prayer": "主啊，雅弗与闪同心遮盖父亲，承受了扩张的福。求祢使我与人同心行善，作遮盖与和睦的人，蒙祢扩张使用。阿们。", "tags": ["其他", "混合型"], "follow": ["与人同心行善、遮盖软弱", "在合宜的事上与弟兄同行"], "caution": ["不参与张扬、轻看他人的事"], "applications": ["与人同心做遮盖、造就的事", "在家庭与群体中作和睦的力量", "相信同心行善的，神必使之扩张"], "scriptures": ["创9:27,10:2"]}, {"name": "迦南（含之子）", "lesson": "咒诅之下，仍有回转的余地", "witness": "迦南是含的儿子，因父亲的轻慢承受了'必给弟兄作奴仆'的咒诅，后裔成了迦南诸族。这地后来因罪孽满盈被神审判。然而同出迦南之地的喇合却因信蒙恩——血统的咒诅之下，信心仍能带来转机。", "summary": "含之子，受咒诅，迦南诸族之祖。", "prayer": "主啊，迦南承受了咒诅，喇合却因信蒙恩。求祢使我不以出身为借口，靠信心打破家族的负面循环，归入祢的祝福。阿们。", "tags": ["其他", "警戒为主"], "follow": [], "caution": ["承袭家族的罪与咒诅，随波逐流", "容让罪孽在世代中累积满盈"], "applications": ["不以'家族如此'为借口，可凭信回转", "打破家族中负面的循环与咒诅", "相信信心能改写血统所定的命运（如喇合）"], "scriptures": ["创9:25,10:6"]}, {"name": "他拉", "lesson": "走到半路，不要停在哈兰", "witness": "他拉是亚伯拉罕的父亲。他带着亚伯兰、罗得离开吾珥，本要往迦南去，却走到哈兰就住下了，终老于此。他迈出了第一步，却没有走到神所指的终点。半途而止，是许多人共同的危险。", "summary": "亚伯拉罕之父，从吾珥迁往哈兰。", "prayer": "主啊，他拉走到哈兰就停住了。求祢使我不半途而废，不被舒适的中途站绊住，一直走到祢为我所定的应许之地。阿们。", "tags": ["其他", "混合型"], "follow": ["有勇气迈出离开旧地的第一步"], "caution": ["走到半路就停下，未到神所指的终点", "让'哈兰'（舒适的中途站）取代了应许之地"], "applications": ["不要在通往神应许的半路上安顿下来", "察验自己是否停在了某个'哈兰'", "求神赐你走到底的恒心"], "scriptures": ["创11:24-32"]}, {"name": "拿鹤", "lesson": "留在家乡的一支，也在神的安排中", "witness": "拿鹤是亚伯拉罕的兄弟。他没有像亚伯兰那样被呼召出去，留在了本族本乡，却成了利百加、拉班一家的源头——日后以撒、雅各的妻子都从他这一支而来。神的计划，也藉着'留下来'的人成全。", "summary": "亚伯拉罕兄弟，利百加家族之祖。", "prayer": "主啊，拿鹤虽留在本乡，祢的计划仍藉他的后裔成全。求祢使我在所在之处忠心，深知祢能藉各样的人成就祂的旨意。阿们。", "tags": ["其他", "混合型"], "follow": ["在自己所在之处忠心，也被神使用", "作家族延续与联结的一环"], "caution": ["不轻看'未蒙特别呼召'之人的价值"], "applications": ["无论被差出去还是留在原处，都忠心事神", "看重家族中维系联结的角色", "相信神的计划藉各样的人成全"], "scriptures": ["创11:26-29"]}, {"name": "哈兰", "lesson": "生命虽短，影响仍在", "witness": "哈兰是他拉的儿子、亚伯拉罕的兄弟、罗得的父亲。他在本地吾珥英年早逝，死在父亲之先。他自己的人生短暂，留下的罗得却一路与亚伯拉罕同行，成为后来摩押、亚扪的源头。", "summary": "亚伯拉罕兄弟，罗得之父，死于吾珥。", "prayer": "主啊，哈兰英年早逝，祢仍看顾他所留下的。求祢使我珍惜有限的年日，尽上当尽的责任，把所爱的人交托在祢手中。阿们。", "tags": ["其他", "混合型"], "follow": ["纵然生命短暂，仍留下后代的托付"], "caution": ["人生短长难料，要把握当尽的责任"], "applications": ["珍惜有限的年日，尽好为人父母的责任", "把所牵挂的人交托给神看顾", "在无常中把盼望放在神身上"], "scriptures": ["创11:27-28"]}, {"name": "以拜尼土", "lesson": "初熟的果子，所亲爱的", "witness": "以拜尼土是保罗'所亲爱的'，被称为'亚西亚归基督初结的果子'。他是那一带头一个信主的人——初熟的果子，往往要付更多的勇气，也格外被神与人珍爱。", "summary": "亚西亚初结果子归基督的人，保罗所亲爱的。", "prayer": "主啊，以拜尼土是亚西亚初结的果子。求祢使我有勇气作群体中第一个归向祢的人，以我的信带动后来者。阿们。", "tags": ["其他", "正面榜样"], "follow": ["甘心作群体中'第一个'归向主的人", "以初熟果子的勇气带动后来者"], "caution": [], "applications": ["在尚无人信的地方，甘作第一个", "以自己的归主带动身边的人", "珍惜并坚固那些'初信、初结'的人"], "scriptures": ["罗16:5"]}, {"name": "安多尼古", "lesson": "在使徒中是有名望的", "witness": "安多尼古是保罗的亲属，曾与保罗一同坐监，被称为'在使徒中是有名望的，且比保罗先信基督'。他既有同受患难的经历，又有早信、被众人敬重的属灵分量。患难与资历，都成了他服事的根基。", "summary": "与保罗一同坐监的亲属，在使徒中有名望。", "prayer": "主啊，安多尼古同受患难、在使徒中有名望。求祢使我甘与人同担患难，以长久的忠心服事祢，也敬重信仰的前辈。阿们。", "tags": ["其他", "正面榜样"], "follow": ["甘与人同受患难、同坐监", "以早信、忠心赢得属灵的敬重"], "caution": [], "applications": ["甘心与受苦的肢体同担患难", "以长久的忠心赢得属灵的分量", "看重那些'比我先信'、值得敬重的前辈"], "scriptures": ["罗16:7"]}, {"name": "犹尼亚", "lesson": "在使徒中有名望的", "witness": "犹尼亚与安多尼古一同被保罗问安，称为'我亲属，与我一同坐监的，在使徒中是有名望的，比我先在基督里'。她（或他）既同受患难，又早信、被广泛敬重。无论解释如何，这是一位极受尊重、为主受过苦的人。", "summary": "与安多尼古一同被保罗称许的信徒。", "prayer": "主啊，犹尼亚同受患难、在使徒中有名望。求祢使我甘与人同担患难，以忠心赢得敬重，也敬重为祢受苦的前辈。阿们。", "tags": ["女性", "正面榜样"], "follow": ["甘与人同受患难、同坐监", "以早信与忠心赢得众人的敬重"], "caution": [], "applications": ["甘心与受苦的肢体同担患难", "以长久忠心赢得属灵的分量", "敬重那些为主受过苦的前辈"], "scriptures": ["罗16:7"]}, {"name": "暗伯利", "lesson": "主里所亲爱的", "witness": "暗伯利是保罗'在主里所亲爱的'。这是个常见于当时奴仆的名字，使徒却以'主里所亲爱'相称。在基督里，身份高低不再是隔阂——卑微之人也是'所亲爱的'。", "summary": "保罗在主里所亲爱的。", "prayer": "主啊，暗伯利是祢里所亲爱的，纵然身份卑微。求祢使我在祢里跨越尊卑，以真挚的爱待每一位肢体。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在主里彼此以'亲爱'相待，不分尊卑"], "caution": [], "applications": ["在主里跨越身份待人如亲爱的肢体", "不以社会地位区别对待弟兄姊妹", "珍惜在基督里被爱、彼此相爱的关系"], "scriptures": ["罗16:8"]}, {"name": "耳巴奴", "lesson": "在基督里一同做工的", "witness": "耳巴奴是保罗称为'在基督里与我们同工的'。这名字意为'城里人'，也常是奴仆之名。他不显赫，却实实在在地与使徒'一同做工'。在基督的工场里，'同工'二字就是对一个人最实在的肯定。", "summary": "在基督里与保罗同工的。", "prayer": "主啊，耳巴奴与使徒一同做工。求祢使我也甘作祢工场里实干的同工，与人并肩，忠心做主的工。阿们。", "tags": ["其他", "正面榜样"], "follow": ["实实在在地与人一同做主的工", "甘作团队中并肩做工的一员"], "caution": [], "applications": ["在神的工作中与人并肩、实干", "看重'同工'的身份过于头衔", "在团队中作可靠的做工者"], "scriptures": ["罗16:9"]}, {"name": "士大古", "lesson": "保罗所亲爱的", "witness": "士大古是保罗在罗马书问安的弟兄，被称为'我所亲爱的'。一句简单的'亲爱的'，道出他与使徒之间真实的情谊。在基督里，人与人之间这份单纯而真挚的相爱，本身就是宝贵的见证。", "summary": "保罗所亲爱的同伴。", "prayer": "主啊，士大古是保罗所亲爱的。求祢使我在祢里面与肢体建立真挚的情谊，以真诚的爱彼此相待，作相爱的见证。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在基督里与肢体建立真挚的情谊", "以真诚的爱待身边的弟兄姊妹"], "caution": [], "applications": ["珍惜并经营在主里真挚的友谊", "以'亲爱'而非客套去待肢体", "让弟兄相爱成为你的见证"], "scriptures": ["罗16:9"]}, {"name": "亚比利", "lesson": "经过试验，蒙主称许", "witness": "亚比利是保罗在罗马书问安的一位弟兄，被称为'在基督里经过试验的'。他的信心不是未经考验的空谈，而是历经磨炼、被证实为真的。经得起试验的信心，才配得这样的称许。", "summary": "在基督里经过试验、蒙称许的。", "prayer": "主啊，亚比利的信心经过试验、蒙了称许。求祢使我的信心也经得起考验，在磨炼中被证实为真，蒙祢喜悦。阿们。", "tags": ["其他", "正面榜样"], "follow": ["让信心经得起试验的考验", "在磨炼中证实自己的真实"], "caution": [], "applications": ["不怕信心被试验，试验显出真实", "在磨炼中持守，直到被证实为真", "渴慕'经过试验、蒙主称许'的生命"], "scriptures": ["罗16:10"]}, {"name": "希罗天", "lesson": "保罗的亲属，在主里被记念", "witness": "希罗天是保罗在罗马书问安的'亲属'之一。血缘的亲属又成了主内的肢体，这双重的情分被使徒特意记下。亲人若能一同在主里，那份亲情就被提升为永恒的弟兄之情。", "summary": "保罗的亲属。", "prayer": "主啊，希罗天既是保罗的亲属，又是主内肢体。求祢使我的亲人也一同归入祢里，把血缘的情分提升为永恒的弟兄之爱。阿们。", "tags": ["其他", "正面榜样"], "follow": ["盼望血缘的亲人也一同归入主里", "珍惜亲属又是肢体的双重情分"], "caution": [], "applications": ["为自己尚未信主的亲人祷告", "珍惜并见证'亲人又是肢体'的关系", "把血缘的亲情提升为主里的相爱"], "scriptures": ["罗16:11"]}, {"name": "土非拿", "lesson": "为主劳苦，名列问安", "witness": "土非拿是保罗问安的姊妹，与土富撒一同被称为'为主劳苦的'。她们在罗马教会默默服事，具体做了什么没有记载，但'为主劳苦'四个字，就是使徒给她们最高的褒奖。", "summary": "为主劳苦的姊妹。", "prayer": "主啊，土非拿为祢劳苦，被使徒记念。求祢使我在教会里甘心为祢劳苦，不求人的记载，只求在祢面前忠心。阿们。", "tags": ["女性", "正面榜样"], "follow": ["在教会里甘心为主劳苦", "不求记载，只求忠心服事"], "caution": [], "applications": ["在教会中找到可摆上的服事，甘心劳苦", "不在意是否被记载，只在意是否忠心", "与同心的姊妹一起服事主"], "scriptures": ["罗16:12"]}, {"name": "土富撒", "lesson": "为主劳苦的姊妹", "witness": "土富撒是保罗问安的姊妹之一，与土非拿一同被称为'为主劳苦的'。两个名字常并列，像一对同心服事的姊妹。她们的劳苦不为人知的细节，主却看见、记念，使徒也特意问安。", "summary": "与土非拿一同为主劳苦的姊妹。", "prayer": "主啊，土富撒为祢劳苦，被记在问安里。求祢使我甘心为祢默默劳苦，与同伴同心服事，深知祢记念一切的摆上。阿们。", "tags": ["女性", "正面榜样"], "follow": ["甘心为主劳苦，不计声名", "与姊妹同心服事"], "caution": [], "applications": ["甘心为主默默劳苦，不求人知", "与同伴同心服事，彼此扶持", "相信主记念你为祂所付的劳苦"], "scriptures": ["罗16:12"]}, {"name": "彼息", "lesson": "为主多多劳苦的姊妹", "witness": "彼息是保罗'所亲爱的'姊妹，被称为'为主多多劳苦的'。'多多'二字，显出她劳苦的分量。她的服事或许不为人详知，使徒却郑重地记下她为主付出的辛劳。", "summary": "所亲爱、为主多多劳苦的姊妹。", "prayer": "主啊，彼息为祢多多劳苦。求祢使我也甘心为祢尽力付出，不计较人的看见，深信祢记念我一切的劳苦。阿们。", "tags": ["女性", "正面榜样"], "follow": ["为主甘心多多地劳苦付出", "不计较是否被人看见"], "caution": [], "applications": ["在服事上甘心'多多'地付出，不惜力", "不在意被不被看见，只求主喜悦", "相信你为主的劳苦，主都一一记念"], "scriptures": ["罗16:12"]}, {"name": "鲁孚", "lesson": "在主蒙拣选的，连同他母亲", "witness": "鲁孚是保罗'在主蒙拣选的'，很可能就是为耶稣背十字架的古利奈人西门的儿子。保罗连他的母亲也一同问安，说'她就是我的母亲'——显见这一家待保罗如亲人。一次'被迫背十架'的相遇，竟把全家带成了主所拣选、与使徒亲如一家的人。", "summary": "在主蒙拣选的，其母亲待保罗如同母亲。", "prayer": "主啊，鲁孚在祢蒙拣选，他全家待保罗如亲人。求祢使我珍惜家族与祢相连的恩典，以亲情般的爱待祢的仆人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["承接家族与十字架的属灵联结", "以家庭的爱待主的仆人如亲人"], "caution": [], "applications": ["珍惜家族与基督相连的属灵传承", "以亲情般的爱接待、照顾主的工人", "相信一次相遇能把全家带进主的拣选"], "scriptures": ["罗16:13"]}, {"name": "亚逊其土", "lesson": "名字被记在问安里", "witness": "亚逊其土是保罗在罗马书所问安的弟兄之一，与几位同被提名。圣经没有记下他的事迹，只记下他在主里、被使徒挂念的名字。在神的群体里，被记念、被挂念，本身就是恩典。", "summary": "保罗在罗马书所问安的弟兄之一。", "prayer": "主啊，亚逊其土的名字被记在问安里。求祢使我珍惜在祢群体中彼此记念的恩典，也主动去关心、问安肢体。阿们。", "tags": ["其他", "混合型"], "follow": ["在主里与肢体彼此挂念"], "caution": [], "applications": ["珍惜在主里被肢体记念、挂念的福分", "也主动去记念、问安身边的肢体", "相信无名却在主里的人，神都记念"], "scriptures": ["罗16:14"]}, {"name": "弗勒干", "lesson": "问安名单中忠心的弟兄", "witness": "弗勒干是保罗在罗马书问安的弟兄之一，与几位同被提名。圣经没有更多记载，他却被使徒在主里挂念。许多忠心的肢体，事迹无传，名字却留在神的群体与圣经里——这已是莫大的恩典。", "summary": "保罗在罗马书所问安的弟兄之一。", "prayer": "主啊，弗勒干被记在问安里。求祢使我在祢的群体中忠心，珍惜彼此记念的恩典，也去关心不起眼的肢体。阿们。", "tags": ["其他", "混合型"], "follow": ["在主的群体中忠心、彼此联络"], "caution": [], "applications": ["珍惜在主里被记念的福分", "主动去问安、联络平凡的肢体", "相信无名而忠心的人，神都记念"], "scriptures": ["罗16:14"]}, {"name": "黑米", "lesson": "问安名单中的弟兄", "witness": "黑米是保罗在罗马书问安的弟兄之一（名字源自希腊神祇之名，常是奴仆之名）。他不显赫，却与几位弟兄一同被使徒在主里记念。出身、名字的卑微，丝毫不减他在基督身体里被珍视的分量。", "summary": "保罗在罗马书所问安的弟兄之一。", "prayer": "主啊，黑米虽出身卑微，也在祢里被记念。求祢使我珍惜在祢身体里彼此记念的恩典，以平等的爱待每一位肢体。阿们。", "tags": ["其他", "混合型"], "follow": ["在主里彼此联络、被记念，不论出身"], "caution": [], "applications": ["珍惜在主里被记念的恩典，不看出身", "以平等的爱待不同背景的肢体", "主动问安、关心不起眼的弟兄"], "scriptures": ["罗16:14"]}, {"name": "八罗巴", "lesson": "问安名单里被记念的肢体", "witness": "八罗巴是保罗在罗马书问安的弟兄之一，与几位同被提名。圣经没有更多记载，他却被使徒在主里挂念、问安。在基督的身体里，没有一个肢体是被遗忘的——哪怕只留下一个名字。", "summary": "保罗在罗马书所问安的弟兄之一。", "prayer": "主啊，八罗巴的名字被记在问安里。求祢使我珍惜在祢身体里彼此记念的恩典，也去关心那些不起眼的肢体。阿们。", "tags": ["其他", "混合型"], "follow": ["在主的身体里彼此联络、挂念"], "caution": [], "applications": ["珍惜在基督身体里被记念的福分", "主动去问安、联络不起眼的肢体", "相信每个在主里的人都被神记念"], "scriptures": ["罗16:14"]}, {"name": "黑马", "lesson": "一同被问安的弟兄", "witness": "黑马是保罗在罗马书问安的弟兄之一，与黑米、八罗巴等一同被提名，可能同属一个聚会。圣经只留下他的名字，他却与众弟兄一同被使徒挂念。在基督里，一个被记念的名字，就承载着一份归属与恩典。", "summary": "保罗在罗马书所问安的弟兄之一。", "prayer": "主啊，黑马与众弟兄一同被记在问安里。求祢使我珍惜在祢群体中的归属与彼此记念，也去关心、问安身边的肢体。阿们。", "tags": ["其他", "混合型"], "follow": ["在主的群体中归属、被记念"], "caution": [], "applications": ["珍惜在主里被记念、有归属的福分", "看重小组、聚会中的彼此联络", "主动去记念、问安身边的弟兄"], "scriptures": ["罗16:14"]}, {"name": "非罗罗古", "lesson": "一同被记念的圣徒", "witness": "非罗罗古是保罗在罗马书末了问安的圣徒之一，与犹利亚、尼利亚等一同被提名，可能同属一个家庭或聚会。他的事迹无传，却在使徒的挂念与圣经的记载中留下了名字——在基督里被记念，就是福分。", "summary": "保罗在罗马书所问安的圣徒之一。", "prayer": "主啊，非罗罗古与众圣徒一同被记在问安里。求祢使我珍惜在祢里彼此记念、彼此联络的恩典，关心身边的肢体。阿们。", "tags": ["其他", "混合型"], "follow": ["在群体与家庭聚会中彼此联络"], "caution": [], "applications": ["珍惜在主里被记念的恩典", "看重家庭、小组式的聚会与联络", "主动去问安、记念身边的肢体"], "scriptures": ["罗16:15"]}, {"name": "犹利亚", "lesson": "问安里的一位姊妹", "witness": "犹利亚是保罗在罗马书问安的姊妹之一，与几位圣徒同被提名。她的事迹无传，名字却被圣灵记在书信里。在基督的身体中，姊妹们默默的同在与服事，同样被神看重、被使徒挂念。", "summary": "保罗在罗马书所问安的姊妹。", "prayer": "主啊，犹利亚被记在问安里。求祢使我珍惜在祢群体中彼此记念的恩典，看重每一位默默服事的姊妹。阿们。", "tags": ["女性", "混合型"], "follow": ["在群体中默默同在、彼此联络"], "caution": [], "applications": ["珍惜在主里被记念的福分", "看重姊妹们在群体中的同在与服事", "主动问安、关心身边的姊妹"], "scriptures": ["罗16:15"]}, {"name": "尼利亚", "lesson": "罗马教会被问安的圣徒", "witness": "尼利亚是保罗在罗马书末了问安的圣徒之一，与他的姊妹同被提名。圣经没有记下他的事迹，只把他的名字留在了使徒的挂念里。在主的群体中，一个被记念的名字，就是一份恩典。", "summary": "保罗在罗马书所问安的圣徒之一。", "prayer": "主啊，尼利亚的名字被记在问安里。求祢使我珍惜在祢群体中彼此记念的恩典，也去关心、问安身边的肢体。阿们。", "tags": ["其他", "混合型"], "follow": ["在主的群体中被联络、被记念"], "caution": [], "applications": ["珍惜在基督群体里被记念的福分", "主动去问安、关心不起眼的肢体", "相信无名的圣徒，神都记念"], "scriptures": ["罗16:15"]}, {"name": "阿林巴", "lesson": "问安名单里的圣徒", "witness": "阿林巴是保罗在罗马书末了问安的圣徒之一，与几位同被提名。圣经没有记下他的事迹，他却与众圣徒一同被使徒在主里记念。在基督的身体里，与众圣徒同被记念，本身就是恩典。", "summary": "保罗在罗马书所问安的圣徒之一。", "prayer": "主啊，阿林巴与众圣徒一同被记念。求祢使我珍惜在祢身体里彼此相连、彼此记念的恩典，也去关心身边的肢体。阿们。", "tags": ["其他", "混合型"], "follow": ["与众圣徒一同在主里被记念"], "caution": [], "applications": ["珍惜在主里与众圣徒相连的福分", "主动问安、记念身边的肢体", "相信无名的圣徒，神都看见"], "scriptures": ["罗16:15"]}, {"name": "该犹", "lesson": "接待全教会的人", "witness": "该犹是哥林多的信徒，保罗称他'接待我，也接待全教会'。他敞开自己的家，成了使徒与众圣徒聚集、受接待的地方。一个慷慨好客的家，能托住一整个群体的团契——好客是看得见的爱。", "summary": "接待保罗与全教会的人。", "prayer": "主啊，该犹接待了保罗和全教会。求祢使我也敞开所有，以好客接待祢的仆人与肢体，作托住团契的人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["敞开家门接待使徒与众圣徒", "以好客托住群体的团契"], "caution": [], "applications": ["以好客接待主的仆人与肢体", "把自己的家、资源向团契敞开", "看好客为爱主爱人的实际"], "scriptures": ["罗16:23"]}, {"name": "以拉都", "lesson": "身居公职，也作主的同工", "witness": "以拉都是哥林多城管银库的官员，也是保罗的同工，曾被差往马其顿服事。他一面担着城里的公职，一面参与神国的工作。信仰与公职并非冲突——在权责的岗位上，也能忠心事主。", "summary": "哥林多城管银库的信徒。", "prayer": "主啊，以拉都身居公职，也作祢的同工。求祢使我在职业岗位上忠心事奉祢，让我的身份成为服事祢国的平台。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在公职与世俗岗位上忠心事主", "把职业身份用于服事神国"], "caution": [], "applications": ["在你的职业、公职岗位上活出信仰", "让世俗的身份成为服事的平台", "平衡公职责任与神国的参与"], "scriptures": ["罗16:23"]}, {"name": "所西巴德", "lesson": "保罗的亲属与同工", "witness": "所西巴德是保罗的亲属，与他一同问安罗马的信徒，也是宣教队伍中的同工。他既有血缘的亲情，又有同工的情谊，把家族关系活成了一同事奉主的关系。", "summary": "保罗的亲属与同工。", "prayer": "主啊，所西巴德既是保罗的亲属，也是同工。求祢使我带动家人一同事奉祢，把血缘的情分活成同工的情谊。阿们。", "tags": ["其他", "正面榜样"], "follow": ["把家族关系活成一同事奉的关系", "作可靠的亲属兼同工"], "caution": [], "applications": ["邀请、带动家人一同参与神的工作", "把亲情提升为同工的情谊", "在亲属中作信仰的带动者"], "scriptures": ["罗16:21"]}, {"name": "耶孙", "lesson": "为接待信徒，甘担风险", "witness": "耶孙在帖撒罗尼迦接待了保罗一行。当暴民找不到保罗，就把耶孙拉到官长面前，他被迫取了保状才得释放。接待福音的使者，他付上了被牵连、担风险的代价。好客而担当，是初代信徒可贵的品格。", "summary": "接待保罗、在帖撒罗尼迦受牵连的信徒。", "prayer": "主啊，耶孙接待保罗、甘担风险。求祢使我以好客接待祢的仆人，在需要时甘心承担、不怕牵连，以行动爱祢爱人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["接待福音的使者，甘愿担当风险", "为他人挺身、付上代价"], "caution": [], "applications": ["以好客接待主的工人，不怕牵连", "在别人受难时甘愿承担一份风险", "看接待与担当为爱主的实际"], "scriptures": ["罗16:21,徒17:5-9"]}, {"name": "路求", "lesson": "安提阿的领袖，差传的根基", "witness": "路求是古利奈人，安提阿教会的先知与教师之一。正是这个由不同背景之人组成的团队，在禁食祷告、事奉主时，被圣灵分派，差出了巴拿巴与扫罗——开启了向外邦的宣教。差传的伟大行动，始于一群安静事奉、寻求神的领袖。", "summary": "保罗的亲属与同工。", "prayer": "主啊，路求与同工在安提阿事奉祷告，差出了宣教士。求祢使我在事奉与祷告中寻求祢的差遣，甘作差传背后安静的根基。阿们。", "tags": ["其他", "正面榜样"], "follow": ["在事奉与祷告中寻求神的差遣", "作差传背后安静而关键的根基"], "caution": [], "applications": ["以事奉、禁食、祷告寻求神的带领", "看重'差出去'背后的祷告团队", "甘作宣教大业背后安静的根基"], "scriptures": ["罗16:21"]}, {"name": "推基古", "lesson": "忠心的信使，传递与代表", "witness": "推基古是保罗'所亲爱的弟兄、忠心的执事、一同作仆人的'。他为保罗递送以弗所书、歌罗西书，又把保罗的景况告诉众教会，还几次被差去代表保罗。忠心可靠的传递者，使福音的网络得以连通。", "summary": "保罗所差派传递书信的亲爱弟兄。", "prayer": "主啊，推基古是忠心的信使，连通了众教会。求祢使我作忠心可靠的传递者，在联络与代表的事上尽忠，连通肢体。阿们。", "tags": ["其他", "正面榜样"], "follow": ["作忠心可靠的信使与代表", "在传递、联络中尽忠"], "caution": [], "applications": ["在传递信息、代表他人的事上忠心可靠", "以联络、沟通的服事连通肢体", "作'所亲爱、忠心'的那种同工"], "scriptures": ["弗6:21,西4:7"]}, {"name": "阿尼色弗", "lesson": "不以锁链为耻，屡次使人畅快", "witness": "阿尼色弗是保罗特别感念的同工。保罗下在罗马监里，别人都退避，他却'屡次使我畅快，不以我的锁链为耻'，还殷勤地找着了被囚的保罗。在患难、羞辱临到时仍不离不弃、主动寻找的爱，何等宝贵。", "summary": "多次使保罗畅快、不以锁链为耻的人。", "prayer": "主啊，阿尼色弗不以保罗的锁链为耻，屡次使他畅快。求祢使我在人受苦蒙羞时不退避，主动寻找、探望，成为使人畅快的安慰。阿们。", "tags": ["其他", "正面榜样"], "follow": ["不以受苦之人的'锁链'为耻", "屡次主动寻找、使人畅快"], "caution": [], "applications": ["在朋友受难、蒙羞时不退避", "主动去寻找、探望被囚被弃的人", "作'屡次使人畅快'的安慰者"], "scriptures": ["提后1:16"]}, {"name": "以巴弗", "lesson": "为人竭力祷告的忠仆", "witness": "以巴弗是歌罗西教会忠心的执事，把福音带给他们，又'在祷告中常为你们竭力祈求'，愿他们在神旨意上站立得稳、得以完全。他不在身边时，就以恒切的代祷牧养所爱的群体。", "summary": "歌罗西教会忠心的执事，常为信徒竭力祷告。", "prayer": "主啊，以巴弗为歌罗西人竭力祷告。求祢使我也成为恒切代祷的人，为我所爱的人在祢面前竭力祈求，愿他们站立得稳。阿们。", "tags": ["其他", "正面榜样"], "follow": ["为所牧养、所爱的人恒切竭力祷告", "忠心传福音、建立群体"], "caution": ["事工的果效在于祷告，不可忽略"], "applications": ["为你所牵挂的人列名恒切代祷", "以祷告而非只靠方法来牧养、关怀", "在看不见的祷告里忠心摆上"], "scriptures": ["西1:7,4:12"]}, {"name": "以巴弗提", "lesson": "为主的工，几乎不顾性命", "witness": "以巴弗提是腓立比教会差来供应保罗的使者。他为基督的工作'几乎至死，不顾性命'，病重几乎丧命。保罗称他为'弟兄、同工、同当兵'的，嘱咐众人尊重这样的人。摆上到不顾性命的服事，最当被敬重。", "summary": "腓立比教会差遣供应保罗、几乎至死的同工。", "prayer": "主啊，以巴弗提为祢的工几乎不顾性命。求祢使我也甘心为祢尽心摆上，忠心完成所托，也使我尊重这样拼命服事的人。阿们。", "tags": ["其他", "正面榜样"], "follow": ["为主的工尽心竭力，甚至不顾性命", "忠心完成所受差遣的供应使命"], "caution": [], "applications": ["在服事上甘心付代价、尽心竭力", "尊重那些为主拼命摆上的同工", "忠心完成受托的任务，不半途退缩"], "scriptures": ["腓2:25"]}, {"name": "亚基布", "lesson": "务要谨慎，尽你的职分", "witness": "亚基布是歌罗西/腓利门家中的同工。保罗特地嘱咐他：务要谨慎，尽你从主所受的职分。这句简短的提醒，适用于每一个领受了服事的人——领受了，就当尽心尽力地完成。", "summary": "被嘱咐要谨慎尽职的同工。", "prayer": "主啊，祢藉保罗嘱咐亚基布尽他的职分。求祢使我谨慎对待祢所托付的服事，尽心竭力，不懈怠、不半途而废。阿们。", "tags": ["其他", "正面榜样"], "follow": ["谨慎对待、尽心完成从主所受的职分"], "caution": ["不可懈怠、半途而废所受的托付"], "applications": ["认真对待主交托给你的服事职分", "不懈怠、不半途而废", "常自省：我尽了从主所受的职分吗？"], "scriptures": ["西4:17,门2"]}]$json$::jsonb)
  AS x(name text, lesson text, witness text, summary text, prayer text,
       tags jsonb, follow jsonb, caution jsonb, applications jsonb, scriptures jsonb);

-- 1) main fields
UPDATE biblical_characters c
SET lesson = LEFT(d.lesson, 200), witness = d.witness, summary = d.summary,
    prayer = d.prayer, updated_at = NOW()
FROM _card_sync d
WHERE c.name = d.name AND c.is_active = true;

-- 2) tags
INSERT INTO character_tags (character_id, tag)
SELECT c.id, t.tag
FROM _card_sync d
JOIN biblical_characters c ON c.name = d.name AND c.is_active = true,
     LATERAL jsonb_array_elements_text(d.tags) AS t(tag)
ON CONFLICT (character_id, tag) DO NOTHING;

-- 3) follow points
INSERT INTO character_follow_points (character_id, content, sort_order)
SELECT c.id, e.content, e.ord
FROM _card_sync d
JOIN biblical_characters c ON c.name = d.name AND c.is_active = true,
     LATERAL jsonb_array_elements_text(d.follow) WITH ORDINALITY AS e(content, ord)
WHERE NOT EXISTS (SELECT 1 FROM character_follow_points f
                  WHERE f.character_id = c.id AND f.content = e.content);

-- 4) caution points
INSERT INTO character_caution_points (character_id, content, sort_order)
SELECT c.id, e.content, e.ord
FROM _card_sync d
JOIN biblical_characters c ON c.name = d.name AND c.is_active = true,
     LATERAL jsonb_array_elements_text(d.caution) WITH ORDINALITY AS e(content, ord)
WHERE NOT EXISTS (SELECT 1 FROM character_caution_points f
                  WHERE f.character_id = c.id AND f.content = e.content);

-- 5) applications
INSERT INTO character_applications (character_id, content, sort_order)
SELECT c.id, e.content, e.ord
FROM _card_sync d
JOIN biblical_characters c ON c.name = d.name AND c.is_active = true,
     LATERAL jsonb_array_elements_text(d.applications) WITH ORDINALITY AS e(content, ord)
WHERE NOT EXISTS (SELECT 1 FROM character_applications f
                  WHERE f.character_id = c.id AND f.content = e.content);

-- 6) scriptures
INSERT INTO character_scriptures (character_id, reference, sort_order)
SELECT c.id, e.reference, e.ord
FROM _card_sync d
JOIN biblical_characters c ON c.name = d.name AND c.is_active = true,
     LATERAL jsonb_array_elements_text(d.scriptures) WITH ORDINALITY AS e(reference, ord)
WHERE NOT EXISTS (SELECT 1 FROM character_scriptures f
                  WHERE f.character_id = c.id AND f.reference = e.reference);

-- End of 0067.
